passing_property:
// Sample combinational behavior on an external clock; the RTL has no reset.

    // Y matches the implemented O21BAI gate equation.
    check_output_matches_gate_equation: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~((~B1_N) & (A1 | A2))
    );

// B1_N high forces the output high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0) B1_N |-> Y
    );

// Both A inputs low force the output high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !A2) |-> Y
    );

// A1 high with active-low B input forces the output low.
    check_a1_high_and_b1n_low_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A1) |-> !Y
    );

// A2 high with active-low B input forces the output low.
    check_a2_high_and_b1n_low_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A2) |-> !Y
    );

// A low output requires B1_N to be low.
    check_y_low_requires_b1n_low: assert property (
        @(posedge clk) disable iff (1'b0) !Y |-> !B1_N
    );

// A low output requires at least one A input high.
    check_y_low_requires_a_input_high: assert property (
        @(posedge clk) disable iff (1'b0) !Y |-> (A1 | A2)
    );

// With B1_N low, a high output requires both A inputs low.
    check_y_high_with_b1n_low_requires_a_inputs_low: assert property (
        @(posedge clk) disable iff (1'b0) (Y && !B1_N) |-> (!A1 && !A2)
    );

// RTL has no reset; all checks are sampled on clk.

    // y must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) y == ((a & ~sel) | (b & sel))
    );

// When sel is low, y follows a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (y == a)
    );

// When sel is high, y follows b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (y == b)
    );

// If both inputs are low, y is low.
    check_both_inputs_low: assert property (
        @(posedge clk) ((a == 1'b0) && (b == 1'b0)) |-> (y == 1'b0)
    );

// If both inputs are high, y is high.
    check_both_inputs_high: assert property (
        @(posedge clk) ((a == 1'b1) && (b == 1'b1)) |-> (y == 1'b1)
    );

// Output matches the implemented nested mux expression.
    check_output_matches_mux_tree: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? data3 : data2) : (sel[0] ? data1 : data0))
    );

// sel=00 routes data0 to the output.
    check_sel_00_routes_data0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == data0)
    );

// sel=01 routes data1 to the output.
    check_sel_01_routes_data1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == data1)
    );

// sel=10 routes data2 to the output.
    check_sel_10_routes_data2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == data2)
    );

// sel=11 routes data3 to the output.
    check_sel_11_routes_data3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == data3)
    );

// Len_int matches the implemented OR-of-products equation.
    check_len_equation: assert property (
        @(posedge clk)
        Len_int == ((n63 & Z_B) | ((~n63) & (~Z_B) & (~n62)))
    );

// Ren_int matches the implemented OR-of-products equation.
    check_ren_equation: assert property (
        @(posedge clk)
        Ren_int == ((Z_B & n62) | ((~n63) & (~Z_B) & (~n62)))
    );

// When Z_B is high, the outputs follow n63 and n62 directly.
    check_outputs_follow_inputs_when_zb_high: assert property (
        @(posedge clk)
        Z_B |-> ((Len_int == n63) && (Ren_int == n62))
    );

// When Z_B is low, both outputs reduce to !n63 & !n62.
    check_outputs_when_zb_low: assert property (
        @(posedge clk)
        (!Z_B) |-> ((Len_int == ((!n63) && (!n62))) && (Ren_int == ((!n63) && (!n62))))
    );

// With Z_B low, any high input forces both outputs low.
    check_outputs_low_when_zb_low_and_any_input_high: assert property (
        @(posedge clk)
        ((!Z_B) && (n63 || n62)) |-> ((!Len_int) && (!Ren_int))
    );

// With all three inputs low, both outputs must be high.
    check_outputs_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((!Z_B) && (!n63) && (!n62)) |-> (Len_int && Ren_int)
    );

// gray[3] is a direct copy of bin[3].
    check_gray_bit3_passthrough: assert property (
        @(posedge clk) gray[3] == bin[3]
    );

// gray[2] is bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray[2] == (bin[3] ^ bin[2])
    );

// gray[1] is bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray[1] == (bin[2] ^ bin[1])
    );

// gray[0] is bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray[0] == (bin[1] ^ bin[0])
    );

// The full gray output matches the implemented conversion.
    check_gray_vector_conversion: assert property (
        @(posedge clk) gray == {bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0])}
    );

// A sampled reset leaves the counter at zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// An enabled cycle increments the counter by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (q == ($past(q) + 4'b0001))
    );

// A disabled cycle holds the counter value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (q == $past(q))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (q == 4'b1111)) |=> (q == 4'b0000)
    );

// Outputs must match the full 5-bit addition result.
    check_full_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// No-overflow additions must produce no carry out.
    check_no_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) <= 5'd15)
        |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b} + cin) && cout == 1'b0)
    );

// Overflow additions must wrap the low 4 bits and set carry out.
    check_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
        |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b} + cin) - 5'd16) && cout == 1'b1)
    );

// All-zero inputs must produce a zero result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0)
        |-> (sum == 4'h0 && cout == 1'b0)
    );

// Maximum inputs must produce 0xF with carry out set.
    check_max_inputs: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1)
        |-> (sum == 4'hF && cout == 1'b1)
    );

// Opcode 00 produces the low 8 bits of the sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ({1'b0, result} == (({1'b0, num1} + {1'b0, num2}) & 9'h0ff))
    );

// Opcode 01 produces the low 8 bits of the difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ({1'b0, result} == (({1'b0, num1} - {1'b0, num2}) & 9'h0ff))
    );

// X must equal the AND of A1, A2, B1, and VPWR.
    check_x_matches_and: assert property (
        @(posedge clk) X == (A1 & A2 & B1 & VPWR)
    );

// When all functional inputs are high, X must be high.
    check_x_high_when_all_inputs_high: assert property (
        @(posedge clk) (A1 && A2 && B1 && VPWR) |-> X
    );

// If any functional input is low, X must be low.
    check_x_low_when_any_input_low: assert property (
        @(posedge clk) ((!A1) || (!A2) || (!B1) || (!VPWR)) |-> !X
    );

// A high X implies all functional inputs are high.
    check_x_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A1 && A2 && B1 && VPWR)
    );

// Output must be the AND of A and SLEEP_B.
    check_output_function: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// Low SLEEP_B must force X low.
    check_sleep_low_forces_zero: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When enabled, X must match A.
    check_enabled_output_follows_input: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A high X requires both A and SLEEP_B high.
    check_output_high_requires_enable_and_input: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// A low input must force X low.
    check_low_input_forces_zero: assert property (
        @(posedge clk) !A |-> !X
    );

// Y implements the AOI221 combinational equation.
    check_function_equation: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the output low.
    check_c1_forces_output_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the output low.
    check_a_and_pair_forces_output_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force the output low.
    check_b_and_pair_forces_output_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// All three NOR inputs low drive the output high.
    check_all_nor_inputs_low_drive_output_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high output requires all three NOR inputs to be low.
    check_output_high_requires_all_nor_inputs_low: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// A low output requires at least one NOR input to be high.
    check_output_low_requires_any_nor_input_high: assert property (
        @(posedge clk) !Y |-> (C1 || (A1 && A2) || (B1 && B2))
    );

// Combinational RTL with no reset; sample behavior on clk.

    // The eight 6-bit outputs reconstruct the full XOR result.
    check_full_xor_mapping: assert property (
        @(posedge clk) {b8x, b7x, b6x, b5x, b4x, b3x, b2x, b1x} == (k ^ e)
    );

// b1x carries XOR bits [5:0].
    check_b1x_slice: assert property (
        @(posedge clk) b1x == (k[5:0] ^ e[5:0])
    );

// b2x carries XOR bits [11:6].
    check_b2x_slice: assert property (
        @(posedge clk) b2x == (k[11:6] ^ e[11:6])
    );

// b3x carries XOR bits [17:12].
    check_b3x_slice: assert property (
        @(posedge clk) b3x == (k[17:12] ^ e[17:12])
    );

// b4x carries XOR bits [23:18].
    check_b4x_slice: assert property (
        @(posedge clk) b4x == (k[23:18] ^ e[23:18])
    );

// b5x carries XOR bits [29:24].
    check_b5x_slice: assert property (
        @(posedge clk) b5x == (k[29:24] ^ e[29:24])
    );

// b6x carries XOR bits [35:30].
    check_b6x_slice: assert property (
        @(posedge clk) b6x == (k[35:30] ^ e[35:30])
    );

// b7x carries XOR bits [41:36].
    check_b7x_slice: assert property (
        @(posedge clk) b7x == (k[41:36] ^ e[41:36])
    );

// b8x carries XOR bits [47:42].
    check_b8x_slice: assert property (
        @(posedge clk) b8x == (k[47:42] ^ e[47:42])
    );

// s_axi_wready is hardwired high.
    check_wready_constant_high: assert property (
        @(posedge s_aclk) s_axi_wready == 1'b1
    );

// E can only assert when s_axi_wvalid is high.
    check_e_requires_wvalid: assert property (
        @(posedge s_aclk) E[0] |-> s_axi_wvalid
    );

// Without s_axi_wvalid, both observable outputs driven by the full flag stay low.
    check_no_wvalid_forces_outputs_low: assert property (
        @(posedge s_aclk) !s_axi_wvalid |-> (!E[0] && !ram_full_fb_i_reg_0)
    );

// The feedback output is E gated by Q and the read pointer bit.
    check_feedback_output_equation: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 == (E[0] & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0])
    );

// The feedback output can only assert when E is asserted.
    check_feedback_requires_e: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 |-> E[0]
    );

// Loading a 1 into the internal flag makes E track s_axi_wvalid on the next cycle.
    check_load_one_makes_e_track_wvalid: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (E[0] == s_axi_wvalid)
    );

// Loading a 1 into the internal flag makes the feedback output track its gates next cycle.
    check_load_one_makes_feedback_track_gates: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (ram_full_fb_i_reg_0 == (s_axi_wvalid & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0]))
    );

// Loading a 0 into the internal flag clears both observable outputs on the next cycle.
    check_load_zero_clears_outputs: assert property (
        @(posedge s_aclk)
        (!out && !gic0_gc0_count_d1_reg_3) |=> (!E[0] && !ram_full_fb_i_reg_0)
    );

// No clock or reset exists in the DUT; clk is an external sampling clock.
    // The DUT is purely combinational and implements a 4-input OR.

    // Output must equal the OR of all four inputs.
    check_output_matches_or: assert property (
        @(posedge clk)
        output1 === (input1 | input2 | input3 | input4)
    );

// Any asserted input must drive the output high.
    check_any_high_sets_output: assert property (
        @(posedge clk)
        ((input1 | input2 | input3 | input4) === 1'b1) |-> (output1 === 1'b1)
    );

// All deasserted inputs must drive the output low.
    check_all_low_clears_output: assert property (
        @(posedge clk)
        (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0) |-> (output1 === 1'b0)
    );

// A high output requires at least one high input.
    check_output_high_implies_input_high: assert property (
        @(posedge clk)
        (output1 === 1'b1) |-> ((input1 | input2 | input3 | input4) === 1'b1)
    );

// A low output requires all inputs to be low.
    check_output_low_implies_all_inputs_low: assert property (
        @(posedge clk)
        (output1 === 1'b0) |-> (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0)
    );

// The output never uses the unused 2'b11 encoding.
    check_output_encoding: assert property (
        @(posedge clk) (output_value != 2'b11)
    );

// Reset clears both registered outputs by the next sampled cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (out == 1'b0)
    );

// Outside reset, count increments by one every cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (count == ($past(count) + 4'd1))
    );

// Outside reset, out toggles every cycle.
    check_out_toggles: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (out == ~$past(out))
    );

// Outside reset, count wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (!reset && (count == 4'hF)) |=> (count == 4'h0)
    );

// serial_out is the zero-extended LSB of the register.
    check_serial_out_mapping: assert property (
        @(posedge clk) serial_out == {7'b0, parallel_out[0]}
    );

// parallel_load loads data_in into the register on the next cycle.
    check_parallel_load_updates_register: assert property (
        @(posedge clk) parallel_load |=> parallel_out == $past(data_in)
    );

// parallel_load also updates serial_out to the loaded bit 0 on the next cycle.
    check_parallel_load_updates_serial: assert property (
        @(posedge clk) parallel_load |=> serial_out == {7'b0, $past(data_in[0])}
    );

// With no load, shift_dir=1 shifts the register left and inserts 0 in bit 0.
    check_left_shift_updates_register: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> parallel_out == {$past(parallel_out[6:0]), 1'b0}
    );

// A left shift forces serial_out to zero on the next cycle.
    check_left_shift_clears_serial_out: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> serial_out == 8'h00
    );

// With no load, shift_dir=0 shifts the register right and inserts 0 in bit 7.
    check_right_shift_updates_register: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> parallel_out == {1'b0, $past(parallel_out[7:1])}
    );

// A right shift makes serial_out equal the prior bit 1 on the next cycle.
    check_right_shift_updates_serial: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> serial_out == {7'b0, $past(parallel_out[1])}
    );

// External sampling clock for this combinational DUT.

    // When disabled, the output is forced to zero.
    check_disabled_forces_zero: assert property (
        @(posedge clk) (en === 1'b0) |-> (out === 4'b0000)
    );

// With sel=00 and enable high, out follows in0.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ((sel === 2'b00) && (en === 1'b1)) |-> (out === in0)
    );

// With sel=01 and enable high, out follows in1.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ((sel === 2'b01) && (en === 1'b1)) |-> (out === in1)
    );

// With sel=10 and enable high, out follows in2.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ((sel === 2'b10) && (en === 1'b1)) |-> (out === in2)
    );

// With sel=11 and enable high, out follows in3.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ((sel === 2'b11) && (en === 1'b1)) |-> (out === in3)
    );

// Any non-matching select value drives the default zero output.
    check_invalid_sel_defaults_zero: assert property (
        @(posedge clk)
        !((sel === 2'b00) || (sel === 2'b01) || (sel === 2'b10) || (sel === 2'b11))
        |-> (out === 4'b0000)
    );

// X matches the implemented O211 logic function.
    check_function_exact: assert property (
        @(posedge clk) X == (((A1 | A2) & B1) & C1)
    );

// Low B1 forces the AND output low.
    check_b1_gates_output_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Low C1 forces the AND output low.
    check_c1_gates_output_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// With both OR inputs low, the output must be low.
    check_or_inputs_low_force_output_low: assert property (
        @(posedge clk) !(A1 | A2) |-> !X
    );

// A1 can drive X high when both gating inputs are high.
    check_a1_path_drives_high: assert property (
        @(posedge clk) (A1 & B1 & C1) |-> X
    );

// A2 can drive X high when both gating inputs are high.
    check_a2_path_drives_high: assert property (
        @(posedge clk) (A2 & B1 & C1) |-> X
    );

// High X requires B1 to be high.
    check_output_high_implies_b1: assert property (
        @(posedge clk) X |-> B1
    );

// High X requires C1 to be high.
    check_output_high_implies_c1: assert property (
        @(posedge clk) X |-> C1
    );

// High X requires at least one OR input to be high.
    check_output_high_implies_or_term: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// Sampling clock only; the DUT itself has no clock or reset.

    // When disabled, all outputs are HIGH.
    check_disabled_all_high: assert property (
        @(posedge clk) !ena |-> (out == 16'hFFFF)
    );

// When enabled, the selected output bit is LOW.
    check_enabled_selected_bit_low: assert property (
        @(posedge clk) ena |-> (out[in] == 1'b0)
    );

// When enabled, all non-selected output bits are HIGH.
    check_enabled_unselected_bits_high: assert property (
        @(posedge clk) ena |-> ((out | (16'h0001 << in)) == 16'hFFFF)
    );

// When enabled, the full active-low decode matches the input value.
    check_enabled_decode_map: assert property (
        @(posedge clk) ena |-> (out == ~(16'h0001 << in))
    );

// Y matches the gate-level structure in the RTL.
    check_y_matches_structure: assert property (
        @(posedge clk) Y == ~((~(A2 & A1)) & (~(B2 & B1)))
    );

// Y simplifies to the OR of the two input pairs.
    check_y_matches_simplified_function: assert property (
        @(posedge clk) Y == ((A1 & A2) | (B1 & B2))
    );

// A1 and A2 both high force Y high.
    check_a_pair_drives_y_high: assert property (
        @(posedge clk) (A1 & A2) |-> Y
    );

// B1 and B2 both high force Y high.
    check_b_pair_drives_y_high: assert property (
        @(posedge clk) (B1 & B2) |-> Y
    );

// If neither pair is fully high, Y must be low.
    check_no_complete_pair_drives_y_low: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !Y
    );

// A low Y means neither input pair is fully high.
    check_y_low_implies_no_complete_pair: assert property (
        @(posedge clk) !Y |-> (!(A1 & A2) && !(B1 & B2))
    );

// Counter state follows the RTL next-state function each cycle.
    check_next_state_matches_rtl: assert property (
        @(posedge clk)
        1'b1 |=> (out == ($past(load) ? 3'b000 :
                          ($past(up_down) ? ($past(out) + 3'b001) :
                                            ($past(out) - 3'b001))))
    );

// A load request clears the counter to zero on the next cycle.
    check_load_clears_out: assert property (
        @(posedge clk)
        load |=> (out == 3'b000)
    );

// With load low and up_down high, the counter increments by one.
    check_count_up: assert property (
        @(posedge clk)
        (!load && up_down) |=> (out == ($past(out) + 3'b001))
    );

// With load low and up_down low, the counter decrements by one.
    check_count_down: assert property (
        @(posedge clk)
        (!load && !up_down) |=> (out == ($past(out) - 3'b001))
    );

// Counting up wraps from 7 back to 0.
    check_count_up_wrap: assert property (
        @(posedge clk)
        (!load && up_down && (out == 3'b111)) |=> (out == 3'b000)
    );

// Counting down wraps from 0 back to 7.
    check_count_down_wrap: assert property (
        @(posedge clk)
        (!load && !up_down && (out == 3'b000)) |=> (out == 3'b111)
    );

// sel=0 maps to bit 0.
    check_decode_sel_0: assert property (
        @(posedge clk) (sel == 4'h0) |-> (out == 16'h0001)
    );

// sel=1 maps to bit 1.
    check_decode_sel_1: assert property (
        @(posedge clk) (sel == 4'h1) |-> (out == 16'h0002)
    );

// sel=2 maps to bit 2.
    check_decode_sel_2: assert property (
        @(posedge clk) (sel == 4'h2) |-> (out == 16'h0004)
    );

// sel=3 maps to bit 3.
    check_decode_sel_3: assert property (
        @(posedge clk) (sel == 4'h3) |-> (out == 16'h0008)
    );

// sel=4 maps to bit 4.
    check_decode_sel_4: assert property (
        @(posedge clk) (sel == 4'h4) |-> (out == 16'h0010)
    );

// sel=5 maps to bit 5.
    check_decode_sel_5: assert property (
        @(posedge clk) (sel == 4'h5) |-> (out == 16'h0020)
    );

// sel=6 maps to bit 6.
    check_decode_sel_6: assert property (
        @(posedge clk) (sel == 4'h6) |-> (out == 16'h0040)
    );

// sel=7 maps to bit 7.
    check_decode_sel_7: assert property (
        @(posedge clk) (sel == 4'h7) |-> (out == 16'h0080)
    );

// sel=8 maps to bit 8.
    check_decode_sel_8: assert property (
        @(posedge clk) (sel == 4'h8) |-> (out == 16'h0100)
    );

// sel=9 maps to bit 9.
    check_decode_sel_9: assert property (
        @(posedge clk) (sel == 4'h9) |-> (out == 16'h0200)
    );

// sel=10 maps to bit 10.
    check_decode_sel_a: assert property (
        @(posedge clk) (sel == 4'hA) |-> (out == 16'h0400)
    );

// sel=11 maps to bit 11.
    check_decode_sel_b: assert property (
        @(posedge clk) (sel == 4'hB) |-> (out == 16'h0800)
    );

// sel=12 maps to bit 12.
    check_decode_sel_c: assert property (
        @(posedge clk) (sel == 4'hC) |-> (out == 16'h1000)
    );

// sel=13 maps to bit 13.
    check_decode_sel_d: assert property (
        @(posedge clk) (sel == 4'hD) |-> (out == 16'h2000)
    );

// sel=14 maps to bit 14.
    check_decode_sel_e: assert property (
        @(posedge clk) (sel == 4'hE) |-> (out == 16'h4000)
    );

// sel=15 maps to bit 15.
    check_decode_sel_f: assert property (
        @(posedge clk) (sel == 4'hF) |-> (out == 16'h8000)
    );

// Unknown select values drive the default zero output.
    check_unknown_sel_default_zero: assert property (
        @(posedge clk) $isunknown(sel) |-> (out == 16'h0000)
    );

// Output is always one-hot or all zero.
    check_out_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

// q captures a 1 from d on the following clock edge.
    check_q_captures_high_d: assert property (
        @(posedge clk) d |=> q
    );

// q captures a 0 from d on the following clock edge.
    check_q_captures_low_d: assert property (
        @(posedge clk) !d |=> !q
    );

// Overall output matches the implemented 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

// sel=00 routes in0 to out.
    check_sel00_routes_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel01_routes_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel10_routes_in2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel11_routes_in3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in3)
    );

// sel[1]=0 selects between the lower input pair.
    check_lower_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

// sel[1]=1 selects between the upper input pair.
    check_upper_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

// When enabled, the next-cycle output matches the sampled input.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

// When disabled, the next-cycle output is forced low.
    check_drive_low_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

// Each cycle, the output follows the prior-cycle enable/data function.
    check_registered_output_function: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(en) ? $past(data_in) : 1'b0))
    );

// Output must always be the XOR of the two inputs.
    check_xor_function: assert property (
        @(posedge clk) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

// 0 ^ 0 must produce 0.
    check_xor_00_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b0)
    );

// 0 ^ 1 must produce 1.
    check_xor_01_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b1)
    );

// 1 ^ 0 must produce 1.
    check_xor_10_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b1)
    );

// 1 ^ 1 must produce 0.
    check_xor_11_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b0)
    );

// COUT must implement the AND of A and B.
    check_cout_matches_and: assert property (
        @(posedge clk) COUT === (A & B)
    );

// SUM must implement the XOR of A and B.
    check_sum_matches_xor: assert property (
        @(posedge clk) SUM === (A ^ B)
    );

// When both inputs are 0, both outputs must be 0.
    check_zero_plus_zero: assert property (
        @(posedge clk)
        ((A === 1'b0) && (B === 1'b0)) |-> ((COUT === 1'b0) && (SUM === 1'b0))
    );

// When exactly one input is 1, SUM must be 1 and COUT must be 0.
    check_one_hot_input_sum_only: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b1)) || ((A === 1'b1) && (B === 1'b0)))
        |-> ((COUT === 1'b0) && (SUM === 1'b1))
    );

// When both inputs are 1, COUT must be 1 and SUM must be 0.
    check_one_plus_one_carry_only: assert property (
        @(posedge clk)
        ((A === 1'b1) && (B === 1'b1)) |-> ((COUT === 1'b1) && (SUM === 1'b0))
    );

// Duty-cycle stabilizer output is tied high.
    check_adc_cdcs_constant_high: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_cdcs_o == 1'b1
    );

// ADC clock source output is tied to 2'b10.
    check_adc_clk_source_constant: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_clk_source == 2'b10
    );

// Channel A output matches the prior sampled input transform.
    check_adc_dat_a_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o == { $past(adc_dat_a_i[13]), ~$past(adc_dat_a_i[12:0]) })
    );

// Channel B output matches the prior sampled input transform.
    check_adc_dat_b_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o == { $past(adc_dat_b_i[13]), ~$past(adc_dat_b_i[12:0]) })
    );

// Channel A sign bit is preserved from the sampled input.
    check_adc_dat_a_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[13] == $past(adc_dat_a_i[13]))
    );

// Channel A lower bits are inverted from the sampled input.
    check_adc_dat_a_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[12:0] == ~$past(adc_dat_a_i[12:0]))
    );

// Channel B sign bit is preserved from the sampled input.
    check_adc_dat_b_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[13] == $past(adc_dat_b_i[13]))
    );

// Channel B lower bits are inverted from the sampled input.
    check_adc_dat_b_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[12:0] == ~$past(adc_dat_b_i[12:0]))
    );

// out matches the implemented combinational expression.
    check_out_matches_implemented_function: assert property (
        @(posedge clk) out == {(a[2] & b), (a[3] & b)}
    );

// The upper nibble is b masked by a[2].
    check_upper_nibble_matches_a2_mask: assert property (
        @(posedge clk) out[7:4] == (a[2] & b)
    );

// The lower nibble is b masked by a[3].
    check_lower_nibble_matches_a3_mask: assert property (
        @(posedge clk) out[3:0] == (a[3] & b)
    );

// Zero on b forces the full output low.
    check_zero_output_when_b_zero: assert property (
        @(posedge clk) (b == 4'h0) |-> (out == 8'h00)
    );

// Zero on a[3:2] forces the full output low.
    check_zero_output_when_a23_zero: assert property (
        @(posedge clk) (a[3:2] == 2'b00) |-> (out == 8'h00)
    );

// Input 00 selects only out0.
    check_decode_00: assert property (
        @(posedge clk) (in == 2'b00) |-> ({out3, out2, out1, out0} == 4'b0001)
    );

// Input 01 selects only out1.
    check_decode_01: assert property (
        @(posedge clk) (in == 2'b01) |-> ({out3, out2, out1, out0} == 4'b0010)
    );

// Input 10 selects only out2.
    check_decode_10: assert property (
        @(posedge clk) (in == 2'b10) |-> ({out3, out2, out1, out0} == 4'b0100)
    );

// Input 11 selects only out3.
    check_decode_11: assert property (
        @(posedge clk) (in == 2'b11) |-> ({out3, out2, out1, out0} == 4'b1000)
    );

// For any binary input, exactly one output is asserted.
    check_outputs_onehot: assert property (
        @(posedge clk)
        ((in == 2'b00) || (in == 2'b01) || (in == 2'b10) || (in == 2'b11))
        |-> $onehot({out3, out2, out1, out0})
    );

// A sampled active-low reset keeps the output low at the next clock sample.
    check_reset_forces_low_next_sample: assert property (
        @(posedge clk) !rst_n |=> (pwm_out == 1'b0)
    );

// The first sampled cycle after a sampled reset low still sees the output low.
    check_release_from_reset_starts_low: assert property (
        @(posedge clk) (($past(rst_n) === 1'b0) && (rst_n == 1'b1)) |-> (pwm_out == 1'b0)
    );

// A sampled high output must be low on the next clock sample.
    check_high_sample_falls_next_cycle: assert property (
        @(posedge clk) (pwm_out == 1'b1) |=> (pwm_out == 1'b0)
    );

// Any sampled high output must come from a previous low sample out of reset.
    check_high_sample_comes_from_prev_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (((($past(rst_n) === 1'b0) || ($past(rst_n) === 1'b1))) && (pwm_out == 1'b1))
        |-> (($past(rst_n) === 1'b1) && ($past(pwm_out) === 1'b0))
    );

// gt matches the OR of zero-extended bit positions where a is 1 and b is 0.
    check_gt_definition: assert property (
        @(posedge clk) gt == (|(({1'b0, a}) & ~({1'b0, b})))
    );

// lt matches the OR of zero-extended bit positions where a is 0 and b is 1.
    check_lt_definition: assert property (
        @(posedge clk) lt == (|(~({1'b0, a}) & ({1'b0, b})))
    );

// eq matches the AND of zero-extended bitwise equality results.
    check_eq_definition: assert property (
        @(posedge clk) eq == (&((({1'b0, a}) ~^ ({1'b0, b}))))
    );

// Equal inputs must drive eq high and both difference flags low.
    check_equal_inputs_outputs: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

// Different inputs must clear eq and assert at least one difference flag.
    check_different_inputs_outputs: assert property (
        @(posedge clk) (a != b) |-> (!eq && (gt || lt))
    );

// eq is asserted exactly when neither gt nor lt is asserted.
    check_eq_matches_no_gt_lt: assert property (
        @(posedge clk) eq == !(gt || lt)
    );

// gt can only be high when a and b differ.
    check_gt_indicates_difference: assert property (
        @(posedge clk) gt |-> (a != b)
    );

// lt can only be high when a and b differ.
    check_lt_indicates_difference: assert property (
        @(posedge clk) lt |-> (a != b)
    );

// Selector forces the state register to 00 on the next clock.
    check_selector_clears_state: assert property (
        @(posedge clk_IBUF_BUFG)
        FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// With selector low and AR low, state 00 holds.
    check_hold_00_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// With selector low and AR low, state 01 holds.
    check_hold_01_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

// With selector low and AR low, state 10 holds.
    check_hold_10_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

// With selector low and AR low, state 11 holds.
    check_hold_11_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

// With selector low and AR high, state 00 increments to 01.
    check_increment_00_to_01: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

// With selector low and AR high, state 01 increments to 10.
    check_increment_01_to_10: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

// With selector low and AR high, state 10 increments to 11.
    check_increment_10_to_11: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

// With selector low and AR high, state 11 wraps to 00.
    check_increment_11_to_00: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

///// Functional mapping /////
    // S implements A + (~B + 1), i.e., two's-complement subtraction.
    check_subtractor_function: assert property (
        @(posedge clk) S == (A + ((~B) + 32'd1))
    );

// Adding B back to S yields A (mod 2^32).
    check_add_back_B_yields_A: assert property (
        @(posedge clk) (S + B) == A
    );

// A minus S equals B (mod 2^32).
    check_A_minus_S_equals_B: assert property (
        @(posedge clk) A + ((~S) + 32'd1) == B
    );

///// Special cases /////
    // If inputs are equal, result is zero.
    check_equal_inputs_zero_output: assert property (
        @(posedge clk) (A == B) |-> (S == 32'd0)
    );

// If B is zero, S passes through A.
    check_zero_B_passthrough: assert property (
        @(posedge clk) (B == 32'd0) |-> (S == A)
    );

// If A is zero, S is two's complement of B.
    check_zero_A_twos_complement_B: assert property (
        @(posedge clk) (A == 32'd0) |-> (S == ((~B) + 32'd1))
    );

// If B is all ones, S equals A plus one (mod 2^32).
    check_B_all_ones_inc_A: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (S == (A + 32'd1))
    );

// LSB of result equals XOR of input LSBs.
    check_lsb_is_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

///// Reset behavior /////
  // At reset, internal registers are driven to 0.
  check_reset_regs_zero: assert property (
    @(posedge clk) !reset_n |-> (pwm_timer == 12'd0) && (fifo_rdreq == 1'b0) &&
                               (audiodata_32 == 32'd0) && (audiodata_32_p == 32'd0) &&
                               (data_rdy == 1'b0)
  );

// At reset, PWM outputs are HIGH (timer=0, thresholds=0).
  check_reset_pwm_out_high: assert property (
    @(posedge clk) !reset_n |-> (pwm_out_l == 1'b1) && (pwm_out_r == 1'b1)
  );

// rdreq deasserts one cycle after being observed high at 0x801.
  check_rdreq_clear_after_801: assert property (
    @(posedge clk) disable iff (!reset_n) (pwm_timer == 12'h801 && fifo_rdreq == 1'b1) |-> ##1 (fifo_rdreq == 1'b0)
  );

// rdreq pulse width is exactly one cycle.
  check_rdreq_one_cycle_pulse: assert property (
    @(posedge clk) disable iff (!reset_n) $rose(fifo_rdreq) |-> ##1 (!fifo_rdreq)
  );

// Left PWM is known when inputs to comparator are known.
  check_pwm_out_l_known_when_inputs_known: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({pwm_timer, audiodata_32[15:4]})) |-> (!$isunknown(pwm_out_l))
  );

// Right PWM is known when inputs to comparator are known.
  check_pwm_out_r_known_when_inputs_known: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({pwm_timer, audiodata_32[31:20]})) |-> (!$isunknown(pwm_out_r))
  );

// If left/right thresholds are equal, PWM outputs must match.
  check_pwms_equal_when_thresholds_equal: assert property (
    @(posedge clk) disable iff (!reset_n) (audiodata_32[15:4] == audiodata_32[31:20]) |-> (pwm_out_l == pwm_out_r)
  );

///// Functional mapping /////
    // Out must match the truth table for every input.
    check_truth_table: assert property (
        @(posedge clk) out == expected_out(in)
    );

///// Inverse mapping (consistency) /////
    // If out is 00, input must be 0000.
    check_inverse_out_00: assert property (
        @(posedge clk) (out == 2'b00) |-> (in == 4'b0000)
    );

// If out is 01, input must be one of single-bit-set values.
    check_inverse_out_01: assert property (
        @(posedge clk) (out == 2'b01) |-> (in inside {4'b0001,4'b0010,4'b0100,4'b1000})
    );

// If out is 10, input must be one of the specified seven values.
    check_inverse_out_10: assert property (
        @(posedge clk) (out == 2'b10) |-> (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100,4'b1111})
    );

// If out is 11, input must be one of the three-ones values.
    check_inverse_out_11: assert property (
        @(posedge clk) (out == 2'b11) |-> (in inside {4'b0111,4'b1011,4'b1101,4'b1110})
    );

///// Forward mapping by input classes /////
    // If input has exactly one bit set, out must be 01.
    check_onehot_implies_01: assert property (
        @(posedge clk) (in inside {4'b0001,4'b0010,4'b0100,4'b1000}) |-> (out == 2'b01)
    );

// If input has exactly two bits set, out must be 10.
    check_two_ones_implies_10: assert property (
        @(posedge clk) (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100}) |-> (out == 2'b10)
    );

// If input has exactly three bits set, out must be 11.
    check_three_ones_implies_11: assert property (
        @(posedge clk) (in inside {4'b0111,4'b1011,4'b1101,4'b1110}) |-> (out == 2'b11)
    );

// If input has zero bits set, out must be 00.
    check_zero_ones_implies_00: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

// If input has four bits set, out must be 10 (special case in RTL).
    check_four_ones_implies_10: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 2'b10)
    );

///// Output clear behavior /////
  // When clr is HIGH, op must be 0 in the same cycle.
  check_op_zero_when_clr_high: assert property (
    @(posedge clk) clr |-> (op == 1'b0)
  );

// If clr is HIGH in two consecutive cycles, op stays 0.
  check_op_zero_stable_while_clr_high: assert property (
    @(posedge clk) ($past(clr) && clr) |-> (op == 1'b0)
  );

///// Reset behavior /////
  // On reset, outputs and internal count are cleared to zero.
  check_reset_clears_outputs: assert property (
    @(posedge clk) rst |-> (activate == 2'b00) && (data == 32'd0) && (strobe == 1'b0) && (count == 24'd0)
  );

///// Activate encoding /////
  // activate is always at most one-hot (00,01,10).
  check_activate_onehot0: assert property (
    @(posedge clk) disable iff (rst) $onehot0(activate)
  );

// activate[0] can only rise from idle with enable and ready[0].
  check_activate0_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[0]) |-> $past((activate == 2'b00) && enable && ready[0])
  );

// activate[1] can only rise from idle with enable, ready[0]==0, and ready[1]==1.
  check_activate1_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[1]) |-> $past((activate == 2'b00) && enable && (ready[0] == 1'b0) && (ready[1] == 1'b1))
  );

// On reset, output equals init value that cycle.
    check_reset_assigns_init: assert property (
        @(posedge clock) reset |-> (io_out == io_init)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) (reset && io_enable) |-> (io_out == io_init)
    );

// g_out equals logical AND of inputs.
    check_g_out_is_and: assert property (
        @(posedge clk) g_out == (a & b)
    );

// p_out equals logical OR of inputs.
    check_p_out_is_or: assert property (
        @(posedge clk) p_out == (a | b)
    );

// If AND output is 1, OR output must also be 1.
    check_and_implies_or: assert property (
        @(posedge clk) g_out |-> p_out
    );

// When both inputs are 0, both outputs must be 0.
    check_zero_zero_outputs_zero: assert property (
        @(posedge clk) (!a && !b) |-> (!g_out && !p_out)
    );

// When a=1 and b=0, outputs must be g_out=0, p_out=1.
    check_a1_b0_outputs: assert property (
        @(posedge clk) (a && !b) |-> (!g_out && p_out)
    );

// When a=0 and b=1, outputs must be g_out=0, p_out=1.
    check_a0_b1_outputs: assert property (
        @(posedge clk) (!a && b) |-> (!g_out && p_out)
    );

// When both inputs are 1, both outputs must be 1.
    check_one_one_outputs_one: assert property (
        @(posedge clk) (a && b) |-> (g_out && p_out)
    );

// key_input == 1 maps to led_output == 00001
    map_1_to_00001: assert property (
        @(posedge clk) (key_input == 9'h001) |-> (led_output == 5'b00001)
    );

// key_input == 2 maps to led_output == 00010
    map_2_to_00010: assert property (
        @(posedge clk) (key_input == 9'h002) |-> (led_output == 5'b00010)
    );

// key_input == 4 maps to led_output == 00100
    map_4_to_00100: assert property (
        @(posedge clk) (key_input == 9'h004) |-> (led_output == 5'b00100)
    );

// key_input == 8 maps to led_output == 01000
    map_8_to_01000: assert property (
        @(posedge clk) (key_input == 9'h008) |-> (led_output == 5'b01000)
    );

// key_input == 16 maps to led_output == 10000
    map_16_to_10000: assert property (
        @(posedge clk) (key_input == 9'h010) |-> (led_output == 5'b10000)
    );

// key_input == 32 maps to led_output == 00000
    map_32_to_00000: assert property (
        @(posedge clk) (key_input == 9'h020) |-> (led_output == 5'b00000)
    );

// key_input == 64 maps to led_output == 11111
    map_64_to_11111: assert property (
        @(posedge clk) (key_input == 9'h040) |-> (led_output == 5'b11111)
    );

// For defined keys, led_output has no unknown bits
    no_x_led_when_defined: assert property (
        @(posedge clk)
        ((key_input == 9'h001) || (key_input == 9'h002) || (key_input == 9'h004) ||
         (key_input == 9'h008) || (key_input == 9'h010) || (key_input == 9'h020) ||
         (key_input == 9'h040)) |-> !$isunknown(led_output)
    );

// DUT has no reset; purely combinational 4-input AND built from 2-input ANDs.

    // and0_out must be 1 when both A and B are 1.
    check_and0_high_when_A_and_B_high: assert property (
        @(posedge clk) (A && B) |-> (and0_out == 1'b1)
    );

// and0_out must be 0 when either A or B is 0.
    check_and0_low_when_A_or_B_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (and0_out == 1'b0)
    );

// and1_out must be 1 when both C and D are 1.
    check_and1_high_when_C_and_D_high: assert property (
        @(posedge clk) (C && D) |-> (and1_out == 1'b1)
    );

// and1_out must be 0 when either C or D is 0.
    check_and1_low_when_C_or_D_low: assert property (
        @(posedge clk) ((!C) || (!D)) |-> (and1_out == 1'b0)
    );

// X must be 1 when both sub-AND outputs are 1.
    check_X_high_when_subands_high: assert property (
        @(posedge clk) (and0_out && and1_out) |-> (X == 1'b1)
    );

// X must be 0 when either sub-AND output is 0.
    check_X_low_when_any_suband_low: assert property (
        @(posedge clk) ((!and0_out) || (!and1_out)) |-> (X == 1'b0)
    );

// X must be 1 when all four inputs are 1.
    check_X_high_when_all_inputs_high: assert property (
        @(posedge clk) (A && B && C && D) |-> (X == 1'b1)
    );

// X must be 0 when any input is 0.
    check_X_low_when_any_input_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C) || (!D)) |-> (X == 1'b0)
    );

// and0_out being 1 implies both A and B are 1.
    check_and0_high_implies_A_and_B_high: assert property (
        @(posedge clk) and0_out |-> (A && B)
    );

// and1_out being 1 implies both C and D are 1.
    check_and1_high_implies_C_and_D_high: assert property (
        @(posedge clk) and1_out |-> (C && D)
    );

// Combinational DUT with no clock/reset; assertions sampled on clk.

    // Output equals RTL XOR expression.
    check_xor_equation: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// Output matches XOR operator directly.
    check_xor_operator_equiv: assert property (
        @(posedge clk) out_comb == (a ^ b)
    );

// Truth table: a=0, b=0 -> out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out_comb == 1'b0)
    );

// Truth table: a=1, b=0 -> out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out_comb == 1'b1)
    );

// Truth table: a=0, b=1 -> out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out_comb == 1'b1)
    );

// Truth table: a=1, b=1 -> out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out_comb == 1'b0)
    );

// Output low when inputs are equal.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

// Output high when inputs differ.
    check_diff_inputs_one: assert property (
        @(posedge clk) (a != b) |-> (out_comb == 1'b1)
    );

// Commutative form equivalence.
    check_commutative_form: assert property (
        @(posedge clk) out_comb == ((b & ~a) | (~b & a))
    );

///// Functional mapping /////
    // MSB mapping: gray[3] equals binary[3].
    check_gray_bit3_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] === binary[3]
    );

// gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] === (binary[3] ^ binary[2])
    );

// gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] === (binary[2] ^ binary[1])
    );

// gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] === (binary[1] ^ binary[0])
    );

// Full vector mapping matches {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_full_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray === {binary[3], (binary[3]^binary[2]), (binary[2]^binary[1]), (binary[1]^binary[0])}
    );

// op=0000: Y equals A + B
    check_add: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0000) |-> (Y == A + B)
    );

// op=0001: Y equals A - B
    check_sub: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0001) |-> (Y == A - B)
    );

// op=0010: Y equals A & B
    check_and: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0010) |-> (Y == (A & B))
    );

// op=0011: Y equals A | B
    check_or: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0011) |-> (Y == (A | B))
    );

// op=0100: Y equals A ^ B
    check_xor: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// op=0101: Y equals bitwise NOT of A
    check_notA: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0101) |-> (Y == ~A)
    );

// op=0110: Y equals A shifted left by 1 with LSB=0
    check_shift_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0110) |-> (Y == {A[14:0], 1'b0})
    );

// op=0111: Y equals A shifted right by 1 with MSB=0
    check_shift_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0111) |-> (Y == {1'b0, A[15:1]})
    );

// op=1000: Y equals A rotated left by 1
    check_rotate_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1000) |-> (Y == {A[14:0], A[15]})
    );

// op=1001: Y equals A rotated right by 1
    check_rotate_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1001) |-> (Y == {A[0], A[15:1]})
    );

// Default case: Y is zero for unimplemented opcodes (1010..1111)
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (op inside {[4'hA:4'hF]}) |-> (Y == 16'b0)
    );

// out_xor equals (sel_b2 ? b : (sel_b1 ? b : a)) XOR a.
    check_out_xor_from_mux: assert property (
        @(posedge clk) out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is bitwise inverse of out_xor.
    check_out_xor_inv_is_not: assert property (
        @(posedge clk) out_xor_inv == ~out_xor
    );

// out_logical_inv is logical NOT of out_xor (NOR-reduction).
    check_out_logical_inv_is_nor: assert property (
        @(posedge clk) out_logical_inv == ~(|out_xor)
    );

// When sel_b2 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b2_drives_b_xor_a: assert property (
        @(posedge clk) sel_b2 |-> (out_xor == (b ^ a))
    );

// When sel_b2 is 0 and sel_b1 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b1_drives_when_b2_low: assert property (
        @(posedge clk) (!sel_b2 && sel_b1) |-> (out_xor == (b ^ a))
    );

// When both sel_b2 and sel_b1 are 0, a is selected and out_xor is zero (a ^ a).
    check_both_selects_zero_xor_zero: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor == 4'b0000)
    );

// When both selects are 0, out_xor_inv is all ones (~0).
    check_both_selects_zero_inv_ones: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor_inv == 4'b1111)
    );

// When out_xor is zero, out_logical_inv must be 1.
    check_xor_zero_implies_logical_inv_one: assert property (
        @(posedge clk) (out_xor == 4'b0000) |-> (out_logical_inv == 1'b1)
    );

// Out matches the mux+enable function exactly.
    check_mux_function: assert property (
        @(posedge clk)
        out === (enable ? (sel == 2'b00 ? in0 :
                           sel == 2'b01 ? in1 :
                           sel == 2'b10 ? in2 : in3)
                       : 4'b0)
    );

// When disabled, out must be zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) (!enable) |-> (out === 4'b0)
    );

// When enabled and sel==00, out equals in0.
    check_sel00_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b00)) |-> (out === in0)
    );

// When enabled and sel==01, out equals in1.
    check_sel01_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b01)) |-> (out === in1)
    );

// When enabled and sel==10, out equals in2.
    check_sel10_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b10)) |-> (out === in2)
    );

// When enabled and sel==11, out equals in3.
    check_sel11_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b11)) |-> (out === in3)
    );

// If all inputs are equal and enabled, out equals that common value.
    check_equal_inputs_collapse: assert property (
        @(posedge clk) (enable && (in0 === in1) && (in1 === in2) && (in2 === in3)) |-> (out === in0)
    );

// If enabled and out is zero, the selected input must be zero.
    check_zero_out_implies_zero_selected_input: assert property (
        @(posedge clk)
        (enable && (out === 4'b0)) |-> (
            (sel == 2'b00) ? (in0 === 4'b0) :
            (sel == 2'b01) ? (in1 === 4'b0) :
            (sel == 2'b10) ? (in2 === 4'b0) :
                             (in3 === 4'b0)
        )
    );

///// Mapping from ctrl[7:5] to td_mode /////
    // When ctrl[7:5]==3'b000, td_mode must be 4'b0000.
    check_map_000: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );

// When ctrl[7:5]==3'b001, td_mode must be 4'b1000.
    check_map_001: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );

// When ctrl[7:5]==3'b010, td_mode must be 4'b0100.
    check_map_010: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );

// When ctrl[7:5]==3'b011, td_mode must be 4'b1100.
    check_map_011: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );

// When ctrl[7:5]==3'b100, td_mode must be 4'b0010.
    check_map_100: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );

// When ctrl[7:5]==3'b101, td_mode must be 4'b1010.
    check_map_101: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );

// When ctrl[7:5]==3'b110, td_mode must be 4'b0101.
    check_map_110: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );

// When ctrl[7:5]==3'b111, td_mode must be 4'b1111.
    check_map_111: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

///// General invariants derived from the mapping /////
    // td_mode must always be one of the defined codewords.
    check_td_mode_code_set: assert property (
        @(posedge clk) td_mode inside {4'b0000,4'b1000,4'b0100,4'b1100,4'b0010,4'b1010,4'b0101,4'b1111}
    );

///// Decoder correctness /////
    // Out equals 1 shifted by 'in' (core 4->16 one-hot decode).
    check_decode_function: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

// Out is exactly one-hot (exactly one bit set).
    check_out_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

///// Specific mappings (spot-checks) /////
    // in == 0 maps to out == 16'h0001.
    check_map_in0: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 16'h0001)
    );

// in == 1 maps to out == 16'h0002.
    check_map_in1: assert property (
        @(posedge clk) (in == 4'd1) |-> (out == 16'h0002)
    );

// in == 14 maps to out == 16'h4000.
    check_map_in14: assert property (
        @(posedge clk) (in == 4'd14) |-> (out == 16'h4000)
    );

// in == 15 maps to out == 16'h8000.
    check_map_in15: assert property (
        @(posedge clk) (in == 4'd15) |-> (out == 16'h8000)
    );

// Output equals XOR of inputs each cycle.
    check_xor_function: assert property (
        @(posedge CLK) (out_comb_logic == (a ^ b))
    );

// When inputs are equal, output is 0.
    check_out_zero_when_inputs_equal: assert property (
        @(posedge CLK) (a == b) |-> (out_comb_logic == 1'b0)
    );

// When inputs differ, output is 1.
    check_out_one_when_inputs_unequal: assert property (
        @(posedge CLK) (a != b) |-> (out_comb_logic == 1'b1)
    );

// When a is 0, output equals b.
    check_out_eq_b_when_a_zero: assert property (
        @(posedge CLK) (a == 1'b0) |-> (out_comb_logic == b)
    );

// When a is 1, output equals ~b.
    check_out_eq_notb_when_a_one: assert property (
        @(posedge CLK) (a == 1'b1) |-> (out_comb_logic == ~b)
    );

// When b is 0, output equals a.
    check_out_eq_a_when_b_zero: assert property (
        @(posedge CLK) (b == 1'b0) |-> (out_comb_logic == a)
    );

// When b is 1, output equals ~a.
    check_out_eq_nota_when_b_one: assert property (
        @(posedge CLK) (b == 1'b1) |-> (out_comb_logic == ~a)
    );

// X equals A|B|C|~D_N
    check_function_equation: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// D_N low forces X high
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) (D_N == 1'b0) |-> (X == 1'b1)
    );

// A high forces X high
    check_a_high_forces_x_high: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

// B high forces X high
    check_b_high_forces_x_high: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

// C high forces X high
    check_c_high_forces_x_high: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == 1'b1)
    );

// All inputs inactive (A=B=C=0, D_N=1) forces X low
    check_all_inactive_forces_x_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// X low implies A=B=C=0 and D_N=1
    check_x_low_implies_all_inactive: assert property (
        @(posedge clk) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// X high implies at least one of A,B,C is high or D_N is low
    check_x_high_implies_some_active: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0))
    );

// With D_N high, X equals A|B|C
    check_reduction_when_dn_high: assert property (
        @(posedge clk) (D_N == 1'b1) |-> (X == (A | B | C))
    );

// With A=B=C=0, X equals ~D_N
    check_reduction_when_abc_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == ~D_N)
    );

// A high forces X high.
    force_x_high_when_a_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// B high forces X high.
    force_x_high_when_b_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

// C high forces X high.
    force_x_high_when_c_high: assert property (
        @(posedge CLK) (C == 1'b1) |-> (X == 1'b1)
    );

// D_N low forces X high.
    force_x_high_when_dn_low: assert property (
        @(posedge CLK) (D_N == 1'b0) |-> (X == 1'b1)
    );

// All-neutral inputs drive X low.
    force_x_low_when_all_neutral: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// X low implies all inputs neutral.
    x_low_implies_all_neutral: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// X high implies at least one asserted (A/B/C) or D_N low.
    x_high_implies_any_input_true: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0))
    );

// With B=0,C=0,D_N=1, X equals A.
    x_equals_a_when_b0_c0_dn1: assert property (
        @(posedge CLK) ((B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == A)
    );

// With A=0,B=0,C=0, X equals !D_N.
    x_equals_notdn_when_a0_b0_c0: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == !D_N)
    );

// When all inputs are known, X equals (!D_N) OR A OR B OR C.
    truth_table_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B,C,D_N})) |-> (X == ((!D_N) || A || B || C))
    );

// X equals logical AND of all four inputs.
    check_output_equals_and4: assert property (
        @(posedge CLK) X == (A && B && C && D)
    );

// If X is HIGH, A must be HIGH.
    check_x_high_implies_a_high: assert property (
        @(posedge CLK) X |-> A
    );

// If X is HIGH, B must be HIGH.
    check_x_high_implies_b_high: assert property (
        @(posedge CLK) X |-> B
    );

// If X is HIGH, C must be HIGH.
    check_x_high_implies_c_high: assert property (
        @(posedge CLK) X |-> C
    );

// If X is HIGH, D must be HIGH.
    check_x_high_implies_d_high: assert property (
        @(posedge CLK) X |-> D
    );

// When a >= b, out must equal a.
    check_out_eq_a_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (out == a)
    );

// When b > a, out must equal b.
    check_out_eq_b_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out == b)
    );

// When a == b, out must equal a.
    check_out_eq_a_when_equal: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// If neither condition holds, out is 0.
    check_out_zero_when_neither: assert property (
        @(posedge clk) (!(a >= b) && !(b > a)) |-> (out == 8'h00)
    );

// Under a >= b, out is at least b.
    check_out_ge_b_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (out >= b)
    );

// Under b > a, out is at least a.
    check_out_ge_a_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out >= a)
    );

///// Reset behavior /////
    // While reset is asserted, drive out_port and readdata to 0.
    reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (out_port == 6'd0) && (readdata == 32'd0)
    );

///// Read datapath /////
    // Upper readdata bits are always zero.
    readdata_upper_zero_always: assert property (
        @(posedge clk) disable iff (!reset_n) readdata[31:6] == 26'd0
    );

// When address == 0, readdata[5:0] reflects out_port.
    read_addr0_reflects_out_port: assert property (
        @(posedge clk) disable iff (!reset_n) (address == 2'd0) |-> (readdata[5:0] == out_port)
    );

// When address != 0, entire readdata is zero.
    read_addr_nonzero_is_zero: assert property (
        @(posedge clk) disable iff (!reset_n) (address != 2'd0) |-> (readdata == 32'd0)
    );

// On reset release, if no same-cycle write to address 0, out_port remains 0.
    zero_after_reset_release_no_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            $rose(reset_n) && !(chipselect && !write_n && (address == 2'd0)) |-> (out_port == 6'd0)
    );

///// Combinational mapping checks (sampled on clk) /////
    // gray[3] equals binary[8].
    check_gray3_eq_binary8: assert property (
        @(posedge clk) gray[3] == binary[8]
    );

// gray[2] equals binary[8] XOR binary[7].
    check_gray2_eq_b8_xor_b7: assert property (
        @(posedge clk) gray[2] == (binary[8] ^ binary[7])
    );

// gray[1] equals binary[7] XOR binary[6].
    check_gray1_eq_b7_xor_b6: assert property (
        @(posedge clk) gray[1] == (binary[7] ^ binary[6])
    );

// gray[0] equals binary[6] XOR binary[5].
    check_gray0_eq_b6_xor_b5: assert property (
        @(posedge clk) gray[0] == (binary[6] ^ binary[5])
    );

// o_dataout is the mux of i_register_settings and i_datain selected by i_settings.
    check_dataout_mux_function: assert property (
        @(posedge clock) disable iff (!resetn)
            o_dataout == (i_settings ? i_register_settings : i_datain)
    );

// When i_settings is 1, o_dataout equals i_register_settings.
    check_dataout_sel_register_settings: assert property (
        @(posedge clock) disable iff (!resetn)
            i_settings |-> (o_dataout == i_register_settings)
    );

// When i_settings is 0, o_dataout equals i_datain.
    check_dataout_sel_datain: assert property (
        @(posedge clock) disable iff (!resetn)
            !i_settings |-> (o_dataout == i_datain)
    );

// o_dataout_valid passes through from i_datain_valid.
    check_valid_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
            o_dataout_valid == i_datain_valid
    );

// o_datain_stall passes through from i_dataout_stall.
    check_stall_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
            o_datain_stall == i_dataout_stall
    );

// If i_settings and both data inputs are stable, o_dataout remains stable.
    check_dataout_stable_when_all_inputs_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_settings) && $stable(i_register_settings) && $stable(i_datain)
            |-> $stable(o_dataout)
    );

// If i_datain_valid is stable, o_dataout_valid remains stable.
    check_valid_stable_when_input_valid_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_datain_valid) |-> $stable(o_dataout_valid)
    );

// If i_dataout_stall is stable, o_datain_stall remains stable.
    check_stall_stable_when_input_stall_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_dataout_stall) |-> $stable(o_datain_stall)
    );

// Changes on unselected i_datain do not affect o_dataout when selecting i_register_settings.
    check_independence_unselected_datain: assert property (
        @(posedge clock) disable iff (!resetn)
            i_settings && $stable(i_register_settings) && $changed(i_datain)
            |-> $stable(o_dataout)
    );

// Changes on unselected i_register_settings do not affect o_dataout when selecting i_datain.
    check_independence_unselected_regsettings: assert property (
        @(posedge clock) disable iff (!resetn)
            !i_settings && $stable(i_datain) && $changed(i_register_settings)
            |-> $stable(o_dataout)
    );

///// Functional correctness against the RTL computation /////
    // a_prim must equal a1_e = (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) a_prim == a1_e
    );

// b_prim must equal b3_e = rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c1_e ).
    check_b_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) b_prim == b3_e
    );

// c_prim must equal c1_e = (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) c_prim == c1_e
    );

// d_prim must equal d3_e = rol8( rol16(d ^ (a + b)) ^ a_prim ).
    check_d_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) d_prim == d3_e
    );

///// Closed-form relations directly from inputs /////
    // a_prim equals (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            a_prim == (a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))
    );

// d_prim equals rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) ).
    check_d_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            d_prim == rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) )
    );

// c_prim equals (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            c_prim == (c + rol16(d ^ (a + b))) + d_prim
    );

// b_prim equals rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim ).
    check_b_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            b_prim == rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim )
    );

///// Functional equivalence checks /////
    // out_and equals bitwise AND of all inputs.
    spec_out_and_def: assert property (
        @(posedge clk) out_and == (((in1 & in2) & in3) & in4)
    );

// out_or equals bitwise OR of all inputs.
    spec_out_or_def: assert property (
        @(posedge clk) out_or == (((in1 | in2) | in3) | in4)
    );

// out_xor equals bitwise XOR of all inputs.
    spec_out_xor_def: assert property (
        @(posedge clk) out_xor == (((in1 ^ in2) ^ in3) ^ in4)
    );

///// AND result subset relations /////
    // out_and cannot have 1s where in1 has 0s.
    check_and_subset_in1: assert property (
        @(posedge clk) (out_and & ~in1) == 4'b0000
    );

// out_and cannot have 1s where in2 has 0s.
    check_and_subset_in2: assert property (
        @(posedge clk) (out_and & ~in2) == 4'b0000
    );

// out_and cannot have 1s where in3 has 0s.
    check_and_subset_in3: assert property (
        @(posedge clk) (out_and & ~in3) == 4'b0000
    );

// out_and cannot have 1s where in4 has 0s.
    check_and_subset_in4: assert property (
        @(posedge clk) (out_and & ~in4) == 4'b0000
    );

///// OR result superset relations /////
    // out_or must have 1s wherever in1 has 1s.
    check_or_superset_in1: assert property (
        @(posedge clk) (in1 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in2 has 1s.
    check_or_superset_in2: assert property (
        @(posedge clk) (in2 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in3 has 1s.
    check_or_superset_in3: assert property (
        @(posedge clk) (in3 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in4 has 1s.
    check_or_superset_in4: assert property (
        @(posedge clk) (in4 & ~out_or) == 4'b0000
    );

///// Cross-output relation /////
    // AND result is always a subset of OR result.
    check_and_implies_or: assert property (
        @(posedge clk) (out_and & ~out_or) == 4'b0000
    );

// Route Y = D0 when S1=0,S0=0 and selects are known.
    route_sel00_to_D0: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b0)) |-> (Y === D0)
    );

// Route Y = D1 when S1=0,S0=1 and selects are known.
    route_sel01_to_D1: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b1)) |-> (Y === D1)
    );

// Route Y = D2 when S1=1,S0=0 and selects are known.
    route_sel10_to_D2: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b0)) |-> (Y === D2)
    );

// Route Y = D3 when S1=1,S0=1 and selects are known.
    route_sel11_to_D3: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b1)) |-> (Y === D3)
    );

// Any unknown on S0 or S1 must drive Y to X (due to default in mux2_1).
    xprop_when_select_unknown: assert property (
        @(posedge CLK) ($isunknown(S0) || $isunknown(S1)) |-> (Y === 1'bx)
    );

///// Functional equivalence to reduction operators /////
    // out_and equals bitwise reduction AND of in.
    check_out_and_equals_reduction: assert property (
        @(posedge CLK) (out_and === (&in))
    );

// All 4 outputs equal the AND of the two inputs.
    check_out_matches_and_broadcast: assert property (
        @(posedge clk) disable iff (!rst_n) out == {4{in[0] & in[1]}}
    );

// All output bits are identical at all times.
    check_all_outs_equal: assert property (
        @(posedge clk) disable iff (!rst_n) (out[0] == out[1]) && (out[1] == out[2]) && (out[2] == out[3])
    );

// Outputs are all zero when any input is zero.
    check_out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (!rst_n) ((!in[0]) || (!in[1])) |-> (out == 4'b0000)
    );

// Outputs are all one when both inputs are one.
    check_out_one_when_both_inputs_one: assert property (
        @(posedge clk) disable iff (!rst_n) (in[0] && in[1]) |-> (out == 4'b1111)
    );

// A rising edge on any output implies both inputs are one.
    check_out_rise_implies_inputs_high: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(out[0]) |-> (in[0] && in[1])
    );

// A falling edge on any output implies at least one input is zero.
    check_out_fall_implies_any_input_low: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(out[0]) |-> ((!in[0]) || (!in[1]))
    );

// Output bus can only be all-zeros or all-ones.
    check_out_is_const_bus: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 4'b0000) || (out == 4'b1111)
    );

///// Functional equivalence checks /////
    // X equals A|B when A rises.
    check_func_eq_on_A_posedge: assert property (
        @(posedge A) X == (A | B)
    );

// X equals A|B when A falls.
    check_func_eq_on_A_negedge: assert property (
        @(negedge A) X == (A | B)
    );

// X equals A|B when B rises.
    check_func_eq_on_B_posedge: assert property (
        @(posedge B) X == (A | B)
    );

// X equals A|B when B falls.
    check_func_eq_on_B_negedge: assert property (
        @(negedge B) X == (A | B)
    );

// A falling with B high keeps X high.
    check_x_stays_high_on_a_fall_when_b_high: assert property (
        @(negedge A) (B == 1'b1) |-> (X == 1'b1)
    );

// B falling with A high keeps X high.
    check_x_stays_high_on_b_fall_when_a_high: assert property (
        @(negedge B) (A == 1'b1) |-> (X == 1'b1)
    );

///// Reset behavior /////
    // Synchronous clear forces op low on the next cycle.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

///// Update and hold rules /////
    // With clr low, ce sets op high on the next cycle.
    ce_sets_op_high_next: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// With clr low and ce low, op holds its value.
    hold_without_ce: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// Once high and with clr low, op stays high.
    sticky_high_without_clr: assert property (
        @(posedge clk) disable iff (clr) (op == 1'b1) |=> (op == 1'b1)
    );

///// Reset behavior /////
  // While reset is asserted low, outputs are forced to 0/1.
  reset_level_forces_values: assert property (
    @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled falling edge of reset, outputs are 0/1.
  reset_fall_forces_values: assert property (
    @(posedge CLK) $fell(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled rising edge of reset, outputs are still at reset values before capture.
  reset_rise_holds_reset_values_before_capture: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

///// Output relationship /////
  // QN is always the logical inverse of Q.
  complement_invariant: assert property (
    @(posedge CLK) QN == ~Q
  );

// Q and QN are never both HIGH.
  never_both_high: assert property (
    @(posedge CLK) !(Q && QN)
  );

// Q and QN are never both LOW.
  never_both_low: assert property (
    @(posedge CLK) !(~Q && ~QN)
  );

// A rise on Q implies a fall on QN in the same sample.
  q_rise_implies_qn_fall: assert property (
    @(posedge CLK) $rose(Q) |-> $fell(QN)
  );

// Reset low forces count to zero on each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

// Next-state function when out of reset: increment on enable, else hold.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (count == (enable ? ($past(count) + 4'd1) : $past(count)))
    );

// When enable is 1, count increments by exactly 1 (mod 16).
    check_increment_when_enable: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable) |-> (count == ($past(count) + 4'd1))
    );

// When enable is 0, count holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !enable) |-> (count == $past(count))
    );

// Wrap-around: from 4'hF with enable high, next value is 0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// If reset rises on a clock edge, next count is 1 if enable=1 else 0.
    check_release_from_reset_at_clk: assert property (
        @(posedge clk) $rose(reset) |-> (count == (enable ? 4'd1 : 4'd0))
    );

// No unknowns on output when inputs are known.
    check_no_x_on_output_when_inputs_known: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (!$isunknown({add_sub,in1,in2})) |-> (!$isunknown(res))
    );

// In add mode, res equals zero-extended exact sum.
    check_add_exact_value: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (add_sub == 1'b0) |-> (res == ({1'b0,in1} + {1'b0,in2}))
    );

// In add mode, LSB equals XOR of input LSBs.
    check_add_lsb_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (add_sub == 1'b0) |-> (res[0] == (in1[0] ^ in2[0]))
    );

// In sub mode, LSB equals XOR of input LSBs.
    check_sub_lsb_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (add_sub == 1'b1) |-> (res[0] == (in1[0] ^ in2[0]))
    );

// In add mode, adding zero leaves operand unchanged (zero-extended).
    check_add_zero_identity: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (add_sub == 1'b0 && in2 == '0) |-> (res == {1'b0,in1})
    );

// In sub mode, subtracting self yields zero (zero-extended).
    check_sub_self_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (add_sub == 1'b1 && in1 == in2) |-> (res == '0)
    );

// When reset is asserted, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// If reset is high in consecutive cycles, count holds at 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (($past(rst)===1'b1) && rst) |-> (count == 4'h0) && (count == $past(count))
    );

// Wrap-around: from 0xF to 0x0 when running.
    check_wraparound_mod16: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(rst)===1'b0) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// Clock: clk (posedge). Reset: rst (active-high, synchronous). Logic is sequential (registered outputs).
    // Behavior: rst clears outputs; when en, control_o[2:0] reflect inputs and pc_op depends on imm; other bits hold.

    // Synchronous reset drives outputs to zero on the next cycle.
    reset_sync_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0) && (pc_op == 2'b00)
    );

// When not enabled, control_o holds its previous value.
    hold_when_en_low_control: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o))
    );

// When not enabled, pc_op holds its previous value.
    hold_when_en_low_pc: assert property (
        @(posedge clk) disable iff (rst) !en |=> (pc_op == $past(pc_op))
    );

// When enabled, upper control bits [8:3] remain unchanged.
    hi_bits_unchanged_on_en: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[8:3] == $past(control_o[8:3]))
    );

// After an enable update, pc_op[1] matches control_o[2] (both from imm).
    pc_op_msb_matches_control2_on_update: assert property (
        @(posedge clk) disable iff (rst) en |=> (pc_op[1] == control_o[2])
    );

// For SHIFT_DIRECTION=0, output equals DATA << SHIFT_AMOUNT.
    check_left_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

// For SHIFT_DIRECTION=1, output equals DATA >> SHIFT_AMOUNT.
    check_right_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

// Shift amount 0 leaves data unchanged.
    check_shift_by_zero_identity: assert property (
        @(posedge CLK) (SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

// Left shift zero-fills lower bits.
    check_left_zero_fill_lsb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> ((SHIFTED_DATA & ((8'h1 << SHIFT_AMOUNT) - 8'h1)) == 8'h00)
    );

// Right shift zero-fills upper bits.
    check_right_zero_fill_msb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> ((SHIFTED_DATA & ~(8'hFF >> SHIFT_AMOUNT)) == 8'h00)
    );

// Zero input yields zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (DATA == 8'h00) |-> (SHIFTED_DATA == 8'h00)
    );

// Left shift by 7 moves bit0 to MSB and clears others.
    check_left_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {DATA[0], 7'b0})
    );

// Right shift by 7 moves MSB to LSB and clears others.
    check_right_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {7'b0, DATA[7]})
    );

// Output equals selected shift function for all cases.
    check_functional_equation: assert property (
        @(posedge CLK) SHIFTED_DATA == ((SHIFT_DIRECTION == 1'b0) ? (DATA << SHIFT_AMOUNT) : (DATA >> SHIFT_AMOUNT))
    );

// No clock/reset in DUT; pure combinational AND. Sample on posedges of inputs/outputs.

    // Z equals A & B & C & D when A toggles HIGH.
    check_z_eq_and_at_A: assert property (
        @(posedge A) Z == (A & B & C & D)
    );

// Z equals A & B & C & D when B toggles HIGH.
    check_z_eq_and_at_B: assert property (
        @(posedge B) Z == (A & B & C & D)
    );

// Z equals A & B & C & D when C toggles HIGH.
    check_z_eq_and_at_C: assert property (
        @(posedge C) Z == (A & B & C & D)
    );

// Z equals A & B & C & D when D toggles HIGH.
    check_z_eq_and_at_D: assert property (
        @(posedge D) Z == (A & B & C & D)
    );

// Z equals A & B & C & D when Z toggles HIGH.
    check_z_eq_and_at_Z: assert property (
        @(posedge Z) Z == (A & B & C & D)
    );

// sum equals A XOR B.
    check_sum_is_xor: assert property (
        @(posedge clk) disable iff (1'b0) sum == (A ^ B)
    );

// carry_out equals A AND B.
    check_carry_is_and: assert property (
        @(posedge clk) disable iff (1'b0) carry_out == (A & B)
    );

// sum and carry_out are never both HIGH.
    check_sum_carry_mutex: assert property (
        @(posedge clk) disable iff (1'b0) !(sum && carry_out)
    );

// (sum OR carry_out) equals (A OR B).
    check_or_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) (sum | carry_out) == (A | B)
    );

// For A=0,B=0: sum=0 and carry_out=0.
    check_tt_00: assert property (
        @(posedge clk) disable iff (1'b0) ((A==1'b0) && (B==1'b0)) |-> ((sum==1'b0) && (carry_out==1'b0))
    );

// For A=1,B=1: sum=0 and carry_out=1.
    check_tt_11: assert property (
        @(posedge clk) disable iff (1'b0) ((A==1'b1) && (B==1'b1)) |-> ((sum==1'b0) && (carry_out==1'b1))
    );

// If carry_out is HIGH then both inputs are HIGH.
    check_carry_implies_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0) carry_out |-> (A && B)
    );

// If sum is HIGH then inputs differ.
    check_sum_implies_inputs_differ: assert property (
        @(posedge clk) disable iff (1'b0) sum |-> (A ^ B)
    );

// {carry_out,sum} equals zero-extended A+B.
    check_addition_identity: assert property (
        @(posedge clk) disable iff (1'b0) {carry_out, sum} == ({1'b0, A} + {1'b0, B})
    );

// out equals two's complement of (a | b).
    out_twos_comp_def: assert property (
        @(posedge clk) out == ((~(a | b)) + 4'd1)
    );

// out plus (a | b) wraps to zero (mod 16).
    sum_with_or_zero: assert property (
        @(posedge clk) (out + (a | b)) == 4'd0
    );

// out is zero iff both a and b are zero.
    zero_iff_a_b_zero: assert property (
        @(posedge clk) (out == 4'd0) == ((a == 4'd0) && (b == 4'd0))
    );

// Two's complement of out yields (a | b).
    double_negation_returns_or: assert property (
        @(posedge clk) ((~out) + 4'd1) == (a | b)
    );

// If (a | b) is 8, out is also 8 (self-negating).
    or_8_maps_to_out_8: assert property (
        @(posedge clk) ((a | b) == 4'd8) |-> (out == 4'd8)
    );

// If (a | b) is 15 (all ones), out is 1.
    or_all_ones_maps_to_one: assert property (
        @(posedge clk) ((a | b) == 4'hF) |-> (out == 4'd1)
    );

// Nonzero (a | b) implies nonzero out.
    nonzero_or_implies_nonzero_out: assert property (
        @(posedge clk) ((a | b) != 4'd0) |-> (out != 4'd0)
    );

// Synchronous reset drives count to 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// Reset dominates enable when both are asserted.
    reset_overrides_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'd0)
    );

// When enabled (and not in reset), count increments by 1.
    increment_on_enable: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When not enabled (and not in reset), count holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// Result matches the top-level combinational spec
    check_overall_functionality: assert property (
        @(posedge clk) result == (SEL[1] ? (SEL[0] ? (A >> B) : (A << B))
                                        : (SEL[0] ? (A - B) : (A + B)))
    );

// When select is add/sub and mode=add, result equals A+B
    check_add_mode_add: assert property (
        @(posedge clk) (SEL[1] == 1'b0 && SEL[0] == 1'b0) |-> (result == (A + B))
    );

// When select is add/sub and mode=sub, result equals A-B
    check_add_mode_sub: assert property (
        @(posedge clk) (SEL[1] == 1'b0 && SEL[0] == 1'b1) |-> (result == (A - B))
    );

// When select is shift and dir=left, result equals A<<B
    check_shift_mode_left: assert property (
        @(posedge clk) (SEL[1] == 1'b1 && SEL[0] == 1'b0) |-> (result == (A << B))
    );

// When select is shift and dir=right, result equals A>>B
    check_shift_mode_right: assert property (
        @(posedge clk) (SEL[1] == 1'b1 && SEL[0] == 1'b1) |-> (result == (A >> B))
    );

// In shift path, zero shift amount returns A
    check_shift_zero_amount: assert property (
        @(posedge clk) (SEL[1] == 1'b1 && (B == 16'd0)) |-> (result == A)
    );

// In add/sub path, B==0 returns A
    check_addsub_zero_B: assert property (
        @(posedge clk) (SEL[1] == 1'b0 && (B == 16'd0)) |-> (result == A)
    );

// In subtract mode with equal operands, result is zero
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (SEL[1] == 1'b0 && SEL[0] == 1'b1 && (A == B)) |-> (result == 16'h0000)
    );

// Right shift by amount >= width yields zero
    check_right_shift_ge_width_zero: assert property (
        @(posedge clk) (SEL[1] == 1'b1 && SEL[0] == 1'b1 && (B >= 16'd16)) |-> (result == 16'h0000)
    );

// Left shift by amount >= width yields zero
    check_left_shift_ge_width_zero: assert property (
        @(posedge clk) (SEL[1] == 1'b1 && SEL[0] == 1'b0 && (B >= 16'd16)) |-> (result == 16'h0000)
    );

// When select=0, concatenated outputs equal i_mk15to12.
    check_concat_sel0: assert property (
        @(posedge i_op) (!w_out_sel) |-> ({o_wk3_7, o_wk2_6, o_wk1_5, o_wk0_4} == i_mk15to12)
    );

// When select=1, concatenated outputs equal i_mk3to0.
    check_concat_sel1: assert property (
        @(posedge i_op) (w_out_sel) |-> ({o_wk3_7, o_wk2_6, o_wk1_5, o_wk0_4} == i_mk3to0)
    );

// When select=0, o_wk3_7 maps to i_mk15to12[31:24].
    check_sel0_byte_31_24: assert property (
        @(posedge i_op) (!w_out_sel) |-> (o_wk3_7 == i_mk15to12[31:24])
    );

// When select=0, o_wk2_6 maps to i_mk15to12[23:16].
    check_sel0_byte_23_16: assert property (
        @(posedge i_op) (!w_out_sel) |-> (o_wk2_6 == i_mk15to12[23:16])
    );

// When select=0, o_wk1_5 maps to i_mk15to12[15:8].
    check_sel0_byte_15_8: assert property (
        @(posedge i_op) (!w_out_sel) |-> (o_wk1_5 == i_mk15to12[15:8])
    );

// When select=0, o_wk0_4 maps to i_mk15to12[7:0].
    check_sel0_byte_7_0: assert property (
        @(posedge i_op) (!w_out_sel) |-> (o_wk0_4 == i_mk15to12[7:0])
    );

// When select=1, o_wk3_7 maps to i_mk3to0[31:24].
    check_sel1_byte_31_24: assert property (
        @(posedge i_op) (w_out_sel) |-> (o_wk3_7 == i_mk3to0[31:24])
    );

// When select=1, o_wk2_6 maps to i_mk3to0[23:16].
    check_sel1_byte_23_16: assert property (
        @(posedge i_op) (w_out_sel) |-> (o_wk2_6 == i_mk3to0[23:16])
    );

// When select=1, o_wk1_5 maps to i_mk3to0[15:8].
    check_sel1_byte_15_8: assert property (
        @(posedge i_op) (w_out_sel) |-> (o_wk1_5 == i_mk3to0[15:8])
    );

// When select=1, o_wk0_4 maps to i_mk3to0[7:0].
    check_sel1_byte_7_0: assert property (
        @(posedge i_op) (w_out_sel) |-> (o_wk0_4 == i_mk3to0[7:0])
    );

// Clock: posedge clk; Reset: rst_n active-low async; Logic: mixed (seq rat/pc, comb low_sum/pc_plus_one/m_at mux)

  // During reset, rat and pc are driven to zero.
  reset_regs_zero: assert property (
    @(posedge clk) !rst_n |-> (rat == 8'h00) && (pc == 8'h00)
  );

// During reset, m_at is zero since it selects between zeroed pc/rat.
  reset_m_at_zero: assert property (
    @(posedge clk) !rst_n |-> (m_at == 8'h00)
  );

///// Functional equivalence /////
    // F equals the truth table defined by the RTL case mapping.
    check_f_equivalence: assert property (
        @(posedge CLK) F == expected_F
    );

///// Individual minterm checks where F must be 1 /////
    // When A..E = 00000, F must be 1.
    check_f_one_00000: assert property (
        @(posedge CLK) (X == 5'b00000) |-> (F == 1'b1)
    );

// When A..E = 00111, F must be 1.
    check_f_one_00111: assert property (
        @(posedge CLK) (X == 5'b00111) |-> (F == 1'b1)
    );

// When A..E = 00101, F must be 1.
    check_f_one_00101: assert property (
        @(posedge CLK) (X == 5'b00101) |-> (F == 1'b1)
    );

// When A..E = 01101, F must be 1.
    check_f_one_01101: assert property (
        @(posedge CLK) (X == 5'b01101) |-> (F == 1'b1)
    );

// When A..E = 01111, F must be 1.
    check_f_one_01111: assert property (
        @(posedge CLK) (X == 5'b01111) |-> (F == 1'b1)
    );

// When A..E = 01110, F must be 1.
    check_f_one_01110: assert property (
        @(posedge CLK) (X == 5'b01110) |-> (F == 1'b1)
    );

// When A..E = 01010, F must be 1.
    check_f_one_01010: assert property (
        @(posedge CLK) (X == 5'b01010) |-> (F == 1'b1)
    );

// When A..E = 01011, F must be 1.
    check_f_one_01011: assert property (
        @(posedge CLK) (X == 5'b01011) |-> (F == 1'b1)
    );

// When A..E = 01001, F must be 1.
    check_f_one_01001: assert property (
        @(posedge CLK) (X == 5'b01001) |-> (F == 1'b1)
    );

// When A..E = 11000, F must be 1.
    check_f_one_11000: assert property (
        @(posedge CLK) (X == 5'b11000) |-> (F == 1'b1)
    );

// When A..E = 11110, F must be 1.
    check_f_one_11110: assert property (
        @(posedge CLK) (X == 5'b11110) |-> (F == 1'b1)
    );

// When A..E = 11111, F must be 1.
    check_f_one_11111: assert property (
        @(posedge CLK) (X == 5'b11111) |-> (F == 1'b1)
    );

// When A..E = 10010, F must be 1.
    check_f_one_10010: assert property (
        @(posedge CLK) (X == 5'b10010) |-> (F == 1'b1)
    );

// When A..E = 10011, F must be 1.
    check_f_one_10011: assert property (
        @(posedge CLK) (X == 5'b10011) |-> (F == 1'b1)
    );

// When op==00, result equals 8-bit addition zero-extended.
    check_addition_result: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b00) |-> (result == (A + B))
    );

// When op==01, result equals 8-bit subtraction zero-extended.
    check_subtraction_result: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b01) |-> (result == (A - B))
    );

// For division with nonzero divisor, upper 8 bits are zero.
    check_upper_zero_for_div_no_div0: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 2'b11 && (B != 8'd0)) |-> (result[15:8] == 8'h00)
    );

// Clock: clk; Reset: rst (active-high, asynchronous)
    // Sequential logic: 4-bit up-counter with async reset to 0

    // During reset, count is forced to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// While reset remains asserted across cycles, count stays 0 and stable.
    check_count_stable_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0 && $stable(count))
    );

// Wrap-around: when previous value was 0xF out of reset, next is 0x0.
    check_wraparound_from_f_to_0: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// No clock/reset in RTL; pure combinational mux. Assertions sampled on external CLK.

    // EN low forces Y to 0.
    en_low_forces_y_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (Y == 1'b0)
    );

// With EN high and SEL==00, Y equals ABCD[0].
    sel_00_routes_bit0: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b00) |-> (Y == ABCD[0])
    );

// With EN high and SEL==01, Y equals ABCD[1].
    sel_01_routes_bit1: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b01) |-> (Y == ABCD[1])
    );

// With EN high and SEL==10, Y equals ABCD[2].
    sel_10_routes_bit2: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b10) |-> (Y == ABCD[2])
    );

// With EN high and SEL==11, Y equals ABCD[3].
    sel_11_routes_bit3: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b11) |-> (Y == ABCD[3])
    );

// With EN high and unknown SEL, Y drives X (default case).
    unknown_sel_drives_x_when_en: assert property (
        @(posedge CLK) (EN == 1'b1 && $isunknown(SEL)) |-> (Y === 1'bx)
    );

// Clock: clk (posedge). Reset: reset (active-high, asynchronous).
    // Logic: sequential with async reset; count=0 on reset, else count increments modulo 16.

    // While reset is HIGH at the clock edge, count must be 0.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// If reset is HIGH on two consecutive clock edges, count holds its value (remains 0).
    check_reset_held_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == $past(count))
    );

// One cycle after reset falls at a clock edge, the counter advances to 1.
    check_first_count_after_reset_fall: assert property (
        @(posedge clk) $fell(reset) |=> (count == 4'd1)
    );

// Count is always within 4-bit range (sanity check).
    check_count_range: assert property (
        @(posedge clk) (count <= 4'd15)
    );

// Cover: observe a normal increment between consecutive cycles without reset.
    cover_normal_increment: cover property (
        @(posedge clk) disable iff (reset) (count == ($past(count) + 4'd1))
    );

// Cover: observe rollover from 15 to 0 without reset interference.
    cover_rollover: cover property (
        @(posedge clk) disable iff (reset) (count == 4'hF) ##1 (count == 4'h0)
    );

// Left shift definition: dir==0 makes out = in << shift.
    check_left_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b0) |-> (out == (in << shift))
    );

// Right shift definition: dir==1 makes out = in >> shift.
    check_right_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b1) |-> (out == (in >> shift))
    );

// Zero shift is identity regardless of dir.
    check_shift_zero_identity: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

// Zero input yields zero output for any dir/shift.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (in == 16'h0000) |-> (out == 16'h0000)
    );

// Left shift zero-fill: lower 'shift' bits of out are zero.
    check_left_zero_fill_lowbits: assert property (
        @(posedge CLK) (dir == 1'b0) |-> ((out & (((16'h0001 << shift) - 16'h0001))) == 16'h0000)
    );

// Right shift zero-fill: upper 'shift' bits of out are zero.
    check_right_zero_fill_highbits: assert property (
        @(posedge CLK) (dir == 1'b1) |-> ((out & (16'hFFFF << (16 - shift))) == 16'h0000)
    );

// Left shift by 15: out[14:0]==0 and out[15]==in[0].
    check_left_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd15)) |-> ((out[14:0] == 15'b0) && (out[15] == in[0]))
    );

// Right shift by 15: out[15:1]==0 and out[0]==in[15].
    check_right_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd15)) |-> ((out[15:1] == 15'b0) && (out[0] == in[15]))
    );

// Left shift by 1: LSB zero and remaining bits align with in.
    check_left_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd1)) |-> ((out[0] == 1'b0) && (out[15:1] == in[14:0]))
    );

// Right shift by 1: MSB zero and remaining bits align with in.
    check_right_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd1)) |-> ((out[15] == 1'b0) && (out[14:0] == in[15:1]))
    );

// Synchronous reset sets reg_0x1F to zero on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// Reset has priority over writes (wenb low) and still drives zero next cycle.
    reset_overrides_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |=> (reg_0x1F == 8'h00)
    );

// When not in reset and wenb is LOW, capture in_data on the next cycle.
    write_captures_in_data: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |=> (reg_0x1F == $past(in_data))
    );

// When not in reset and wenb is HIGH, hold previous value on the next cycle.
    hold_on_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |=> (reg_0x1F == $past(reg_0x1F))
    );

// While reset remains asserted across cycles, the register is zero.
    reset_while_asserted_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

// Even if in_data toggles, with wenb HIGH the register does not update.
    no_update_when_wenb_high_despite_data_change: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1 && $changed(in_data)) |=> (reg_0x1F == $past(reg_0x1F))
    );

// On a write with data different from the current value, the register must change next cycle.
    write_with_different_data_changes_reg: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0 && (in_data != reg_0x1F)) |=> (reg_0x1F != $past(reg_0x1F))
    );

// parity_error equals the reduction XOR of data (handles X/Z via case equality).
    check_parity_equals_reduction: assert property (
        @(posedge CLK) disable iff (!RESETn) (parity_error === (^data))
    );

// Fully known data implies parity_error is known (no X/Z).
    check_known_data_implies_known_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!$isunknown(data)) |-> (!$isunknown(parity_error))
    );

// All-zero data has even parity -> parity_error is 0.
    check_zero_data_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'h00) |-> (parity_error == 1'b0)
    );

// All-ones (8'hFF) has even parity for 8 bits -> parity_error is 0.
    check_allones_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'hFF) |-> (parity_error == 1'b0)
    );

// Exactly one '1' in data (odd weight) -> parity_error is 1.
    check_onehot_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(data) |-> (parity_error == 1'b1)
    );

// Exactly one '0' in data (seven ones, odd) -> parity_error is 1.
    check_onecold_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(~data) |-> (parity_error == 1'b1)
    );

// After a sampled reset, Q must be 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (Q == 4'b0000)
    );

// With load high (reset low), Q updates to data_in on the next clock.
    check_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

// After a sampled reset, if no load in the following cycle, Q remains 0 for one more cycle.
    check_zero_persists_one_more_cycle_without_load_after_reset: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && !load |=> (Q == 4'b0000)
    );

// Back-to-back loads pipeline data: second cycle reflects data_in of the first next cycle.
    check_back_to_back_loads_pipeline: assert property (
        @(posedge clk) disable iff (reset) load ##1 load |=> (Q == $past(data_in))
    );

// If previous cycle had reset and current load is high, Q is 0 in the current cycle (reset dominates).
    check_reset_dominates_load_current: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |-> (Q == 4'b0000)
    );

// If previous cycle had reset and current load is high, Q captures current data on the next clock.
    check_reset_then_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |=> (Q == $past(data_in))
    );

// SUM must equal A xor B xor CI.
    check_sum_logic: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT must equal majority of A,B,CI (carry-out).
    check_cout_logic: assert property (
        @(posedge CLK) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// {COUT,SUM} equals the 2-bit addition of inputs.
    check_add_result_vector: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// 000 inputs produce 00 outputs.
    truth_000: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// 111 inputs produce 11 outputs.
    truth_111: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// Exactly one input high yields SUM=1 and COUT=0.
    onehot_sum_only: assert property (
        @(posedge CLK) $onehot({A,B,CI}) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

// Exactly two inputs high yields SUM=0 and COUT=1.
    two_ones_cout_only: assert property (
        @(posedge CLK) ((A & B & ~CI) | (A & CI & ~B) | (B & CI & ~A)) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

// SUM=1 and COUT=1 implies all three inputs are 1.
    sum_and_cout_imply_three_ones: assert property (
        @(posedge CLK) (SUM == 1'b1 && COUT == 1'b1) |-> (A & B & CI)
    );

// When load is HIGH, next Q equals current input_data.
    check_load_captures_input_data: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

// When load is LOW and up_down is HIGH, next Q increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == (($past(Q) + 1) & 4'hF))
    );

// When load is LOW and up_down is LOW, next Q decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == (($past(Q) - 1) & 4'hF))
    );

// Increment from 0xF wraps to 0x0 when not loading.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrement from 0x0 wraps to 0xF when not loading.
    check_wrap_decrement_from_min: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Two consecutive UP steps (no load) increment Q by 2 (mod 16).
    check_two_cycle_increment: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && up_down) |=> (Q == (($past(Q,2) + 2) & 4'hF))
    );

// Two consecutive DOWN steps (no load) decrement Q by 2 (mod 16).
    check_two_cycle_decrement: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && !up_down) |=> (Q == (($past(Q,2) - 2) & 4'hF))
    );

// UP followed by DOWN with no loads returns Q to original value after 2 cycles.
    check_up_then_down_cancels: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && !up_down) |=> (Q == $past(Q,2))
    );

// DOWN followed by UP with no loads returns Q to original value after 2 cycles.
    check_down_then_up_cancels: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && up_down) |=> (Q == $past(Q,2))
    );

// Two consecutive loads use the second cycle's input_data value.
    check_two_consecutive_loads_use_second_value: assert property (
        @(posedge clk) load ##1 load |=> (Q == $past(input_data,1))
    );

// Clock: clk (posedge). No explicit reset. Mixed logic: sequential counter, combinational diffs with clear gating.

   // count_clk must be 0 when clear is 2'b10 or 2'b11.
   check_count_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (count_clk == 32'd0)
   );

// pos_diff_x must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffx_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == 16'd0)
   );

// pos_diff_y must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffy_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == 16'd0)
   );

// pos_diff_x equals pos11 - pos21 when clear is not 2'b10 or 2'b11.
   check_posdiffx_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == (pos11 - pos21))
   );

// pos_diff_y equals pos12 - pos22 when clear is not 2'b10 or 2'b11.
   check_posdiffy_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == (pos12 - pos22))
   );

// With two consecutive active cycles, count_clk increments by 1 each cycle.
   check_count_inc_on_two_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk) + 32'd1)
   );

// With three consecutive active cycles, count_clk increases by 2 over two cycles.
   check_count_inc_by_two_on_three_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk,2) + 32'd2)
   );

// product1 equals button1 & ~coin
    check_product1_func_equiv: assert property (
        @(posedge CLK) product1 == (button1 & ~coin)
    );

// product2 equals button2 & ~coin
    check_product2_func_equiv: assert property (
        @(posedge CLK) product2 == (button2 & ~coin)
    );

// product3 equals button3 & ~coin
    check_product3_func_equiv: assert property (
        @(posedge CLK) product3 == (button3 & ~coin)
    );

// change equals coin
    check_change_equals_coin: assert property (
        @(posedge CLK) change == coin
    );

// If coin is HIGH, all product outputs must be LOW
    check_coin_high_blocks_products: assert property (
        @(posedge CLK) coin |-> !(product1 | product2 | product3)
    );

// If any button is pressed with coin LOW, at least one product is HIGH
    check_any_button_no_coin_causes_some_product: assert property (
        @(posedge CLK) (~coin & (button1 | button2 | button3)) |-> (product1 | product2 | product3)
    );

// product1 HIGH implies button1 is HIGH
    check_product1_implies_button1: assert property (
        @(posedge CLK) product1 |-> button1
    );

// product2 HIGH implies button2 is HIGH
    check_product2_implies_button2: assert property (
        @(posedge CLK) product2 |-> button2
    );

// product3 HIGH implies button3 is HIGH
    check_product3_implies_button3: assert property (
        @(posedge CLK) product3 |-> button3
    );

// Products and change are mutually exclusive
    check_change_and_products_mutex: assert property (
        @(posedge CLK) (product1 | product2 | product3) |-> !change
    );

///// Reset behavior /////
    // When reset is asserted (active-low), COUNT is 0 in the same cycle.
    reset_level_forces_zero: assert property (
        @(posedge clk) (RST == 1'b0) |-> (COUNT == 4'b0000)
    );

// If reset was asserted in the previous cycle, COUNT is 0 now.
    reset_previous_cycle_low_forces_zero: assert property (
        @(posedge clk) ($past(RST) == 1'b0) |-> (COUNT == 4'b0000)
    );

// On a sampled falling edge of reset, COUNT is 0.
    reset_fall_sampled_forces_zero: assert property (
        @(posedge clk) $fell(RST) |-> (COUNT == 4'b0000)
    );

// On a sampled rising edge of reset (previous cycle in reset), COUNT is 0.
    reset_rise_sampled_shows_zero: assert property (
        @(posedge clk) $rose(RST) |-> (COUNT == 4'b0000)
    );

// Reset has priority over enable; if both active, COUNT is 0.
    reset_priority_over_enable: assert property (
        @(posedge clk) (RST == 1'b0 && EN == 1'b1) |-> (COUNT == 4'b0000)
    );

// COUNT must be known while reset is asserted.
    no_x_during_reset: assert property (
        @(posedge clk) (RST == 1'b0) |-> (!$isunknown(COUNT))
    );

// Functional equivalence sampled on addr[2] edge: ce = addr[2] & ~Q & ~addr[1] & ~addr[0].
    check_function_on_addr2_edge: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// Functional equivalence sampled on addr[3] edge (addr[3] is don't-care in RTL).
    check_function_on_addr3_edge: assert property (
        @(posedge bus2ip_addr_i_reg[3])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// Functional equivalence sampled on addr[4] edge (addr[4] is don't-care in RTL).
    check_function_on_addr4_edge: assert property (
        @(posedge bus2ip_addr_i_reg[4])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// If addr[2]==1, Q==0, and addr[1:0]==2'b00, output must be HIGH.
    check_unique_high_condition_sufficient: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            ((bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0]) |-> (ce_expnd_i_5 == 1'b1))
    );

// If output is HIGH, then addr[2]==1, Q==0, and addr[1:0]==2'b00 must hold.
    check_unique_high_condition_necessary: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            (ce_expnd_i_5 == 1'b1 |-> (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0]))
    );

// With addr[2]==1, any disqualifier (Q or addr[1] or addr[0]) HIGH forces output LOW.
    check_disqualifiers_force_zero_on_addr2: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            (((Q == 1'b1) || (bus2ip_addr_i_reg[1] == 1'b1) || (bus2ip_addr_i_reg[0] == 1'b1)) |-> (ce_expnd_i_5 == 1'b0))
    );

// mod takes only values produced by the decode
    check_mod_value_set: assert property (
        @(posedge clk) disable iff (!rst_n)
        mod inside {8'h00,8'h01,8'h02,8'h03,8'h04,8'h05,8'h06,8'h07,8'h08,8'h09,8'h0a,8'h0b}
    );

// If addr[31:20]==0x000 then mod==0
    decode_000_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'h000) |-> (mod == 8'h00)
    );

// If addr[31:24]==0x10 then mod==1
    decode_10_to_1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:24] == 8'h10) |-> (mod == 8'h01)
    );

// If addr[31:20]==0xf00 then mod==2
    decode_f00_to_2: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf00) |-> (mod == 8'h02)
    );

// If addr[31:20]==0xf06 then mod==8
    decode_f06_to_8: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf06) |-> (mod == 8'h08)
    );

// If addr[31:20]==0xf07 then mod==10
    decode_f07_to_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf07) |-> (mod == 8'h0a)
    );

// If addr[31:20]==0xf08 then mod==11
    decode_f08_to_11: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf08) |-> (mod == 8'h0b)
    );

// If addr[31:20]==0xf0a then mod==9
    decode_f0a_to_9: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf0a) |-> (mod == 8'h09)
    );

// If no decode case matches, mod==0 (default)
    decode_default_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(
            (addr[31:20] == 12'h000) ||
            (addr[31:24] == 8'h10)   ||
            (addr[31:20] inside {12'hf00,12'hf01,12'hf02,12'hf03,12'hf04,12'hf05,12'hf06,12'hf07,12'hf08,12'hf0a})
        ) |-> (mod == 8'h00)
    );

// If mod==1 then addr[31:24]==0x10
    mod1_implies_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (addr[31:24] == 8'h10)
    );

// If mod==10 then addr[31:20]==0xf07
    mod10_implies_f07: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0a) |-> (addr[31:20] == 12'hf07)
    );

// If mod==11 then addr[31:20]==0xf08
    mod11_implies_f08: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0b) |-> (addr[31:20] == 12'hf08)
    );

// If mod==9 then addr[31:20]==0xf0a
    mod9_implies_f0a: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h09) |-> (addr[31:20] == 12'hf0a)
    );

// eff_addr must equal the function of mod and addr
    check_eff_addr_function: assert property (
        @(posedge clk) disable iff (!rst_n)
        eff_addr == ((mod == 8'h01) ? {8'h00, addr[23:0]} : {12'h000, addr[19:0]})
    );

// When mod==1, eff_addr upper 8 bits are zero and low 24 mirror addr
    eff_addr_when_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (eff_addr[31:24] == 8'h00) && (eff_addr[23:0] == addr[23:0])
    );

// When mod!=1, eff_addr upper 12 bits are zero and low 20 mirror addr
    eff_addr_when_not_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod != 8'h01) |-> (eff_addr[31:20] == 12'h000) && (eff_addr[19:0] == addr[19:0])
    );

// X equals its defined boolean function.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

// When B1_N is LOW, X equals A2.
    check_b1n_low_gives_a2: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == A2)
    );

// When B1_N is HIGH, X equals ~A1.
    check_b1n_high_gives_not_a1: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == (~A1))
    );

// When A1 is LOW, X equals (A2 | B1_N).
    check_a1_low_gives_a2_or_b1n: assert property (
        @(posedge CLK) (A1 == 1'b0) |-> (X == (A2 | B1_N))
    );

// When A1 is HIGH, X equals (A2 & ~B1_N).
    check_a1_high_gives_a2_and_not_b1n: assert property (
        @(posedge CLK) (A1 == 1'b1) |-> (X == (A2 & ~B1_N))
    );

// When A2 is LOW, X equals (~A1 & B1_N).
    check_a2_low_gives_not_a1_and_b1n: assert property (
        @(posedge CLK) (A2 == 1'b0) |-> (X == ((~A1) & B1_N))
    );

// When A2 is HIGH, X equals (~A1 | ~B1_N).
    check_a2_high_gives_not_a1_or_not_b1n: assert property (
        @(posedge CLK) (A2 == 1'b1) |-> (X == ((~A1) | (~B1_N)))
    );

// Corner: A1=0, A2=0, B1_N=0 => X=0.
    check_corner_all_zeroes: assert property (
        @(posedge CLK) (A1==1'b0 && A2==1'b0 && B1_N==1'b0) |-> (X==1'b0)
    );

// Corner: A1=1, A2=1, B1_N=0 => X=1.
    check_corner_a1a2_high_b1n_low: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b0) |-> (X==1'b1)
    );

// Corner: A1=1, A2=1, B1_N=1 => X=0.
    check_corner_a1a2_high_b1n_high: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b1) |-> (X==1'b0)
    );

// Clock: CK (posedge). Reset: none. Logic: combinational 2:1 mux (E ? SE : CK).

    // ECK implements (E & SE) | (!E & CK).
    check_mux_equation: assert property (
        @(posedge CK) ECK == ((E & SE) | (!E & CK))
    );

// When E is 1, ECK follows SE.
    check_E_high_selects_SE: assert property (
        @(posedge CK) (E == 1'b1) |-> (ECK == SE)
    );

// When E is 0, ECK follows CK.
    check_E_low_selects_CK: assert property (
        @(posedge CK) (E == 1'b0) |-> (ECK == CK)
    );

// If SE equals CK, ECK equals that common value.
    check_equal_inputs_hold: assert property (
        @(posedge CK) (SE == CK) |-> (ECK == CK)
    );

// If ECK is 1, it must be driven by E&SE or !E&CK.
    check_eck_one_implication: assert property (
        @(posedge CK) (ECK == 1'b1) |-> ((E & SE) | (!E & CK))
    );

// If ECK is 0, it must be driven by E&!SE or !E&!CK.
    check_eck_zero_implication: assert property (
        @(posedge CK) (ECK == 1'b0) |-> ((E & !SE) | (!E & !CK))
    );

// Combinational 16:1 mux: data_o equals the selected input.

    // When select==0, output equals data_i00.
    check_mux_sel_0: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h0) |-> (data_o == data_i00)
    );

// When select==1, output equals data_i01.
    check_mux_sel_1: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h1) |-> (data_o == data_i01)
    );

// When select==2, output equals data_i02.
    check_mux_sel_2: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h2) |-> (data_o == data_i02)
    );

// When select==3, output equals data_i03.
    check_mux_sel_3: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h3) |-> (data_o == data_i03)
    );

// When select==4, output equals data_i04.
    check_mux_sel_4: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h4) |-> (data_o == data_i04)
    );

// When select==5, output equals data_i05.
    check_mux_sel_5: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h5) |-> (data_o == data_i05)
    );

// When select==6, output equals data_i06.
    check_mux_sel_6: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h6) |-> (data_o == data_i06)
    );

// When select==7, output equals data_i07.
    check_mux_sel_7: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h7) |-> (data_o == data_i07)
    );

// When select==8, output equals data_i08.
    check_mux_sel_8: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h8) |-> (data_o == data_i08)
    );

// When select==9, output equals data_i09.
    check_mux_sel_9: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h9) |-> (data_o == data_i09)
    );

// When select==10, output equals data_i10.
    check_mux_sel_10: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hA) |-> (data_o == data_i10)
    );

// When select==11, output equals data_i11.
    check_mux_sel_11: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hB) |-> (data_o == data_i11)
    );

// When select==12, output equals data_i12.
    check_mux_sel_12: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hC) |-> (data_o == data_i12)
    );

// When select==13, output equals data_i13.
    check_mux_sel_13: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hD) |-> (data_o == data_i13)
    );

// When select==14, output equals data_i14.
    check_mux_sel_14: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hE) |-> (data_o == data_i14)
    );

// When select==15, output equals data_i15.
    check_mux_sel_15: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hF) |-> (data_o == data_i15)
    );

// Clock: mdio_mdc; Reset: none. Logic: combinational pass-through and AND on mdio_i.

    // phy0_mdc mirrors mdio_mdc.
    check_phy0_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdc == mdio_mdc)
    );

// phy1_mdc mirrors mdio_mdc.
    check_phy1_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdc == mdio_mdc)
    );

// phy0_mdio_t mirrors mdio_t.
    check_phy0_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == mdio_t)
    );

// phy1_mdio_t mirrors mdio_t.
    check_phy1_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_t == mdio_t)
    );

// phy0_mdio_o mirrors mdio_o.
    check_phy0_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == mdio_o)
    );

// phy1_mdio_o mirrors mdio_o.
    check_phy1_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_o == mdio_o)
    );

// mdio_i is the AND of phy0_mdio_i and phy1_mdio_i.
    check_mdio_i_and: assert property (
        @(posedge mdio_mdc) (mdio_i == (phy0_mdio_i & phy1_mdio_i))
    );

// The two PHY MDC outputs are identical.
    check_mdc_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdc == phy1_mdc)
    );

// The two PHY MDIO_t outputs are identical.
    check_t_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == phy1_mdio_t)
    );

// The two PHY MDIO_o outputs are identical.
    check_o_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == phy1_mdio_o)
    );

// If either PHY MDIO input is 0, mdio_i must be 0.
    check_mdio_i_zero_if_any_zero: assert property (
        @(posedge mdio_mdc) ((!phy0_mdio_i) || (!phy1_mdio_i)) |-> (mdio_i == 1'b0)
    );

// If both PHY MDIO inputs are 1, mdio_i must be 1.
    check_mdio_i_one_if_both_one: assert property (
        @(posedge mdio_mdc) (phy0_mdio_i && phy1_mdio_i) |-> (mdio_i == 1'b1)
    );

// Combinational module; no reset in RTL. clk is a sampling clock for SVA.
    // out1 is the AND of in1..in9 via the internal and*_out chain.

    // and0 implements in1 & in2.
    check_and0_func: assert property (
        @(posedge clk) and0_out == (in1 & in2)
    );

// and1 implements in3 & in4.
    check_and1_func: assert property (
        @(posedge clk) and1_out == (in3 & in4)
    );

// and2 implements in5 & in6.
    check_and2_func: assert property (
        @(posedge clk) and2_out == (in5 & in6)
    );

// and3 implements in7 & in8.
    check_and3_func: assert property (
        @(posedge clk) and3_out == (in7 & in8)
    );

// and4 combines and0_out & and1_out.
    check_and4_func: assert property (
        @(posedge clk) and4_out == (and0_out & and1_out)
    );

// and5 combines and2_out & and3_out.
    check_and5_func: assert property (
        @(posedge clk) and5_out == (and2_out & and3_out)
    );

// and6 combines and4_out & and5_out.
    check_and6_func: assert property (
        @(posedge clk) and6_out == (and4_out & and5_out)
    );

// and7 combines and6_out & in9.
    check_and7_func: assert property (
        @(posedge clk) and7_out == (and6_out & in9)
    );

// buf drives out1 from and7_out.
    check_buf_func: assert property (
        @(posedge clk) out1 == and7_out
    );

// out1 equals the AND of all nine inputs.
    check_out1_all_inputs_and: assert property (
        @(posedge clk) out1 == (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9)
    );

///// Reset behavior /////
    // During active-low reset, address registers hold their reset values.
    reset_defaults: assert property (
        @(posedge clk) !reset_b |-> (address_port_0 == 8'h00) && (address_port_1 == 8'h01) && (address_port_2 == 8'h02) && (address_port_3 == 8'h03)
    );

///// Read mux /////
    // mem_addr==2'b00 maps mem_rdata to address_port_0.
    readmux_sel0: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b00) |-> (mem_rdata == address_port_0)
    );

// mem_addr==2'b01 maps mem_rdata to address_port_1.
    readmux_sel1: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b01) |-> (mem_rdata == address_port_1)
    );

// mem_addr==2'b10 maps mem_rdata to address_port_2.
    readmux_sel2: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b10) |-> (mem_rdata == address_port_2)
    );

// mem_addr==2'b11 maps mem_rdata to address_port_3.
    readmux_sel3: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b11) |-> (mem_rdata == address_port_3)
    );

///// Write behavior /////
    // Write to addr 0 updates address_port_0 by next cycle unless immediately rewritten next cycle.
    write_addr0_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b00)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b00)) ? 1'b1 : (address_port_0 == $past(mem_wdata)) )
    );

// Write to addr 1 updates address_port_1 by next cycle unless immediately rewritten next cycle.
    write_addr1_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b01)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b01)) ? 1'b1 : (address_port_1 == $past(mem_wdata)) )
    );

// Write to addr 2 updates address_port_2 by next cycle unless immediately rewritten next cycle.
    write_addr2_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b10)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b10)) ? 1'b1 : (address_port_2 == $past(mem_wdata)) )
    );

// Write to addr 3 updates address_port_3 by next cycle unless immediately rewritten next cycle.
    write_addr3_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b11)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b11)) ? 1'b1 : (address_port_3 == $past(mem_wdata)) )
    );

// Reset drives data_out and encrypted_data to zero.
  reset_clears_regs: assert property (
    @(posedge clk) reset |-> (data_out == 8'h00) && (encrypted_data == 8'h00)
  );

// With enable=0, data_out passes through data_in on the next cycle.
  en0_bypass_data_out: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (data_out == $past(data_in))
  );

// Back-to-back enable cycles propagate the first cycle's XOR to data_out two cycles later.
  back_to_back_enable_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |=> (data_out == $past(data_in ^ key, 2))
  );

// Reset low must force count to zero at the clock edge.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

// On a sampled falling edge of reset, count is zero.
    check_fall_of_reset_drives_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'b0000)
    );

// On a sampled rising edge of reset, count becomes one.
    check_rise_of_reset_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0001)
    );

// On a sampled rising edge of reset, previous cycle's count was zero.
    check_prev_zero_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> ($past(count) == 4'b0000)
    );

// When not in reset, count is always within 4-bit range.
    check_count_range_when_active: assert property (
        @(posedge clk) disable iff (~rst) (count inside {[4'h0:4'hF]})
    );

// Analysis: No clock/reset in RTL; purely combinational always @(*); out = en ? selected in : 4'b0000.

    // en low forces out to zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0) (!en) |-> (out == 4'b0000)
    );

// When en=1 and sel==00, out equals in0.
    check_sel_00_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b00)) |-> (out == in0)
    );

// When en=1 and sel==01, out equals in1.
    check_sel_01_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b01)) |-> (out == in1)
    );

// When en=1 and sel==10, out equals in2.
    check_sel_10_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b10)) |-> (out == in2)
    );

// When en=1 and sel==11, out equals in3.
    check_sel_11_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b11)) |-> (out == in3)
    );

// Functional equivalence to the mux with enable.
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
            out == (en ? (sel == 2'b00 ? in0 :
                          sel == 2'b01 ? in1 :
                          sel == 2'b10 ? in2 : in3)
                      : 4'b0000)
    );

// Reset drives q and carry LOW when rst is HIGH at the clock edge.
  check_reset_outputs: assert property (
    @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
  );

// No spurious carry when last q was mid-range (1..14).
  check_no_carry_midrange: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && ($past(q) != 4'd0) && ($past(q) != 4'hF))
      |-> (carry == 1'b0)
  );

///// Functional mapping /////
    // flash_sector equals the combinational mapping function of sector.
    check_mapping_function_equivalence: assert property (
        @(posedge CLK)
        flash_sector == (
            (sector == 3'd1) ? SECTOR1_MAP :
            (sector == 3'd2) ? SECTOR2_MAP :
            (sector == 3'd3) ? SECTOR3_MAP :
            (sector == 3'd4) ? SECTOR4_MAP :
            (sector == 3'd5) ? SECTOR5_MAP :
            3'b000
        )
    );

// Sector 1 maps to SECTOR1_MAP.
    check_map_sector1: assert property (
        @(posedge CLK) (sector == 3'd1) |-> (flash_sector == SECTOR1_MAP)
    );

// Sector 2 maps to SECTOR2_MAP.
    check_map_sector2: assert property (
        @(posedge CLK) (sector == 3'd2) |-> (flash_sector == SECTOR2_MAP)
    );

// Sector 3 maps to SECTOR3_MAP.
    check_map_sector3: assert property (
        @(posedge CLK) (sector == 3'd3) |-> (flash_sector == SECTOR3_MAP)
    );

// Sector 4 maps to SECTOR4_MAP.
    check_map_sector4: assert property (
        @(posedge CLK) (sector == 3'd4) |-> (flash_sector == SECTOR4_MAP)
    );

// Sector 5 maps to SECTOR5_MAP.
    check_map_sector5: assert property (
        @(posedge CLK) (sector == 3'd5) |-> (flash_sector == SECTOR5_MAP)
    );

// Invalid sector 0 maps to 3'b000.
    check_invalid_sector_0: assert property (
        @(posedge CLK) (sector == 3'd0) |-> (flash_sector == 3'b000)
    );

// Invalid sector 6 maps to 3'b000.
    check_invalid_sector_6: assert property (
        @(posedge CLK) (sector == 3'd6) |-> (flash_sector == 3'b000)
    );

// Invalid sector 7 maps to 3'b000.
    check_invalid_sector_7: assert property (
        @(posedge CLK) (sector == 3'd7) |-> (flash_sector == 3'b000)
    );

// flash_sector is always one of the defined map values or 3'b000.
    check_output_membership: assert property (
        @(posedge CLK) flash_sector inside {SECTOR1_MAP, SECTOR2_MAP, SECTOR3_MAP, SECTOR4_MAP, SECTOR5_MAP, 3'b000}
    );

// Count is cleared to 0 whenever rst_n is LOW (synchronous reset).
    reset_clears_count: assert property (
        @(posedge clk) !rst_n |-> (count == 16'h0000)
    );

// While reset remains asserted across cycles, count stays 0.
    check_hold_zero_while_in_reset: assert property (
        @(posedge clk) ($past(!rst_n) && !rst_n) |-> (count == 16'h0000)
    );

///// Bit[1]/[2]/[3] select behavior on sel[0] edges /////
    // When sel[0] rises, out[1] takes in1[1].
    out1_follows_in1_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[1] == in1[1])
    );

// When sel[0] falls, out[1] takes in0[1].
    out1_follows_in0_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[1] == in0[1])
    );

// When sel[0] rises, out[2] takes in3[2].
    out2_follows_in3_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[2] == in3[2])
    );

// When sel[0] falls, out[2] takes in2[2].
    out2_follows_in2_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[2] == in2[2])
    );

// When sel[0] rises, out[3] takes in1[3].
    out3_follows_in1_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[3] == in1[3])
    );

// When sel[0] falls, out[3] takes in0[3].
    out3_follows_in0_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[3] == in0[3])
    );

// Functional equivalence: Y = ~(~B1_N | (A1 & A2)).
    check_eq_nor_form: assert property (
        @(posedge CLK) Y == ~( (~B1_N) | (A1 & A2) )
    );

// Functional equivalence (DeMorgan): Y = B1_N & (~A1 | ~A2).
    check_eq_demorgan_form: assert property (
        @(posedge CLK) Y == (B1_N & ((~A1) | (~A2)))
    );

// B1_N LOW forces Y LOW.
    check_b1n_low_forces_y_low: assert property (
        @(posedge CLK) (!B1_N) |-> (Y == 1'b0)
    );

// A1&A2 HIGH forces Y LOW.
    check_and_high_forces_y_low: assert property (
        @(posedge CLK) (A1 && A2) |-> (Y == 1'b0)
    );

// When no AND (A1==0 or A2==0), Y passes B1_N.
    check_passthrough_when_no_and: assert property (
        @(posedge CLK) (!(A1 && A2)) |-> (Y == B1_N)
    );

// If B1_N HIGH and no AND, Y must be HIGH.
    check_high_condition: assert property (
        @(posedge CLK) (B1_N && !(A1 && A2)) |-> (Y == 1'b1)
    );

// Y HIGH implies B1_N HIGH and no AND.
    check_y_high_implies_inputs: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (B1_N && (!A1 || !A2))
    );

// Y LOW implies B1_N LOW or A1&A2 HIGH.
    check_y_low_implies_inputs: assert property (
        @(posedge CLK) (Y == 1'b0) |-> ((!B1_N) || (A1 && A2))
    );

// If B1_N HIGH and Y LOW, then A1&A2 must be HIGH.
    check_b1n_high_y_low_implies_and: assert property (
        @(posedge CLK) (B1_N && (Y == 1'b0)) |-> (A1 && A2)
    );

// Y rising edge only when B1_N HIGH and no AND.
    check_y_rise_condition: assert property (
        @(posedge CLK) $rose(Y) |-> (B1_N && (!A1 || !A2))
    );

// Y falling edge only when B1_N LOW or A1&A2 HIGH.
    check_y_fall_condition: assert property (
        @(posedge CLK) $fell(Y) |-> ((!B1_N) || (A1 && A2))
    );

// Clock: clk posedge. No reset.
    // Sequential: data updates on en; holds when en==0.
    // Behavior: ROM mapping for addr 0..15; default assigns X.

    // Data holds its value when en is LOW.
    hold_when_en_low: assert property (
        @(posedge clk) !en |=> $stable(data)
    );

// When en is HIGH and addr==0, next data is 0010.
    map_addr_0: assert property (
        @(posedge clk) en && (addr == 5'b00000) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==1, next data is 0010.
    map_addr_1: assert property (
        @(posedge clk) en && (addr == 5'b00001) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==2, next data is 1110.
    map_addr_2: assert property (
        @(posedge clk) en && (addr == 5'b00010) |=> (data == 4'b1110)
    );

// When en is HIGH and addr==3, next data is 0010.
    map_addr_3: assert property (
        @(posedge clk) en && (addr == 5'b00011) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==4, next data is 0100.
    map_addr_4: assert property (
        @(posedge clk) en && (addr == 5'b00100) |=> (data == 4'b0100)
    );

// When en is HIGH and addr==5, next data is 1010.
    map_addr_5: assert property (
        @(posedge clk) en && (addr == 5'b00101) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==6, next data is 1100.
    map_addr_6: assert property (
        @(posedge clk) en && (addr == 5'b00110) |=> (data == 4'b1100)
    );

// When en is HIGH and addr==7, next data is 0000.
    map_addr_7: assert property (
        @(posedge clk) en && (addr == 5'b00111) |=> (data == 4'b0000)
    );

// When en is HIGH and addr==8, next data is 1010.
    map_addr_8: assert property (
        @(posedge clk) en && (addr == 5'b01000) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==9, next data is 0010.
    map_addr_9: assert property (
        @(posedge clk) en && (addr == 5'b01001) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==10, next data is 1110.
    map_addr_10: assert property (
        @(posedge clk) en && (addr == 5'b01010) |=> (data == 4'b1110)
    );

// When en is HIGH and addr==11, next data is 0010.
    map_addr_11: assert property (
        @(posedge clk) en && (addr == 5'b01011) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==12, next data is 0100.
    map_addr_12: assert property (
        @(posedge clk) en && (addr == 5'b01100) |=> (data == 4'b0100)
    );

// When en is HIGH and addr==13, next data is 1010.
    map_addr_13: assert property (
        @(posedge clk) en && (addr == 5'b01101) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==14, next data is 1100.
    map_addr_14: assert property (
        @(posedge clk) en && (addr == 5'b01110) |=> (data == 4'b1100)
    );

// When en is HIGH and addr==15, next data is 0000.
    map_addr_15: assert property (
        @(posedge clk) en && (addr == 5'b01111) |=> (data == 4'b0000)
    );

// For en HIGH and addr in 0..15, next data is not X/Z.
    nonx_when_valid_addr: assert property (
        @(posedge clk) en && (addr[4] == 1'b0) |=> !$isunknown(data)
    );

// Clock: clk posedge. Reset: rst synchronous active-high. Counter increments on en, holds otherwise.

  // Reset drives count to 0 on each asserted cycle.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 32'd0)
  );

// If both rst and en are HIGH, reset dominates and count is 0.
  reset_dominates_enable: assert property (
    @(posedge clk) (rst && en) |-> (count == 32'd0)
  );

// No clock/reset in RTL; combinational AND. Sample on posedge of i_bus1[0].

    // Output equals bitwise AND of inputs (vector-level).
    check_and_vector: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus1 & i_bus2)
    );

// Output is a subset of i_bus1 (no 1s where i_bus1 has 0s).
    check_output_subset_input1: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus1) == 8'h00
    );

// Output is a subset of i_bus2 (no 1s where i_bus2 has 0s).
    check_output_subset_input2: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus2) == 8'h00
    );

// When i_bus1 is all 1s, o_bus passes through i_bus2.
    check_allones_i_bus1_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'hFF) |-> (o_bus == i_bus2)
    );

// When i_bus2 is all 1s, o_bus passes through i_bus1.
    check_allones_i_bus2_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'hFF) |-> (o_bus == i_bus1)
    );

// When i_bus1 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus1_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'h00) |-> (o_bus == 8'h00)
    );

// When i_bus2 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus2_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'h00) |-> (o_bus == 8'h00)
    );

// LSB equals AND of corresponding input bits.
    check_bit0_and: assert property (
        @(posedge i_bus1[0]) o_bus[0] == (i_bus1[0] & i_bus2[0])
    );

// MSB equals AND of corresponding input bits.
    check_bit7_and: assert property (
        @(posedge i_bus1[0]) o_bus[7] == (i_bus1[7] & i_bus2[7])
    );

// Output also equals AND with reversed operand order (commutativity).
    check_and_commutative_form: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus2 & i_bus1)
    );

// For valid BCD (0..9), output equals zero-extended input.
    check_valid_mapping: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out == {4'b0000, bcd_in})
    );

// For invalid BCD (>9), output defaults to zero.
    check_invalid_defaults_to_zero: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out == 8'd0)
    );

// Upper nibble of output is always zero.
    check_upper_nibble_zero: assert property (
        @(posedge CLK) bin_out[7:4] == 4'b0000
    );

// Output value is always between 0 and 9.
    check_output_range_0_to_9: assert property (
        @(posedge CLK) bin_out <= 8'd9
    );

// If output is zero, input is either 0 or invalid (>9).
    check_zero_output_input_condition: assert property (
        @(posedge CLK) (bin_out == 8'd0) |-> ((bcd_in == 4'd0) || (bcd_in >= 4'd10))
    );

// For valid inputs, lower nibble equals input value.
    check_lower_nibble_matches_on_valid: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out[3:0] == bcd_in)
    );

// For invalid inputs, lower nibble is zero.
    check_lower_nibble_zero_on_invalid: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out[3:0] == 4'd0)
    );

///// Combinational output relationship /////
    // out_if_else reflects whether q and data differ on any bit.
    check_out_matches_neq: assert property (
        @(posedge clk) out_if_else == (q != data)
    );

// out_if_else equals the reduction-OR of q ^ data.
    check_out_matches_xor_or: assert property (
        @(posedge clk) out_if_else == (|(q ^ data))
    );

///// Next-state behavior /////
    // Complete next-state function for q (priority: load over ena!=0).
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> q == (
            $past(load) ? $past(data) :
            (($past(ena) != 2'b00) ? {$past(q[97:0]), $past(q[99:98])} : $past(q))
        )
    );

// When load is asserted, q loads data on the next cycle.
    check_load_updates_from_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// When load is deasserted and ena!=0, q rotates left by 2 bits.
    check_shift_when_ena_nonzero: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q == {$past(q[97:0]), $past(q[99:98])})
    );

// When load is deasserted and ena==0, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

// Upper bits shift down by 2 when rotating (bits [99:2] from prior [97:0]).
    check_shift_upper_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[99:2] == $past(q[97:0]))
    );

// Lower bits wrap from prior top two bits when rotating (bits [1:0] from prior [99:98]).
    check_shift_lower_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[1:0] == $past(q[99:98]))
    );

// sel==00 routes a to o.
    check_sel00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (o === a)
    );

// sel==01 routes b to o.
    check_sel01_routes_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (o === b)
    );

// sel==10 routes c to o.
    check_sel10_routes_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (o === c)
    );

// sel==11 routes d to o.
    check_sel11_routes_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (o === d)
    );

// For known sel, o equals the selected input (single-expression form).
    check_function_when_sel_known: assert property (
        @(posedge clk) (!$isunknown(sel)) |-> (o === ((sel==2'b00) ? a :
                                                     (sel==2'b01) ? b :
                                                     (sel==2'b10) ? c : d))
    );

// When in==4'b1110, out must be 2'b00.
      map_in_1110_to_out_00: assert property (
        @(posedge clk) (in === 4'b1110) |-> (out == 2'b00)
      );

// When in==4'b1101, out must be 2'b01.
      map_in_1101_to_out_01: assert property (
        @(posedge clk) (in === 4'b1101) |-> (out == 2'b01)
      );

// When in==4'b1011, out must be 2'b10.
      map_in_1011_to_out_10: assert property (
        @(posedge clk) (in === 4'b1011) |-> (out == 2'b10)
      );

// When in==4'b0111, out must be 2'b11.
      map_in_0111_to_out_11: assert property (
        @(posedge clk) (in === 4'b0111) |-> (out == 2'b11)
      );

// For any input not matching the four patterns, out must be 2'b00 (default case).
      default_for_unmatched_inputs: assert property (
        @(posedge clk) (in !== 4'b1110) && (in !== 4'b1101) && (in !== 4'b1011) && (in !== 4'b0111) |-> (out == 2'b00)
      );

// out==2'b01 only occurs for in==4'b1101.
      only_out_01_on_1101: assert property (
        @(posedge clk) (out == 2'b01) |-> (in === 4'b1101)
      );

// out==2'b10 only occurs for in==4'b1011.
      only_out_10_on_1011: assert property (
        @(posedge clk) (out == 2'b10) |-> (in === 4'b1011)
      );

// out==2'b11 only occurs for in==4'b0111.
      only_out_11_on_0111: assert property (
        @(posedge clk) (out == 2'b11) |-> (in === 4'b0111)
      );

// No clock or reset in RTL; pure combinational. Assertions sampled on external CLK.
    // Functional behavior: Y = ~(A | B | C | D_N). Power pins unused in logic.

    // Y equals bitwise NOR of A,B,C,D_N.
    check_function_nor4b: assert property (
        @(posedge CLK) disable iff (1'b0) (Y === ~(A | B | C | D_N))
    );

// If any input is HIGH, Y must be LOW.
    check_any_high_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) (|{A,B,C,D_N}) |-> (Y == 1'b0)
    );

// If all inputs are LOW, Y must be HIGH.
    check_all_low_forces_high: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && !C && !D_N) |-> (Y == 1'b1)
    );

// If Y is HIGH, then all inputs are LOW.
    check_y_high_implies_all_low: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> (!A && !B && !C && !D_N)
    );

// If Y is LOW, then at least one input is HIGH.
    check_y_low_implies_any_high: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b0) |-> (|{A,B,C,D_N})
    );

// A rising to HIGH forces Y LOW.
    check_rose_A_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(A) |-> (Y == 1'b0)
    );

// B rising to HIGH forces Y LOW.
    check_rose_B_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(B) |-> (Y == 1'b0)
    );

// C rising to HIGH forces Y LOW.
    check_rose_C_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(C) |-> (Y == 1'b0)
    );

// D_N rising to HIGH forces Y LOW.
    check_rose_DN_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(D_N) |-> (Y == 1'b0)
    );

///// Reset behavior /////
    // On synchronous reset, counter=0 and precharge_safe=1 on next cycle.
    reset_sync_values: assert property (
        @(posedge sys_clk) sdram_rst |=> (counter == 3'd0) && (precharge_safe == 1'b1)
    );

// Y implements a 2:1 mux with EN selecting A over B.
    check_mux_function: assert property (
        @(posedge CLK) Y == (EN ? A : B)
    );

// When EN is 1, Y equals A.
    check_select_a_when_en: assert property (
        @(posedge CLK) EN |-> (Y == A)
    );

// When EN is 0, Y equals B.
    check_select_b_when_not_en: assert property (
        @(posedge CLK) !EN |-> (Y == B)
    );

// On EN rising edge, Y equals A in the same cycle.
    check_en_rise_selects_a: assert property (
        @(posedge CLK) $rose(EN) |-> (Y == A)
    );

// On EN falling edge, Y equals B in the same cycle.
    check_en_fall_selects_b: assert property (
        @(posedge CLK) $fell(EN) |-> (Y == B)
    );

// Clock: posedge shift. No reset present in RTL. Sequential update on shift edge; out is combinational mirror of register[7].

    // After each shift edge, at the next shift edge out equals the previous in.
    out_lags_in_by_one_shift: assert property (
        @(posedge shift) 1'b1 |=> (out == $past(in))
    );

// If in matches out at a shift edge, then at the next shift edge out remains the same.
    out_holds_when_in_matches: assert property (
        @(posedge shift) (in == out) |=> (out == $past(out))
    );

// When sel=1, OUT is two's complement of A.
    check_sel1_twos_comp: assert property (
        @(posedge CLK) sel |-> (OUT == ((~A) + 4'b0001))
    );

// When sel=1, A + OUT wraps to zero (4-bit two's complement identity).
    check_sel1_adds_to_zero: assert property (
        @(posedge CLK) sel |-> ((A + OUT) == 4'b0000)
    );

// When sel=1 and A==0, OUT==0.
    check_sel1_zero_case: assert property (
        @(posedge CLK) (sel && (A == 4'b0000)) |-> (OUT == 4'b0000)
    );

// When sel=1 and A==4'b1000, OUT==4'b1000 (min value is self-complement).
    check_sel1_min_value_fixed_point: assert property (
        @(posedge CLK) (sel && (A == 4'b1000)) |-> (OUT == 4'b1000)
    );

// If B equals two's complement of A, OUT equals that value regardless of sel.
    check_equal_paths_agree: assert property (
        @(posedge CLK) (B == ((~A) + 4'b0001)) |-> (OUT == B)
    );

// Output equals selected input functionally every cycle.
    check_mux_function_equivalence: assert property (
        @(posedge CLK) out == (sel ? b : a)
    );

// When sel=0, out mirrors a.
    check_route_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == a)
    );

// When sel=1, out mirrors b.
    check_route_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == b)
    );

// On sel rising edge, out equals b immediately.
    check_sel_rise_routes_b_now: assert property (
        @(posedge CLK) $rose(sel) |-> (out == b)
    );

// On sel falling edge, out equals a immediately.
    check_sel_fall_routes_a_now: assert property (
        @(posedge CLK) $fell(sel) |-> (out == a)
    );

// Combinational function: X equals A AND SLEEP_B.
    check_functional_and: assert property (
        @(posedge CLK) (X == (A & SLEEP_B))
    );

// When SLEEP_B is LOW, X must be LOW.
    check_sleep_b_low_forces_low: assert property (
        @(posedge CLK) (!SLEEP_B) |-> (X == 1'b0)
    );

// When SLEEP_B is HIGH, X equals A.
    check_sleep_b_high_transparent: assert property (
        @(posedge CLK) (SLEEP_B) |-> (X == A)
    );

// When A is LOW, X must be LOW.
    check_a_low_forces_low: assert property (
        @(posedge CLK) (!A) |-> (X == 1'b0)
    );

// X HIGH implies both A and SLEEP_B are HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A && SLEEP_B)
    );

// X rising requires both A and SLEEP_B HIGH.
    check_x_rise_requires_enabled_and_a: assert property (
        @(posedge CLK) $rose(X) |-> (A && SLEEP_B)
    );

// X falling requires A LOW or SLEEP_B LOW.
    check_x_fall_requires_either_low: assert property (
        @(posedge CLK) $fell(X) |-> ((!A) || (!SLEEP_B))
    );

// On SLEEP_B rising, X equals A in the same cycle.
    check_enable_rise_sets_x_equal_a: assert property (
        @(posedge CLK) $rose(SLEEP_B) |-> (X == A)
    );

// On SLEEP_B falling, X is forced LOW in the same cycle.
    check_enable_fall_forces_x_low: assert property (
        @(posedge CLK) $fell(SLEEP_B) |-> (X == 1'b0)
    );

// Reset drives out to zero on the next clock.
  reset_clears_out_on_next: assert property (
    @(posedge clk) rst |=> (out == 8'h00)
  );

// When not in reset, next out equals previous out plus previous data_in (mod 256).
  accumulate_updates: assert property (
    @(posedge clk) disable iff (rst) 1 |=> (out == $past(out) + $past(data_in))
  );

// With zero input, out holds its value across the next clock.
  hold_when_data_zero: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'h00) |=> (out == $past(out))
  );

// With input 1, out increments by one on the next clock (mod 256).
  inc_by_one_when_data_one: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'h01) |=> (out == $past(out) + 8'h01)
  );

// With input 0xFF, out decrements by one on the next clock (mod 256).
  dec_by_one_when_data_ff: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'hFF) |=> (out == $past(out) + 8'hFF)
  );

// Explicit wrap: 0xFF plus 1 wraps to 0 on the next clock.
  wrap_ff_plus_one_to_zero: assert property (
    @(posedge clk) disable iff (rst) (out == 8'hFF && data_in == 8'h01) |=> (out == 8'h00)
  );

// Combinational DUT with no reset; assertions are sampled on CLK.

    // When ctrl==00, result equals a+b (8-bit wrap-around).
    check_add_function: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (result == (a + b))
    );

// When ctrl==01, result equals a-b (8-bit wrap-around).
    check_sub_function: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (result == (a - b))
    );

// When ctrl==10, result equals a^b.
    check_xor_function: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (result == (a ^ b))
    );

// When ctrl==11, result is zero.
    check_default_zero: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (result == 8'h00)
    );

// Result matches the full case-expression behavior.
    check_case_equivalence: assert property (
        @(posedge CLK)
        result == ((ctrl == 2'b00) ? (a + b) :
                   (ctrl == 2'b01) ? (a - b) :
                   (ctrl == 2'b10) ? (a ^ b) :
                                     8'h00)
    );

// For XOR op, equal inputs yield zero.
    check_xor_equal_inputs_zero: assert property (
        @(posedge CLK) (ctrl == 2'b10 && (a == b)) |-> (result == 8'h00)
    );

// For XOR op, XOR with zero b returns a.
    check_xor_with_zero_b_returns_a: assert property (
        @(posedge CLK) (ctrl == 2'b10 && (b == 8'h00)) |-> (result == a)
    );

// For ADD op, adding zero b returns a.
    check_add_with_zero_b_returns_a: assert property (
        @(posedge CLK) (ctrl == 2'b00 && (b == 8'h00)) |-> (result == a)
    );

// For SUB op, equal inputs yield zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge CLK) (ctrl == 2'b01 && (a == b)) |-> (result == 8'h00)
    );

// o is the bitwise inversion of x.
    check_o_is_not_x: assert property (
        @(posedge clk) o == ~x
    );

// cfo is permanently 0.
    check_cfo_const_zero: assert property (
        @(posedge clk) cfo == 1'b0
    );

// ofo is permanently 0.
    check_ofo_const_zero: assert property (
        @(posedge clk) ofo == 1'b0
    );

// When x is all zeros, o is all ones.
    check_zero_x_allones_o: assert property (
        @(posedge clk) (x == 16'h0000) |-> (o == 16'hFFFF)
    );

// When x is all ones, o is all zeros.
    check_allones_x_zero_o: assert property (
        @(posedge clk) (x == 16'hFFFF) |-> (o == 16'h0000)
    );

// out must never be 11.
    check_out_never_11: assert property (
        @(posedge clk) !(out == 2'b11)
    );

// out[0] reflects (in1 > in2).
    check_bit0_matches_gt: assert property (
        @(posedge clk) out[0] == (in1 > in2)
    );

// out[1] reflects (in1 < in2).
    check_bit1_matches_lt: assert property (
        @(posedge clk) out[1] == (in1 < in2)
    );

// On reset, next cycle count must be zero.
    reset_clears_next: assert property (
        @(posedge CLK) reset |=> (count == 4'd0)
    );

// When disabled (and not in reset), hold value next cycle.
    hold_when_disabled: assert property (
        @(posedge CLK) disable iff (reset) (!enable) |=> (count == $past(count))
    );

// When enabled (and not in reset), increment by 1 next cycle (mod 16).
    increment_when_enabled: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When enabled at max value, wrap to 0 next cycle.
    wrap_on_max: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// LSB toggles on each enabled increment.
    lsb_toggle_on_inc: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count[0] == ~$past(count[0]))
    );

// Bit1 toggles on increment when there is carry from bit0 (bit0 was 1).
    bit1_toggle_with_carry: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count[0] == 1'b1)) |=> (count[1] == ~$past(count[1]))
    );

// Bit1 holds on increment when there is no carry from bit0 (bit0 was 0).
    bit1_hold_without_carry: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count[0] == 1'b0)) |=> (count[1] == $past(count[1]))
    );

// Two consecutive enables cause a net +2 after two cycles (mod 16).
    two_enables_add_two: assert property (
        @(posedge CLK) disable iff (reset) (enable ##1 enable) |=> (count == $past(count, 2) + 4'd2)
    );

// Two consecutive disables hold the value after two cycles.
    two_disables_hold: assert property (
        @(posedge CLK) disable iff (reset) ((!enable) ##1 (!enable)) |=> (count == $past(count, 2))
    );

// A rising edge of enable (no reset) causes a +1 next cycle.
    inc_on_enable_rise: assert property (
        @(posedge CLK) disable iff (reset) $rose(enable) |=> (count == $past(count) + 4'd1)
    );

// Reset drives storage, out_valid, and out_data to zero on the next cycle.
    reset_initializes: assert property (
        @(posedge clk) reset |=> (stored_data == 32'h0) && (out_valid == 1'b0) && (out_data == 32'h0)
    );

// When in_valid is 1, out_valid is 1 on the next cycle.
    out_valid_set_on_valid: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> out_valid
    );

// When in_valid is 0, out_valid is 0 on the next cycle.
    out_valid_clear_without_valid: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> !out_valid
    );

// When in_valid is 0, out_data holds its previous value.
    out_data_holds_without_valid: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> (out_data == $past(out_data))
    );

// On in_valid, out_data reflects the in_data from the previous cycle.
    out_data_reflects_input_on_valid: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> (out_data == $past(in_data))
    );

// Clock: clk (posedge). Reset: rst (active-high async).
    // Behavior: load copies x into shiftreg and clears out; shift outputs LSB and shifts right with zero fill; rst clears state.

    ///// Reset behavior /////
    // If reset is sampled HIGH, next cycle shiftreg and out are zero.
    reset_clears_state: assert property (
        @(posedge clk) rst |=> (shiftreg == 64'd0) && (out == 1'b0)
    );

// While reset is held across consecutive cycles, state is held at zero.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (shiftreg == 64'd0) && (out == 1'b0)
    );

///// Load behavior /////
    // Load clears out on the next cycle.
    load_clears_out: assert property (
        @(posedge clk) disable iff (rst) ld |=> (out == 1'b0)
    );

///// Priority /////
    // When ld and shift are both HIGH, out follows ld behavior (clears to 0).
    ld_priority_out: assert property (
        @(posedge clk) disable iff (rst) (ld && shift) |=> (rst || (out == 1'b0))
    );

// When op==000, out equals a + b (truncated to 4 bits).
    check_addition: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b000) |-> (out == (a + b))
    );

// When op==001, out equals a - b (truncated to 4 bits).
    check_subtraction: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b001) |-> (out == (a - b))
    );

// When op==010, out equals a & b.
    check_bitwise_and: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b010) |-> (out == (a & b))
    );

// When op==011, out equals a | b.
    check_bitwise_or: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b011) |-> (out == (a | b))
    );

// When op==100, out equals a ^ b.
    check_bitwise_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b100) |-> (out == (a ^ b))
    );

// When op==101, out equals {a[2:0], 1'b0} (shift left by 1 with zero fill).
    check_shift_left: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b101) |-> (out == {a[2:0], 1'b0})
    );

// When op is 110 or 111, out is 0 (default case).
    check_default_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (op inside {3'b110, 3'b111}) |-> (out == 4'b0000)
    );

// EQ reflects 4-state equality of A and B.
    def_eq_matches_relop: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

// GT reflects 4-state greater-than of A over B.
    def_gt_matches_relop: assert property (
        @(posedge CLK) (GT === (A > B))
    );

// LT reflects 4-state less-than of A under B.
    def_lt_matches_relop: assert property (
        @(posedge CLK) (LT === (A < B))
    );

// When inputs are known (no X/Z), exactly one of EQ/GT/LT is 1.
    onehot_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> $onehot({EQ,GT,LT})
    );

// When inputs are known, outputs must be known (no X/Z).
    no_x_on_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> (!$isunknown({EQ,GT,LT}))
    );

// pos selects index of lowest-order '1' in in (bit 0 has highest priority).
    check_pos_priority_bit0: assert property (
        @(posedge clk) in[0] |-> (pos == 3'd0)
    );

// pos==1 when in[1] is 1 and no lower bit is set.
    check_pos_priority_bit1: assert property (
        @(posedge clk) (in[1] && !in[0]) |-> (pos == 3'd1)
    );

// pos==2 when in[2] is 1 and no lower bit is set.
    check_pos_priority_bit2: assert property (
        @(posedge clk) (in[2] && !in[1] && !in[0]) |-> (pos == 3'd2)
    );

// pos==3 when in[3] is 1 and no lower bit is set.
    check_pos_priority_bit3: assert property (
        @(posedge clk) (in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd3)
    );

// pos==4 when in[4] is 1 and no lower bit is set.
    check_pos_priority_bit4: assert property (
        @(posedge clk) (in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd4)
    );

// pos==5 when in[5] is 1 and no lower bit is set.
    check_pos_priority_bit5: assert property (
        @(posedge clk) (in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd5)
    );

// pos==6 when in[6] is 1 and no lower bit is set.
    check_pos_priority_bit6: assert property (
        @(posedge clk) (in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd6)
    );

// pos==7 when in[7] is 1 and no lower bit is set.
    check_pos_priority_bit7: assert property (
        @(posedge clk) (in[7] && !in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd7)
    );

// When no bits are set, pos is 0.
    check_pos_when_none_set: assert property (
        @(posedge clk) (~|in) |-> (pos == 3'd0)
    );

// out_sum equals pos plus the selected mux output (b if both sel=1, else a if any sel=1, else 0).
    check_out_sum_matches_equation: assert property (
        @(posedge clk)
        out_sum == ({1'b0, pos} + {3'b0, ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0))})
    );

// When neither select is asserted, out_sum equals pos (mux_out=0).
    check_out_sum_sel00_no_add: assert property (
        @(posedge clk)
        (!sel_b1 && !sel_b2) |-> (out_sum == {1'b0, pos})
    );

// When exactly one select is asserted, out_sum equals pos + a.
    check_out_sum_sel_one_add_a: assert property (
        @(posedge clk)
        (sel_b1 ^ sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, a}))
    );

// When both selects are asserted, out_sum equals pos + b.
    check_out_sum_sel11_add_b: assert property (
        @(posedge clk)
        (sel_b1 && sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, b}))
    );

// The MSB of out_sum is high only when selected mux output is 1 and pos==7.
    check_out_sum_msb_carry: assert property (
        @(posedge clk)
        out_sum[3] == ( ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) & (&pos) )
    );

// Output equals bitwise OR of inputs.
    check_or_function: assert property (
        @(posedge clk) disable iff (clr) (y == (d0 | d1))
    );

// Output is 1 when either input is 1.
    check_output_high_when_any_high: assert property (
        @(posedge clk) disable iff (clr) ((d0 == 1'b1) || (d1 == 1'b1)) |-> (y == 1'b1)
    );

// Output is 0 when both inputs are 0.
    check_output_low_when_both_low: assert property (
        @(posedge clk) disable iff (clr) ((d0 == 1'b0) && (d1 == 1'b0)) |-> (y == 1'b0)
    );

// If output is 0, both inputs must be 0.
    check_zero_implies_both_zero: assert property (
        @(posedge clk) disable iff (clr) (y == 1'b0) |-> ((d0 == 1'b0) && (d1 == 1'b0))
    );

// If output is 1, at least one input must be 1.
    check_one_implies_any_one: assert property (
        @(posedge clk) disable iff (clr) (y == 1'b1) |-> ((d0 == 1'b1) || (d1 == 1'b1))
    );

// When d1 is 0, output equals d0.
    check_equals_d0_when_d1_zero: assert property (
        @(posedge clk) disable iff (clr) (d1 == 1'b0) |-> (y == d0)
    );

// When d0 is 0, output equals d1.
    check_equals_d1_when_d0_zero: assert property (
        @(posedge clk) disable iff (clr) (d0 == 1'b0) |-> (y == d1)
    );

// If inputs are known (not X/Z), output is known (not X/Z).
    check_no_unknown_output_when_inputs_known: assert property (
        @(posedge clk) disable iff (clr) (!$isunknown(d0) && !$isunknown(d1)) |-> !$isunknown(y)
    );

// Out equals S0 when Sel is 2'b00.
    check_sel00_routes_S0: assert property (
        @(posedge CLK) (Sel == 2'b00) |-> (out == S0)
    );

// Out equals S1 when Sel is 2'b01.
    check_sel01_routes_S1: assert property (
        @(posedge CLK) (Sel == 2'b01) |-> (out == S1)
    );

// Out equals S2 when Sel is 2'b10.
    check_sel10_routes_S2: assert property (
        @(posedge CLK) (Sel == 2'b10) |-> (out == S2)
    );

// Out equals S3 when Sel is 2'b11.
    check_sel11_routes_S3: assert property (
        @(posedge CLK) (Sel == 2'b11) |-> (out == S3)
    );

// Structural equivalence to the RTL ternary expression.
    check_functional_equivalence: assert property (
        @(posedge CLK) out == (Sel[1] ? (Sel[0] ? S3 : S2) : (Sel[0] ? S1 : S0))
    );

// When Sel[1]==0, out selects between S1 and S0 per Sel[0].
    check_lower_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b0) |-> (out == (Sel[0] ? S1 : S0))
    );

// When Sel[1]==1, out selects between S3 and S2 per Sel[0].
    check_upper_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b1) |-> (out == (Sel[0] ? S3 : S2))
    );

// Clock: posedge clk; Reset: active-high synchronous 'reset'; Logic: sequential.

    // Synchronous reset drives count=0 and overflow=0 on the following cycle.
    reset_clears_outputs_next: assert property (
        @(posedge clk) reset |=> (count == 4'h0) && (overflow == 1'b0)
    );

// When disabled, both outputs hold their previous values.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count)) && (overflow == $past(overflow))
    );

// With enable and count==15, next count wraps to 0 and overflow asserts.
    wrap_sets_overflow_and_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0) && (overflow == 1'b1)
    );

// With enable and count!=15, next count increments by 1.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (count == $past(count) + 4'd1)
    );

// With enable and count!=15, next overflow is 0.
    no_overflow_on_non_wrap: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (overflow == 1'b0)
    );

// When enabled, count must change on the next cycle.
    count_changes_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count != $past(count))
    );

// On reset, counter must be all zeros on the next cycle.
    check_reset_clears_counter_next: assert property (
        @(posedge clk) reset |=> (counter == 64'b0)
    );

// On reset, output must be all zeros on the next cycle.
    check_reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (output_val == 64'b0)
    );

// Output bits can only be 1 where the replicated input mask bits are 1.
    check_output_mask_subset: assert property (
        @(posedge clk) disable iff (reset)
            (output_val & ~{8{input_val}}) == 64'b0
    );

// If the input mask is all zeros, the output must be zero.
    check_output_zero_when_input_zero: assert property (
        @(posedge clk) disable iff (reset)
            (input_val == 8'h00) |-> (output_val == 64'b0)
    );

///// Functional equivalence /////
    // Z must equal TE_B & A when sampled on A rising.
    check_func_equiv_on_A: assert property (
        @(posedge A) Z == (TE_B & A)
    );

// Z must equal TE_B & A when sampled on TE_B rising.
    check_func_equiv_on_TEB: assert property (
        @(posedge TE_B) Z == (TE_B & A)
    );

///// Enable low forces zero /////
    // If TE_B is LOW, Z must be 0 (sampled on A rising).
    check_zero_when_teb_low_on_A: assert property (
        @(posedge A) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

///// Enable high passes A /////
    // If TE_B is HIGH, Z equals A (sampled on A rising).
    check_passthrough_when_teb_high_on_A: assert property (
        @(posedge A) (TE_B == 1'b1) |-> (Z == A)
    );

///// Output implications /////
    // If Z is HIGH, both TE_B and A must be HIGH (sampled on A rising).
    check_z_high_implies_inputs_high_on_A: assert property (
        @(posedge A) (Z == 1'b1) |-> (TE_B == 1'b1 && A == 1'b1)
    );

///// Output relationships /////
    // Q_N is always the bitwise inverse of Q.
    check_qn_is_invert_of_q: assert property (
        @(posedge CLK) (Q_N === ~Q)
    );

///// Capture behavior /////
    // Q captures the selected input (SCE ? SCD : D) from the previous cycle.
    check_q_captures_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q == $past(SCE ? SCD : D))
    );

// Q_N captures the inverse of the selected input from the previous cycle.
    check_qn_captures_inverted_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q_N === ~$past(SCE ? SCD : D))
    );

///// Scan enable selection /////
    // When SCE=0, Q captures D on the next rising edge.
    check_q_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q == $past(D))
    );

// When SCE=1, Q captures SCD on the next rising edge.
    check_q_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q == $past(SCD))
    );

// When SCE=0, Q_N captures ~D on the next rising edge.
    check_qn_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q_N === ~$past(D))
    );

// When SCE=1, Q_N captures ~SCD on the next rising edge.
    check_qn_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q_N === ~$past(SCD))
    );

// Y equals A_N | B_N | ~C | ~D.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (A_N | B_N | (~C) | (~D))
    );

// Y is 0 only when A_N=0, B_N=0, C=1, and D=1.
    check_y_zero_only_in_one_case: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// When C=1 and D=1, Y reduces to A_N | B_N.
    check_reduce_when_c_and_d_high: assert property (
        @(posedge clk) (C && D) |-> (Y == (A_N | B_N))
    );

// When A_N=0 and B_N=0, Y reduces to ~C | ~D.
    check_reduce_when_a_and_b_low: assert property (
        @(posedge clk) (!A_N && !B_N) |-> (Y == ((~C) | (~D)))
    );

// A_N=1 forces Y=1.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> (Y == 1'b1)
    );

// B_N=1 forces Y=1.
    check_b_n_high_forces_y_high: assert property (
        @(posedge clk) B_N |-> (Y == 1'b1)
    );

// C=0 forces Y=1.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (!C) |-> (Y == 1'b1)
    );

// D=0 forces Y=1.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) (!D) |-> (Y == 1'b1)
    );

// If Y=0 then A_N must be 0.
    check_y_zero_implies_a_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A_N == 1'b0)
    );

// If Y=0 then B_N must be 0.
    check_y_zero_implies_b_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (B_N == 1'b0)
    );

// If Y=0 then C must be 1.
    check_y_zero_implies_c_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (C == 1'b1)
    );

// If Y=0 then D must be 1.
    check_y_zero_implies_d_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (D == 1'b1)
    );

// On subtraction selection and B==0, Q must equal A.
    check_sub_identity_B_zero: assert property (
        @(posedge C) (B == 16'd0) |-> (Q == A)
    );

// On addition selection and B==0, Q must equal A.
    check_add_identity_B_zero: assert property (
        @(negedge C) (B == 16'd0) |-> (Q == A)
    );

// Pure combinational DUT: Y = ~(~B1_N | (A1 & A2)); no resets present.

    // Y implements the Boolean function from inputs.
    check_output_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y === ~( (~B1_N) | (A1 & A2) )
    );

// not gate: b = ~B1_N.
    check_not_gate: assert property (
        @(posedge CLK) disable iff (1'b0) b === ~B1_N
    );

// and gate: and0_out = A1 & A2.
    check_and_gate: assert property (
        @(posedge CLK) disable iff (1'b0) and0_out === (A1 & A2)
    );

// nor gate: nor0_out_Y = ~(b | and0_out).
    check_nor_gate: assert property (
        @(posedge CLK) disable iff (1'b0) nor0_out_Y === ~(b | and0_out)
    );

// buffer: Y = nor0_out_Y.
    check_buffer: assert property (
        @(posedge CLK) disable iff (1'b0) Y === nor0_out_Y
    );

// If B1_N is 0, Y must be 0.
    check_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N === 1'b0) |-> (Y === 1'b0)
    );

// If both A1 and A2 are 1, Y must be 0.
    check_both_a_high_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((A1 === 1'b1) && (A2 === 1'b1)) |-> (Y === 1'b0)
    );

// If B1_N is 1 and A1 is 0, Y must be 1.
    check_b1n_high_a1_low_sets_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N === 1'b1) && (A1 === 1'b0)) |-> (Y === 1'b1)
    );

// If B1_N is 1 and A2 is 0, Y must be 1.
    check_b1n_high_a2_low_sets_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N === 1'b1) && (A2 === 1'b0)) |-> (Y === 1'b1)
    );

// If Y is 1, then B1_N is 1 and not (A1 & A2).
    check_y_high_implies_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (Y === 1'b1) |-> ((B1_N === 1'b1) && !((A1 === 1'b1) && (A2 === 1'b1)))
    );

// When select=00, output is all zeros.
    check_sel00_zero: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b00) |-> (data_out == {W{1'b0}})
    );

// When select=10, output equals ch_1.
    check_sel10_pass_ch1: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b10) |-> (data_out == ch_1)
    );

// When select=11, output equals ch_2.
    check_sel11_pass_ch2: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b11) |-> (data_out == ch_2)
    );

// OUT must equal A + B modulo 16.
    check_sum_mod16: assert property (
        @(posedge CLK) OUT == (A + B)
    );

// LSB is XOR of inputs (CIN=0).
    check_bit0_xor: assert property (
        @(posedge CLK) OUT[0] == (A[0] ^ B[0])
    );

// Bit1 sum with carry from bit0.
    check_bit1_sum: assert property (
        @(posedge CLK) OUT[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

// Bit2 sum with carry from lower bits.
    check_bit2_sum: assert property (
        @(posedge CLK) OUT[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

// Bit3 sum with carry from lower bits.
    check_bit3_sum: assert property (
        @(posedge CLK) OUT[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

// Adding zero on A passes B through.
    check_a_zero_passthru: assert property (
        @(posedge CLK) (A == 4'h0) |-> (OUT == B)
    );

// Adding zero on B passes A through.
    check_b_zero_passthru: assert property (
        @(posedge CLK) (B == 4'h0) |-> (OUT == A)
    );

// 15 + 1 wraps to 0 (carry-out ignored).
    check_wrap_15_plus_1: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'h1)) |-> (OUT == 4'h0)
    );

// Note: No clock/reset in RTL; sample assertions on posedge of sel1.

  // When sel1=1 and sel2=1, out must equal d3.
  check_sel11_routes_d3: assert property (
    @(posedge sel1) (sel1 && sel2) |-> (out == d3)
  );

// When sel1=1 and sel2=0, out must equal d2.
  check_sel10_routes_d2: assert property (
    @(posedge sel1) (sel1 && !sel2) |-> (out == d2)
  );

// When sel1=0 and sel2=1, out must equal d1.
  check_sel01_routes_d1: assert property (
    @(posedge sel1) (!sel1 && sel2) |-> (out == d1)
  );

// When sel1=0 and sel2=0, out must equal d0.
  check_sel00_routes_d0: assert property (
    @(posedge sel1) (!sel1 && !sel2) |-> (out == d0)
  );

// Out equals the exact ternary selection used in the RTL.
  check_mux_functional_equivalence: assert property (
    @(posedge sel1) out == ((sel1 & sel2) ? d3 :
                            (sel1 & ~sel2) ? d2 :
                            (~sel1 & sel2) ? d1 :
                            d0)
  );

// Exactly one of the four selection minterms is true for any sel1/sel2.
  check_onehot_minterms: assert property (
    @(posedge sel1) $onehot({(sel1 & sel2), (sel1 & ~sel2), (~sel1 & sel2), (~sel1 & ~sel2)})
  );

// 5-bit result matches arithmetic sum of inputs.
    check_sum_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// LSB sum bit equals A0 ^ B0 ^ Ci.
    check_bit0_sum: assert property (
        @(posedge CLK) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit1 sum equals A1 ^ B1 ^ C0.
    check_bit1_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
    );

// Bit2 sum equals A2 ^ B2 ^ C1.
    check_bit2_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[2] == (A[2] ^ B[2] ^ (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
    );

// Bit3 sum equals A3 ^ B3 ^ C2.
    check_bit3_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[3] == (A[3] ^ B[3] ^ (
                        (A[2] & B[2]) |
                        ((A[2] ^ B[2]) & (
                            (A[1] & B[1]) |
                            ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                        ))
                    ))
    );

// Final carry-out equals (A3 & B3) | ((A3 ^ B3) & C2).
    check_final_carry: assert property (
        @(posedge CLK) disable iff (1'b0)
            Co == (
                (A[3] & B[3]) |
                ((A[3] ^ B[3]) & (
                    (A[2] & B[2]) |
                    ((A[2] ^ B[2]) & (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
                ))
            )
    );

// Adding zero B with zero carry-in passes A through, no carry-out.
    check_pass_through_A: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

// Adding zero A with zero carry-in passes B through, no carry-out.
    check_pass_through_B: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

// All zeros on inputs yield zero sum and zero carry.
    check_all_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (B == 4'b0000) && (Ci == 1'b0)) |-> ((S == 4'b0000) && (Co == 1'b0))
    );

// A + ~A + 1 = 16 => zero sum and carry-out set.
    check_complement_plus_one: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == ~A) && (Ci == 1'b1)) |-> ((S == 4'b0000) && (Co == 1'b1))
    );

// No clock/reset in DUT; combinational; sample on edges of A/B/out.

    // Core relation: out equals (|A) & ~(|B) on A[0] edges.
    check_func_equiv_on_A0: assert property (
        @(posedge A[0]) out == ((|A) & ~(|B))
    );

// If A is zero, out must be 0.
    check_out_zero_when_A_zero_on_A1: assert property (
        @(posedge A[1]) (A == 4'd0) |-> (out == 1'b0)
    );

// If B is nonzero, out must be 0.
    check_out_zero_when_B_nonzero_on_B0: assert property (
        @(posedge B[0]) (B != 4'd0) |-> (out == 1'b0)
    );

// If A is nonzero and B is zero, out must be 1.
    check_out_one_when_Ane0_Beq0_on_A2: assert property (
        @(posedge A[2]) ((A != 4'd0) && (B == 4'd0)) |-> (out == 1'b1)
    );

// If out is 1, A must be nonzero and B must be zero.
    check_out_one_only_if_Ane0_Beq0_on_A3: assert property (
        @(posedge A[3]) (out == 1'b1) |-> ((A != 4'd0) && (B == 4'd0))
    );

// If both A and B are zero, out must be 0.
    check_out_zero_when_both_zero_on_B1: assert property (
        @(posedge B[1]) ((A == 4'd0) && (B == 4'd0)) |-> (out == 1'b0)
    );

// If both A and B are nonzero, out must be 0.
    check_out_zero_when_both_nonzero_on_B2: assert property (
        @(posedge B[2]) ((A != 4'd0) && (B != 4'd0)) |-> (out == 1'b0)
    );

// If out is 0, then either A is zero or B is nonzero.
    check_out_zero_implies_Azero_or_Bnonzero_on_B3: assert property (
        @(posedge B[3]) (out == 1'b0) |-> ((A == 4'd0) || (B != 4'd0))
    );

// When A is nonzero, out equals ~(|B).
    check_when_A_nonzero_out_eq_not_reduceB_on_A0: assert property (
        @(posedge A[0]) (A != 4'd0) |-> (out == ~(|B))
    );

// Out equals in0 when sel==00.
    check_mux_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// Out equals in1 when sel==01.
    check_mux_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// Out equals in2 when sel==10.
    check_mux_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// Out equals in3 when sel==11.
    check_mux_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// OR covers all 1s present in A.
  check_or_covers_A: assert property (
    @(posedge CLK) disable iff (!RESETn) ((~or_res & A) == '0)
  );

// If a > b, drive result=a and select=00.
    check_a_gt_b_drives_a_and_sel00: assert property (
        @(posedge CLK) (a > b) |-> (comparison_result == a) && (input_selected == 2'b00)
    );

// If b > a, drive result=b and select=01.
    check_b_gt_a_drives_b_and_sel01: assert property (
        @(posedge CLK) (b > a) |-> (comparison_result == b) && (input_selected == 2'b01)
    );

// If a == b, drive result=a and pass through select.
    check_equal_drives_a_and_sel_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (comparison_result == a) && (input_selected == select)
    );

// Result is always either a or b.
    check_result_is_either_a_or_b: assert property (
        @(posedge CLK) (comparison_result == a) || (comparison_result == b)
    );

// MSB of input_selected is 1 only when a == b (values 2 or 3 only on equality).
    check_sel_msb_one_only_when_equal: assert property (
        @(posedge CLK) (input_selected[1] == 1'b1) |-> (a == b)
    );

// When a != b, MSB of input_selected must be 0 (only 00 or 01 allowed).
    check_not_equal_forces_sel_msb_zero: assert property (
        @(posedge CLK) (a != b) |-> (input_selected[1] == 1'b0)
    );

// If result==a, then a >= b.
    check_result_a_implies_a_ge_b: assert property (
        @(posedge CLK) (comparison_result == a) |-> (a >= b)
    );

// Analysis: no clock/reset in RTL; purely combinational always @(*).
    // Behavior: xor_out = XOR of data_in[7:0]; parity = xor_out when sel_b1==0, else ~xor_out.

    // When sel_b1==0, parity equals XOR of data_in bits.
    check_parity_sel0: assert property (
        @(posedge CLK) (!sel_b1) |-> (parity == ^data_in)
    );

// When sel_b1==1, parity equals inverted XOR of data_in bits.
    check_parity_sel1: assert property (
        @(posedge CLK) (sel_b1) |-> (parity == ~(^data_in))
    );

// Parity matches the Boolean equation parity == (^data_in) ^ sel_b1.
    check_parity_equation: assert property (
        @(posedge CLK) 1'b1 |-> (parity == ((^data_in) ^ sel_b1))
    );

// If XOR of data_in is 0, parity equals sel_b1.
    check_xor_zero_parity_equals_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b0) |-> (parity == sel_b1)
    );

// If XOR of data_in is 1, parity equals inverse of sel_b1.
    check_xor_one_parity_equals_not_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b1) |-> (parity == ~sel_b1)
    );

// When not in scan, reset high clears q to zero on next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (q == {SIZE{1'b0}})
    );

// When not in scan, reset high drives so to zero on next cycle (since so=q).
    check_reset_clears_so: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (so == {SIZE{1'b0}})
    );

// RTL has no reset; assertions are not reset-disabled.
    // Combinational behavior: if (A>B) result=A<<shift_amount; else if (A<B) result=B>>shift_amount; else result=A.

    // If A > B, result equals A shifted left by shift_amount.
    check_left_shift_when_A_gt_B: assert property (
        @(posedge CLK) (A > B) |-> (result == (A << shift_amount))
    );

// If A < B, result equals B shifted right by shift_amount.
    check_right_shift_when_A_lt_B: assert property (
        @(posedge CLK) (A < B) |-> (result == (B >> shift_amount))
    );

// If A == B, result equals A.
    check_passthrough_when_A_eq_B: assert property (
        @(posedge CLK) (A == B) |-> (result == A)
    );

// If shift_amount is 0 and A > B, result equals A (no left shift effect).
    check_no_shift_behavior_left: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd0)) |-> (result == A)
    );

// If shift_amount is 0 and A < B, result equals B (no right shift effect).
    check_no_shift_behavior_right: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd0)) |-> (result == B)
    );

// For left shift by >=1 (A > B), LSB of result is 0.
    check_lsb_zero_after_left_shift: assert property (
        @(posedge CLK) ((A > B) && (shift_amount != 4'd0)) |-> (result[0] == 1'b0)
    );

// For right shift by >=1 (A < B), MSB of result is 0.
    check_msb_zero_after_right_shift: assert property (
        @(posedge CLK) ((A < B) && (shift_amount != 4'd0)) |-> (result[15] == 1'b0)
    );

// Left shift by 15 when A > B produces {A[0], 15'b0}.
    check_left_shift_by_15: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd15)) |-> (result == {A[0], 15'b0})
    );

// Right shift by 15 when A < B produces {15'b0, B[15]}.
    check_right_shift_by_15: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd15)) |-> (result == {15'b0, B[15]})
    );

// For right shift case, result is less than or equal to B (unsigned).
    check_right_shift_monotonic: assert property (
        @(posedge CLK) (A < B) |-> (result <= B)
    );

// Final 5-bit result equals A+B+CI.
    check_full_sum: assert property (
        @(posedge clk) disable iff (1'b0) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

// S[0] equals A[0]^B[0]^CI.
    check_sum0_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ CI)
    );

// S[1] equals A[1]^B[1]^C[0].
    check_sum1_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[1] == (A[1] ^ B[1] ^ C[0])
    );

// S[2] equals A[2]^B[2]^C[1].
    check_sum2_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[2] == (A[2] ^ B[2] ^ C[1])
    );

// S[3] equals A[3]^B[3]^C[2].
    check_sum3_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[3] == (A[3] ^ B[3] ^ C[2])
    );

// C[0] equals majority(A[0],B[0],CI).
    check_carry0_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[0] == ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI))
    );

// C[1] equals majority(A[1],B[1],C[0]).
    check_carry1_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[1] == ((A[1] & B[1]) | (B[1] & C[0]) | (A[1] & C[0]))
    );

// C[2] equals majority(A[2],B[2],C[1]).
    check_carry2_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[2] == ((A[2] & B[2]) | (B[2] & C[1]) | (A[2] & C[1]))
    );

// CO equals majority(A[3],B[3],C[2]).
    check_carry3_majority: assert property (
        @(posedge clk) disable iff (1'b0) CO == ((A[3] & B[3]) | (B[3] & C[2]) | (A[3] & C[2]))
    );

// No clock/reset in RTL; purely combinational. Use posedge of A1[0] as sampling event.

    // Y must equal one of the eight inputs.
    check_Y_is_from_inputs: assert property (
        @(posedge A1[0]) (Y == A1) || (Y == A2) || (Y == B1) || (Y == B2) || (Y == C1) || (Y == C2) || (Y == D1) || (Y == D2)
    );

// No input can be strictly greater than Y (Y is an upper bound).
    check_Y_is_upper_bound: assert property (
        @(posedge A1[0]) (Y >= A1) && (Y >= A2) && (Y >= B1) && (Y >= B2) && (Y >= C1) && (Y >= C2) && (Y >= D1) && (Y >= D2)
    );

// If A1 is strictly greater than all others, Y equals A1.
    check_strict_max_A1: assert property (
        @(posedge A1[0]) (A1 > A2) && (A1 > B1) && (A1 > B2) && (A1 > C1) && (A1 > C2) && (A1 > D1) && (A1 > D2) |-> (Y == A1)
    );

// If A2 is strictly greater than all others, Y equals A2.
    check_strict_max_A2: assert property (
        @(posedge A1[0]) (A2 > A1) && (A2 > B1) && (A2 > B2) && (A2 > C1) && (A2 > C2) && (A2 > D1) && (A2 > D2) |-> (Y == A2)
    );

// If B1 is strictly greater than all others, Y equals B1.
    check_strict_max_B1: assert property (
        @(posedge A1[0]) (B1 > A1) && (B1 > A2) && (B1 > B2) && (B1 > C1) && (B1 > C2) && (B1 > D1) && (B1 > D2) |-> (Y == B1)
    );

// If B2 is strictly greater than all others, Y equals B2.
    check_strict_max_B2: assert property (
        @(posedge A1[0]) (B2 > A1) && (B2 > A2) && (B2 > B1) && (B2 > C1) && (B2 > C2) && (B2 > D1) && (B2 > D2) |-> (Y == B2)
    );

// If C1 is strictly greater than all others, Y equals C1.
    check_strict_max_C1: assert property (
        @(posedge A1[0]) (C1 > A1) && (C1 > A2) && (C1 > B1) && (C1 > B2) && (C1 > C2) && (C1 > D1) && (C1 > D2) |-> (Y == C1)
    );

// If C2 is strictly greater than all others, Y equals C2.
    check_strict_max_C2: assert property (
        @(posedge A1[0]) (C2 > A1) && (C2 > A2) && (C2 > B1) && (C2 > B2) && (C2 > C1) && (C2 > D1) && (C2 > D2) |-> (Y == C2)
    );

// If D1 is strictly greater than all others, Y equals D1.
    check_strict_max_D1: assert property (
        @(posedge A1[0]) (D1 > A1) && (D1 > A2) && (D1 > B1) && (D1 > B2) && (D1 > C1) && (D1 > C2) && (D1 > D2) |-> (Y == D1)
    );

// If D2 is strictly greater than all others, Y equals D2.
    check_strict_max_D2: assert property (
        @(posedge A1[0]) (D2 > A1) && (D2 > A2) && (D2 > B1) && (D2 > B2) && (D2 > C1) && (D2 > C2) && (D2 > D1) |-> (Y == D2)
    );

// out implements exact ternary function of inputs
    check_function_exact: assert property (
        @(posedge clk) out == ((sel == 1'b0) ? a : b)
    );

// When sel==0, out equals a in the same cycle
    check_sel0_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel==1, out equals b in the same cycle
    check_sel1_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

///// Functional checks (sampled on a data edge since no clock/reset in RTL) /////
    // out_hi is always zero because hi_byte truncates to 8'b0 and a bit-select is zero-extended.
    check_out_hi_const_zero: assert property (
        @(posedge in[0]) (out_hi == 8'h00)
    );

// out_lo[7:1] must always be zero due to zero-extension of a single selected bit.
    check_out_lo_zero_extended: assert property (
        @(posedge in[0]) (out_lo[7:1] == 7'b0)
    );

// out_lo[0] equals the selected bit from in[3:0] indexed by in[13:12].
    check_out_lo_dynamic_index: assert property (
        @(posedge in[0]) (out_lo[0] == in[in[13:12]])
    );

// out_lo can only be 8'h00 or 8'h01 (zero-extended single bit).
    check_out_lo_binary_range: assert property (
        @(posedge in[0]) (out_lo inside {8'h00, 8'h01})
    );

// Equivalent Boolean form of selection: out_lo equals OR of gated bits, zero-extended.
    check_out_lo_boolean_form: assert property (
        @(posedge in[0])
        out_lo == {7'b0, (((in[13:12]==2'd0) && in[0]) ||
                          ((in[13:12]==2'd1) && in[1]) ||
                          ((in[13:12]==2'd2) && in[2]) ||
                          ((in[13:12]==2'd3) && in[3]))}
    );

// X equals the bitwise AND of all inputs.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) (X === (A_N & B_N & C & D))
    );

// If A_N is 0 then X must be 0.
    check_zero_dominance_A_N: assert property (
        @(posedge clk) disable iff (1'b0) (A_N == 1'b0) |-> (X == 1'b0)
    );

// If B_N is 0 then X must be 0.
    check_zero_dominance_B_N: assert property (
        @(posedge clk) disable iff (1'b0) (B_N == 1'b0) |-> (X == 1'b0)
    );

// If C is 0 then X must be 0.
    check_zero_dominance_C: assert property (
        @(posedge clk) disable iff (1'b0) (C == 1'b0) |-> (X == 1'b0)
    );

// If D is 0 then X must be 0.
    check_zero_dominance_D: assert property (
        @(posedge clk) disable iff (1'b0) (D == 1'b0) |-> (X == 1'b0)
    );

// If all inputs are 1 then X must be 1.
    check_all_ones_implies_X_one: assert property (
        @(posedge clk) disable iff (1'b0) (A_N && B_N && C && D) |-> (X == 1'b1)
    );

// If X is 1 then all inputs must be 1.
    check_X_one_implies_all_ones: assert property (
        @(posedge clk) disable iff (1'b0) (X == 1'b1) |-> (A_N && B_N && C && D)
    );

// No clock/reset in RTL; combinational logic. Sample assertions on posedge of iEnable.

    // When inside box with enable/mask high, drive sprite color.
    sprite_when_inside_and_enabled: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount <= (SizeX + iPosX)) && (iColumnCount >= iPosX) &&
        (iRowCount    <= (SizeY + iPosY)) && (iRowCount    >= iPosY)
        |-> (oRGB == iColorSprite)
    );

// Left edge inclusive: at left boundary with other coords in range and enables high, sprite color.
    sprite_on_left_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == iPosX) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount <= (SizeX + iPosX))
        |-> (oRGB == iColorSprite)
    );

// Right edge inclusive: at right boundary with other coords in range and enables high, sprite color.
    sprite_on_right_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == (SizeX + iPosX)) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount >= iPosX)
        |-> (oRGB == iColorSprite)
    );

// Top edge inclusive: at top boundary with other coords in range and enables high, sprite color.
    sprite_on_top_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == iPosY) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   <= (SizeY + iPosY))
        |-> (oRGB == iColorSprite)
    );

// Bottom edge inclusive: at bottom boundary with other coords in range and enables high, sprite color.
    sprite_on_bottom_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == (SizeY + iPosY)) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   >= iPosY)
        |-> (oRGB == iColorSprite)
    );

// Output equals in0 when sel1=0 and sel0=0.
    check_out_sel00: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel1 && !sel0) |-> (out == in0)
    );

// Output equals in1 when sel1=0 and sel0=1.
    check_out_sel01: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel1 && sel0) |-> (out == in1)
    );

// Output equals in2 when sel1=1 and sel0=0.
    check_out_sel10: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel1 && !sel0) |-> (out == in2)
    );

// Output equals in3 when sel1=1 and sel0=1.
    check_out_sel11: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel1 && sel0) |-> (out == in3)
    );

// Output matches the RTL ternary expression for all select combinations.
    check_out_expr_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            out == ( (sel1 & sel0) ? in3
                  : (sel1 & ~sel0) ? in2
                  : (~sel1 & sel0) ? in1
                  : in0 )
    );

// Output matches the RTL's piecewise function for all input combinations.
    check_functional_spec: assert property (
        @(posedge clk)
        fifo_wrptr_inc == ( (ge3_free && (input_tm_cnt == 2'd3)) ? 4'd3 :
                            (ge2_free && (input_tm_cnt >= 2'd2)) ? 4'd2 :
                            (input_tm_cnt >= 2'd1)               ? 4'd1 :
                                                                     4'd0 )
    );

// Output is always in the set {0,1,2,3}.
    check_output_range: assert property (
        @(posedge clk) fifo_wrptr_inc inside {4'd0, 4'd1, 4'd2, 4'd3}
    );

// When input_tm_cnt is 0, increment is 0.
    check_tm_cnt0_zero: assert property (
        @(posedge clk) (input_tm_cnt == 2'd0) |-> (fifo_wrptr_inc == 4'd0)
    );

// When input_tm_cnt is 1, increment is 1 (independent of ge2_free/ge3_free).
    check_tm_cnt1_one: assert property (
        @(posedge clk) (input_tm_cnt == 2'd1) |-> (fifo_wrptr_inc == 4'd1)
    );

// When input_tm_cnt is 2 and ge2_free is true, increment is 2.
    check_tm_cnt2_ge2_true: assert property (
        @(posedge clk) (input_tm_cnt == 2'd2) && ge2_free |-> (fifo_wrptr_inc == 4'd2)
    );

// When input_tm_cnt is 2 and ge2_free is false, increment is 1.
    check_tm_cnt2_ge2_false: assert property (
        @(posedge clk) (input_tm_cnt == 2'd2) && !ge2_free |-> (fifo_wrptr_inc == 4'd1)
    );

// When input_tm_cnt is 3 and ge3_free is true, increment is 3 (highest priority).
    check_tm_cnt3_ge3_true: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && ge3_free |-> (fifo_wrptr_inc == 4'd3)
    );

// When input_tm_cnt is 3, ge3_free is false, and ge2_free is true, increment is 2.
    check_tm_cnt3_ge2_only_yields_two: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && !ge3_free && ge2_free |-> (fifo_wrptr_inc == 4'd2)
    );

// When input_tm_cnt is 3 and both ge3_free and ge2_free are false, increment is 1.
    check_tm_cnt3_no_free_yields_one: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && !ge3_free && !ge2_free |-> (fifo_wrptr_inc == 4'd1)
    );

// Exactly one of gt/lt/eq must be HIGH for any a,b.
    outputs_onehot: assert property (
        @(posedge CLK) disable iff (1'b0) $onehot({gt, lt, eq})
    );

// When a > b, outputs must be gt=1, lt=0, eq=0.
    a_gt_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a > b) |-> (gt && !lt && !eq)
    );

// When a < b, outputs must be gt=0, lt=1, eq=0.
    a_lt_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a < b) |-> (!gt && lt && !eq)
    );

// When a == b, outputs must be gt=0, lt=0, eq=1.
    a_eq_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a == b) |-> (!gt && !lt && eq)
    );

// If gt is HIGH, then a > b.
    gt_means_a_gt_b: assert property (
        @(posedge CLK) disable iff (1'b0) gt |-> (a > b)
    );

// If lt is HIGH, then a < b.
    lt_means_a_lt_b: assert property (
        @(posedge CLK) disable iff (1'b0) lt |-> (a < b)
    );

// If eq is HIGH, then a == b.
    eq_means_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) eq |-> (a == b)
    );

// When a >= b, lt must be LOW.
    no_lt_when_a_ge_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a >= b) |-> (!lt)
    );

// When a <= b, gt must be LOW.
    no_gt_when_a_le_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a <= b) |-> (!gt)
    );

// When a != b, eq must be LOW.
    no_eq_when_a_ne_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a != b) |-> (!eq)
    );

// While reset is LOW, result must be zero.
  reset_level_forces_zero: assert property (
    @(posedge clk) (reset == 1'b0) |-> (result == 4'b0000)
  );

// On the first clock after reset deasserts (LOW->HIGH), result is still zero.
  first_clk_after_reset_release_zero: assert property (
    @(posedge clk) (reset == 1'b1) && ($past(reset) == 1'b0) |-> (result == 4'b0000)
  );

// With op=0, next result is (A+B) LSBs from the previous cycle.
  update_sum_when_op0: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b0)
      |-> (result == (($past(A) + $past(B)) & 4'hF))
  );

// With op=1, next result is (A-B) LSBs from the previous cycle.
  update_diff_when_op1: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b1)
      |-> (result == (($past(A) - $past(B)) & 4'hF))
  );

// C never encodes 2'b11.
    check_c_never_11: assert property (
        @(posedge CLK) C != 2'b11
    );

// If A == B then C == 2'b00.
    check_eq_implies_c00: assert property (
        @(posedge CLK) (A == B) |-> (C == 2'b00)
    );

// If C == 2'b00 then A == B.
    check_c00_implies_eq: assert property (
        @(posedge CLK) (C == 2'b00) |-> (A == B)
    );

// If A > B then C == 2'b01.
    check_gt_implies_c01: assert property (
        @(posedge CLK) (A > B) |-> (C == 2'b01)
    );

// If C == 2'b01 then A > B.
    check_c01_implies_gt: assert property (
        @(posedge CLK) (C == 2'b01) |-> (A > B)
    );

// If A < B then C == 2'b10.
    check_lt_implies_c10: assert property (
        @(posedge CLK) (A < B) |-> (C == 2'b10)
    );

// If C == 2'b10 then A < B.
    check_c10_implies_lt: assert property (
        @(posedge CLK) (C == 2'b10) |-> (A < B)
    );

// Reset drives count to 0 on the clock edge while reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// Clock: clk (posedge). No reset present in RTL.
  // Logic: mixed — result is combinational; overflow is registered each clk.

  ///// Result computation /////
  // When op==0, result equals a + b (combinational).
  result_add_correct: assert property (
    @(posedge clk) (op == 1'b0) |-> (result == (a + b))
  );

// When op==1, result equals a - b (combinational).
  result_sub_correct: assert property (
    @(posedge clk) (op == 1'b1) |-> (result == (a - b))
  );

///// Overflow computation (registered) /////
  // On the next cycle, overflow must be 1 when the RTL's overflow condition holds.
  overflow_set_when_condition: assert property (
    @(posedge clk)
      (
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b1)
  );

// On the next cycle, overflow must be 0 when the RTL's overflow condition does not hold.
  overflow_clear_when_not_condition: assert property (
    @(posedge clk)
      !(
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b0)
  );

// After the first cycle, overflow is always a known 0/1 (registered each clk).
  overflow_binary_after_first_cycle: assert property (
    @(posedge clk) $past(1'b1) |-> (overflow inside {1'b0, 1'b1})
  );

// If reset is 1 on this edge, out must be 0 on the next edge.
    check_reset_clears_out_next: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

// If not in reset for two consecutive cycles, out equals in1+in2 from the prior cycle.
    check_sum_update_two_cycle_nonreset: assert property (
        @(posedge CLK) disable iff (reset) (!reset ##1 !reset) |-> (out == $past(in1 + in2))
    );

// Mode 00 left-shifts input and zero-fills the LSB.
    check_mode_shift_left: assert property (
        @(posedge clk) (mode == 2'b00) |-> (out == {in[2:0], 1'b0})
    );

// Mode 01 right-shifts input and zero-fills the MSB.
    check_mode_shift_right: assert property (
        @(posedge clk) (mode == 2'b01) |-> (out == {1'b0, in[3:1]})
    );

// Mode 10 bitwise-inverts the input.
    check_mode_invert: assert property (
        @(posedge clk) (mode == 2'b10) |-> (out == ~in)
    );

// Mode 11 passes the input through unchanged.
    check_mode_passthrough: assert property (
        @(posedge clk) (mode == 2'b11) |-> (out == in)
    );

// X must equal the OR of A1/A2/A3 gated by B1.
    check_exact_boolean_function: assert property (
        @(posedge clk) X == ((A1 | A2 | A3) & B1)
    );

// When B1 is low, X must be low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// When all A inputs are low, X must be low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> !X
    );

// When B1 is high, X must match the OR of A1/A2/A3.
    check_b1_high_passes_or_result: assert property (
        @(posedge clk) B1 |-> (X == (A1 | A2 | A3))
    );

// A high X requires B1 to be high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// A high X requires at least one A input to be high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3)
    );

// A1 asserted with B1 high must drive X high.
    check_a1_path_to_x: assert property (
        @(posedge clk) (A1 & B1) |-> X
    );

// A2 asserted with B1 high must drive X high.
    check_a2_path_to_x: assert property (
        @(posedge clk) (A2 & B1) |-> X
    );

// A3 asserted with B1 high must drive X high.
    check_a3_path_to_x: assert property (
        @(posedge clk) (A3 & B1) |-> X
    );

// Reset drives the counter to zero on the following sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// A sampled reset leaves the registered output cleared on the next clock.
    check_reset_next_cycle_zero: assert property (
        @(posedge clk)
        reset |=> (sum == 32'h00000000)
    );

// X must equal the OR of the three logic inputs.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// X LOW means all three logic inputs are LOW.
    check_x_low_implies_all_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C)
    );

// All three logic inputs LOW must drive X LOW.
    check_all_inputs_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// A HIGH must drive X HIGH.
    check_a_high_drives_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B HIGH must drive X HIGH.
    check_b_high_drives_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C HIGH must drive X HIGH.
    check_c_high_drives_x_high: assert property (
        @(posedge clk) C |-> X
    );

// Active-low reset clears d_out_1.
    check_reset_clears_dout1: assert property (
        @(posedge clk) !reset |-> (d_out_1 == 1'b0)
    );

// Active-low reset clears d_out_2.
    check_reset_clears_dout2: assert property (
        @(posedge clk) !reset |-> (d_out_2 == 1'b0)
    );

// The first clock after reset release still sees cleared outputs.
    check_outputs_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!reset) $past(!reset) |-> ((d_out_1 == 1'b0) && (d_out_2 == 1'b0))
    );

// d_out_1 captures d_in on the next active clock.
    check_dout1_captures_din: assert property (
        @(posedge clk) disable iff (!reset) reset |=> (d_out_1 == $past(d_in))
    );

// d_out_2 captures the previous d_out_1 ^ d_in on the next active clock.
    check_dout2_captures_xor: assert property (
        @(posedge clk) disable iff (!reset) reset |=> (d_out_2 == ($past(d_out_1) ^ $past(d_in)))
    );

// Combined outputs match the 5-bit addition result.
    check_full_sum_match: assert property (
        @(posedge clk) {cout, s} == expected_sum(a, b, cin)
    );

// s matches the lower 4 bits of the addition result.
    check_sum_low_bits: assert property (
        @(posedge clk) s == expected_s(a, b, cin)
    );

// cout matches the carry bit of the addition result.
    check_carry_out: assert property (
        @(posedge clk) cout == expected_cout(a, b, cin)
    );

// The sum LSB is the xor of the input LSBs and carry-in.
    check_lsb_xor: assert property (
        @(posedge clk) s[0] == (a[0] ^ b[0] ^ cin)
    );

// Zero inputs produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, s} == 5'h00)
    );

// 4'hF + 4'h1 wraps the sum and raises carry-out.
    check_wrap_carry_case: assert property (
        @(posedge clk) (a == 4'hF && b == 4'h1 && cin == 1'b0) |-> ({cout, s} == 5'h10)
    );

// 4'hF + 4'hF + 1 produces the maximum 5-bit result.
    check_max_case: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, s} == 5'h1F)
    );

// Carry matches the upper bit of sum.
    check_carry_matches_sum_msb: assert property (
        @(posedge clk) carry == sum[8]
    );

// Zero inputs produce zero outputs.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 8'h00 && B == 8'h00) |-> (sum == 9'h000 && carry == 1'b0)
    );

// Z must match the implemented gate-level RTL expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) Z == ((~((~(A & B)) & EN)) & (A & B))
    );

// When both inputs are high, Z must be high regardless of EN.
    check_ab_high_drive_z_high: assert property (
        @(posedge clk) (A & B) |-> Z
    );

// Z can only be high when both inputs are high.
    check_z_high_requires_ab_high: assert property (
        @(posedge clk) Z |-> (A & B)
    );

// If either input is low, Z must be low regardless of EN.
    check_any_low_drives_z_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (!Z)
    );

// Sum is the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry-out matches the implemented generate/propagate equation.
    check_carry_function: assert property (
        @(posedge clk) Co == ((A & B) | ((A ^ B) & Ci))
    );

// With Ci low, the adder behaves as a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !Ci |-> ((S == (A ^ B)) && (Co == (A & B)))
    );

// With Ci high, sum inverts A^B and carry is A or B.
    check_carry_in_mode: assert property (
        @(posedge clk) Ci |-> ((S == ~(A ^ B)) && (Co == (A | B)))
    );

// When A and B match, sum follows Ci and carry follows A.
    check_equal_inputs_behavior: assert property (
        @(posedge clk) !(A ^ B) |-> ((S == Ci) && (Co == A))
    );

// When A and B differ, sum is the inverse of Ci and carry follows Ci.
    check_unequal_inputs_behavior: assert property (
        @(posedge clk) (A ^ B) |-> ((S == ~Ci) && (Co == Ci))
    );

// Reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// Reset takes priority over enable when both are high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'h0)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// If clear stays low across clocks, the counter must be zero.
    check_clear_holds_zero: assert property (
        @(posedge clk)
        (!clear ##1 !clear) |-> (count_out == 4'b0000)
    );

// Load captures data_in on the next clock unless async clear forces zero.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!clear)
        load |=> ((count_out == $past(data_in)) || (count_out == 4'b0000))
    );

// Without load, up_down high increments on the next clock unless async clear forces zero.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && up_down) |=> ((count_out == ($past(count_out) + 4'b0001)) || (count_out == 4'b0000))
    );

// Without load, up_down low decrements on the next clock unless async clear forces zero.
    check_decrement_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && !up_down) |=> ((count_out == ($past(count_out) - 4'b0001)) || (count_out == 4'b0000))
    );

// Reset low at a sampled clock forces Q low by the next clock.
    check_reset_clears_q_next_clock: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

// With reset high, a sampled 0 on D is captured as 0 on the next clock.
    check_capture_zero_on_clock: assert property (
        @(posedge C) (R && !D) |=> (Q == 1'b0)
    );

// A high Q must come from a prior clock with reset high and D high.
    check_q_high_requires_prior_high_input: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q |-> $past(R && D))
    );

// Reset drives the registered output to 000 on the next cycle.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 3'b000)
    );

// 000 rotates back to 000 in normal operation.
    check_state_000_to_000: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b000) |=> (out == 3'b000)
    );

// 001 rotates to 010 in normal operation.
    check_state_001_to_010: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b001) |=> (out == 3'b010)
    );

// 010 rotates to 100 in normal operation.
    check_state_010_to_100: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b010) |=> (out == 3'b100)
    );

// 011 rotates to 110 in normal operation.
    check_state_011_to_110: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b011) |=> (out == 3'b110)
    );

// 100 rotates to 001 in normal operation.
    check_state_100_to_001: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b100) |=> (out == 3'b001)
    );

// 101 rotates to 011 in normal operation.
    check_state_101_to_011: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b101) |=> (out == 3'b011)
    );

// 110 rotates to 101 in normal operation.
    check_state_110_to_101: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b110) |=> (out == 3'b101)
    );

// 111 rotates back to 111 in normal operation.
    check_state_111_to_111: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b111) |=> (out == 3'b111)
    );

// Data-path registers capture the EX-stage values on each clock.
    check_data_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_aluresult == $past(ex_aluresult) &&
                  me_d2        == $past(ex_d2) &&
                  me_td        == $past(ex_td))
    );

// Control registers capture the EX-stage control bits on each clock.
    check_control_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_WREG == $past(ex_WREG) &&
                  me_WMEM == $past(ex_WMEM) &&
                  me_LW   == $past(ex_LW))
    );

// The instruction register captures the EX-stage instruction on each clock.
    check_instr_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_instr == $past(ex_instr))
    );

// equal matches bitwise equality of A and B.
    check_equal_flag: assert property (
        @(posedge clk) equal == (A == B)
    );

// signed_larger matches the signed A > B comparison.
    check_signed_larger_flag: assert property (
        @(posedge clk) signed_larger == ($signed(A) > $signed(B))
    );

// signed_smaller matches the signed A < B comparison.
    check_signed_smaller_flag: assert property (
        @(posedge clk) signed_smaller == ($signed(A) < $signed(B))
    );

// signed_larger and signed_smaller cannot both be high.
    check_compare_flags_mutex: assert property (
        @(posedge clk) !(signed_larger && signed_smaller)
    );

// larger_num selects A when signed_larger is true, else B.
    check_larger_num_select: assert property (
        @(posedge clk) larger_num == (signed_larger ? A : B)
    );

// smaller_num selects A when signed_smaller is true, else B.
    check_smaller_num_select: assert property (
        @(posedge clk) smaller_num == (signed_smaller ? A : B)
    );

// X implements A OR B OR the NAND of C_N and D_N.
    check_function_equation: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A being high forces X high.
    check_a_forces_high: assert property (
        @(posedge clk) A |-> X
    );

// B being high forces X high.
    check_b_forces_high: assert property (
        @(posedge clk) B |-> X
    );

// C_N being low forces X high through the NAND term.
    check_c_n_low_forces_high: assert property (
        @(posedge clk) !C_N |-> X
    );

// D_N being low forces X high through the NAND term.
    check_d_n_low_forces_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// X is low only in the all-inactive input case.
    check_all_inactive_drives_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

// Synchronous reset drives ENCLK low on the next clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RST |=> (ENCLK == 1'b0)
    );

// Reset has priority over TE when both are asserted.
    check_reset_overrides_te: assert property (
        @(posedge CLK) (RST && TE) |=> (ENCLK == 1'b0)
    );

// When TE is high, EN=1 is captured into ENCLK.
    check_te_captures_one: assert property (
        @(posedge CLK) disable iff (RST) (TE && EN) |=> (ENCLK == 1'b1)
    );

// When TE is high, EN=0 is captured into ENCLK.
    check_te_captures_zero: assert property (
        @(posedge CLK) disable iff (RST) (TE && !EN) |=> (ENCLK == 1'b0)
    );

// When TE is low, a high ENCLK value is held.
    check_hold_high_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) (!TE && ENCLK) |=> (ENCLK == 1'b1)
    );

// When TE is low, a low ENCLK value is held.
    check_hold_low_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) (!TE && !ENCLK) |=> (ENCLK == 1'b0)
    );

// Sum registers the previous cycle's 4-bit addition of A, B, and Cin.
    check_sum_matches_previous_add: assert property (
        @(posedge Clock) 1'b1 |=> (Sum == ($past(A) + $past(B) + $past(Cin)))
    );

// DUT is combinational; clk is an external sampling clock and there is no reset.

    // Y matches the implemented AOI21 boolean function.
    check_boolean_function: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// A high B1 input forces Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> ~Y
    );

// High A1 and A2 force the AND term high and drive Y low.
    check_and_term_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> ~Y
    );

// When B1 is low, Y reduces to the inverse of A1&A2.
    check_b1_low_reduces_to_nand: assert property (
        @(posedge clk) (~B1) |-> (Y == ~(A1 & A2))
    );

// A high output requires B1 to be low.
    check_y_high_requires_b1_low: assert property (
        @(posedge clk) Y |-> ~B1
    );

// A high output requires the A1/A2 AND term to be low.
    check_y_high_requires_and_term_low: assert property (
        @(posedge clk) Y |-> (~A1 | ~A2)
    );

// A low output must be caused by B1 or the A1/A2 AND term being high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) (~Y) |-> (B1 | (A1 & A2))
    );

// Disabled display outputs a blank pattern.
    check_blank_when_disabled: assert property (
        @(posedge clk) !enable |-> out == (INVERT ? ~7'b0000000 : 7'b0000000)
    );

// Enabled display outputs the selected hex digit pattern.
    check_enabled_hex_decode: assert property (
        @(posedge clk) enable |-> out == (INVERT ? ~hex_enc(in) : hex_enc(in))
    );

// out_mux selects data0 when sel is 0.
    check_out_mux_sel0: assert property (
        @(posedge clk) (sel == 3'd0) |-> (out_mux == data0)
    );

// out_mux selects data1 when sel is 1.
    check_out_mux_sel1: assert property (
        @(posedge clk) (sel == 3'd1) |-> (out_mux == data1)
    );

// out_mux selects data2 when sel is 2.
    check_out_mux_sel2: assert property (
        @(posedge clk) (sel == 3'd2) |-> (out_mux == data2)
    );

// out_mux selects data3 when sel is 3.
    check_out_mux_sel3: assert property (
        @(posedge clk) (sel == 3'd3) |-> (out_mux == data3)
    );

// out_mux selects data4 when sel is 4.
    check_out_mux_sel4: assert property (
        @(posedge clk) (sel == 3'd4) |-> (out_mux == data4)
    );

// out_mux selects data5 when sel is 5.
    check_out_mux_sel5: assert property (
        @(posedge clk) (sel == 3'd5) |-> (out_mux == data5)
    );

// out_mux is zero when sel is outside 0 through 5.
    check_out_mux_default_zero: assert property (
        @(posedge clk) ((sel == 3'd6) || (sel == 3'd7)) |-> (out_mux == 4'b0000)
    );

// out_3bit mirrors sel.
    check_out_3bit_matches_sel: assert property (
        @(posedge clk) out_3bit == sel
    );

// o2 mirrors sel[2].
    check_o2_matches_sel_bit2: assert property (
        @(posedge clk) o2 == sel[2]
    );

// o1 mirrors sel[1].
    check_o1_matches_sel_bit1: assert property (
        @(posedge clk) o1 == sel[1]
    );

// o0 mirrors sel[0].
    check_o0_matches_sel_bit0: assert property (
        @(posedge clk) o0 == sel[0]
    );

// Combinational DUT sampled on an external clock.
    // No reset is present in the RTL.

    // ctrl=00 selects D0 onto S.
    check_select_d0: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (S == D0)
    );

// ctrl=01 selects D1 onto S.
    check_select_d1: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (S == D1)
    );

// ctrl=10 selects D2 onto S.
    check_select_d2: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (S == D2)
    );

// ctrl=11 selects D3 onto S.
    check_select_d3: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (S == D3)
    );

// Load copies the input into the register.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> out == $past(in)
    );

// Without load, the register rotates left with wraparound.
    check_shift_rotates_register: assert property (
        @(posedge clk) !load |=> out == {$past(out[2:0]), $past(out[3])}
    );

// On a shift cycle, the previous MSB wraps into bit 0.
    check_shift_wraps_msb_to_lsb: assert property (
        @(posedge clk) !load |=> out[0] == $past(out[3])
    );

// On a shift cycle, bits [3:1] come from the previous [2:0].
    check_shift_moves_lower_bits_up: assert property (
        @(posedge clk) !load |=> out[3:1] == $past(out[2:0])
    );

// The serial output is always the previous cycle's MSB.
    check_ser_out_tracks_previous_msb: assert property (
        @(posedge clk) 1'b1 |=> ser_out == $past(out[3])
    );

// On a shift cycle, serial output matches the wrapped bit on out[0].
    check_shift_ser_out_matches_lsb: assert property (
        @(posedge clk) !load |=> ser_out == out[0]
    );

// SEL=00 routes A to Y.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (Y == A)
    );

// SEL=01 routes B to Y.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (Y == B)
    );

// SEL=10 routes C to Y.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (Y == C)
    );

// SEL=11 routes D to Y.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (Y == D)
    );

// Q captures SE on an enabled clock edge.
    check_capture_when_enabled: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Q holds its previous value when EN is low.
    check_hold_when_disabled: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// Enabling with different data causes Q to change.
    check_enabled_new_data_updates_q: assert property (
        @(posedge CK) EN && (SE != Q) |=> $changed(Q)
    );

// Enabling with the same data leaves Q unchanged.
    check_enabled_same_data_keeps_q: assert property (
        @(posedge CK) EN && (SE == Q) |=> !$changed(Q)
    );

// No DUT clock/reset; this checker samples the combinational interface on clk.

    // out_valid is exactly the enable signal.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// out is the AND of both inputs gated by enable.
    check_out_matches_function: assert property (
        @(posedge clk) out == (in1 & in2 & en)
    );

// When enable is low, out must be low.
    check_disable_forces_out_low: assert property (
        @(posedge clk) !en |-> !out
    );

// A high out requires both inputs high and enable asserted.
    check_out_high_requires_all_inputs: assert property (
        @(posedge clk) out |-> (in1 && in2 && en && out_valid)
    );

// When enabled and both inputs are high, out must be high.
    check_enabled_high_inputs_drive_out: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

// O matches the RTL mux equation.
    check_o_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// CO matches the RTL carry equation.
    check_co_equation: assert property (
        @(posedge clk) CO == ((CI & S) | (DI & (CI | S)))
    );

// When S is high, O selects DI.
    check_o_selects_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

// When S is low, O selects CI.
    check_o_selects_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

// When S is high, CO reduces to CI OR DI.
    check_co_reduces_to_or_when_s_high: assert property (
        @(posedge clk) S |-> (CO == (CI | DI))
    );

// When S is low, CO reduces to CI AND DI.
    check_co_reduces_to_and_when_s_low: assert property (
        @(posedge clk) !S |-> (CO == (CI & DI))
    );

// Equal data inputs force both outputs to that shared value.
    check_equal_inputs_drive_equal_outputs: assert property (
        @(posedge clk) (CI == DI) |-> ((O == CI) && (CO == CI))
    );

// Any reset cycle leaves ENCLK low by the next observed clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |=> (ENCLK == 1'b0)
    );

// With EN low, the RTL takes the else branch and drives ENCLK low.
    check_en_low_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (!EN) |=> (ENCLK == 1'b0)
    );

// With EN and TE high, the TE branch drives ENCLK low.
    check_te_high_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

// OUT matches A+B in add mode.
    check_out_matches_sum_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (OUT == (A + B))
    );

// COUT matches OUT[3] in add mode.
    check_cout_matches_out_msb_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (COUT == OUT[3])
    );

// OUT matches ~B+1 in subtract mode.
    check_out_matches_twos_complement_b_in_sub_mode: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (OUT == ((~B) + 4'd1))
    );

// Output is never multi-hot.
    check_out_onehot0: assert property (
        @(posedge clk) disable iff (1'b0) $onehot0(out)
    );

// Input 000 selects bit 0.
    check_decode_000: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 selects bit 1.
    check_decode_001: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 selects bit 2.
    check_decode_010: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 selects bit 3.
    check_decode_011: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 selects bit 4.
    check_decode_100: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 selects bit 5.
    check_decode_101: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 selects bit 6.
    check_decode_110: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 selects bit 7.
    check_decode_111: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Unknown input values drive the default zero output.
    check_decode_unknown_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) $isunknown(in) |-> (out == 8'b00000000)
    );

// A1, A2, and A3 high must force X high.
    check_a1_a2_a3_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// A1, A2, and A4 high must force X high.
    check_a1_a2_a4_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A4) |-> X
    );

// A1, A3, and A4 high must force X high.
    check_a1_a3_a4_sets_x: assert property (
        @(posedge clk) (A1 & A3 & A4) |-> X
    );

// A2, A3, and A4 high must force X high.
    check_a2_a3_a4_sets_x: assert property (
        @(posedge clk) (A2 & A3 & A4) |-> X
    );

// A1, A2, and B1 high must force X high.
    check_a1_a2_b1_sets_x: assert property (
        @(posedge clk) (A1 & A2 & B1) |-> X
    );

// A1, A3, and B1 high must force X high.
    check_a1_a3_b1_sets_x: assert property (
        @(posedge clk) (A1 & A3 & B1) |-> X
    );

// A1, A4, and B1 high must force X high.
    check_a1_a4_b1_sets_x: assert property (
        @(posedge clk) (A1 & A4 & B1) |-> X
    );

// A2, A3, and B1 high must force X high.
    check_a2_a3_b1_sets_x: assert property (
        @(posedge clk) (A2 & A3 & B1) |-> X
    );

// A2, A4, and B1 high must force X high.
    check_a2_a4_b1_sets_x: assert property (
        @(posedge clk) (A2 & A4 & B1) |-> X
    );

// A3, A4, and B1 high must force X high.
    check_a3_a4_b1_sets_x: assert property (
        @(posedge clk) (A3 & A4 & B1) |-> X
    );

// Output matches the direct ternary addition branch.
    check_sum_matches_no_sign_ext: assert property (
        @(posedge clk) o == (a + b + c)
    );

// Zero inputs produce a zero output.
    check_zero_output_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0) && (c == '0)) |-> (o == '0)
    );

// With only a present, o is zero-extended a.
    check_a_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((b == '0) && (c == '0)) |-> (o == {{2{1'b0}}, a})
    );

// With only b present, o is zero-extended b.
    check_b_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (c == '0)) |-> (o == {{2{1'b0}}, b})
    );

// With only c present, o is zero-extended c.
    check_c_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0)) |-> (o == {{2{1'b0}}, c})
    );

// Combined output must equal the 5-bit sum of A, B, and Cin.
    check_combined_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The least-significant sum bit must match A[0] xor B[0] xor Cin.
    check_lsb_xor_behavior: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With both operands zero, the output must only reflect Cin.
    check_zero_operands_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> ({Cout, Sum} == {4'b0000, Cin})
    );

// With A zero and Cin low, the output must pass B through with no carry.
    check_a_zero_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, B})
    );

// With B zero and Cin low, the output must pass A through with no carry.
    check_b_zero_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, A})
    );

// Carry-out must be low when the computed sum fits in 4 bits.
    check_no_overflow_no_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> (Cout == 1'b0)
    );

// Carry-out must be high when the computed sum exceeds 4 bits.
    check_overflow_sets_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

// The maximum input combination must produce the maximum 5-bit result.
    check_maximum_input_sum: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, Sum} == 5'h1F)
    );

// No shift selects the direct Gray-code encoding.
    check_no_shift_gray_mapping: assert property (
        @(posedge clk)
        (shift_amount == 2'b00) |-> (
            shifted_gray_code_output ==
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])}
        )
    );

// Shift amount 1 rotates the Gray code left by 1 bit.
    check_shift_by_1_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b01) |-> (
            shifted_gray_code_output ==
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]}
        )
    );

// Shift amount 2 rotates the Gray code left by 2 bits.
    check_shift_by_2_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b10) |-> (
            shifted_gray_code_output ==
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])}
        )
    );

// Shift amount 3 rotates the Gray code left by 3 bits.
    check_shift_by_3_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b11) |-> (
            shifted_gray_code_output ==
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])}
        )
    );

// Synchronous reset clears q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'b0)
    );

// Reset overrides load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'b0)
    );

// Load causes q to capture d on the next sampled cycle.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

// Without load, q holds its previous value.
    check_hold_when_load_low: assert property (
        @(posedge clk) disable iff (rst) !ld |=> (q == $past(q))
    );

// Reset forces both trace outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !jrst_n |-> (atm == 36'b0 && dtm == 36'b0)
    );

// A read captures the address and read data.
    check_read_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        cpu_d_read |=> (atm == {14'b0, $past(cpu_d_address)} &&
                        dtm == {4'b0,  $past(cpu_d_readdata)})
    );

// A write captures the address and write data when no read is present.
    check_write_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                          dtm == {4'b0,  $past(cpu_d_writedata)})
    );

// A wait with no read or write clears both outputs.
    check_wait_clears_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && cpu_d_wait) |=> (atm == 36'b0 && dtm == 36'b0)
    );

// With no control activity, both outputs hold their previous values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && !cpu_d_wait) |=> (atm == $past(atm) && dtm == $past(dtm))
    );

// Read has priority over write and wait.
    check_read_has_priority_over_write_or_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && (cpu_d_write || cpu_d_wait)) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                         dtm == {4'b0,  $past(cpu_d_readdata)})
    );

// Write has priority over wait when no read is present.
    check_write_has_priority_over_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write && cpu_d_wait) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                        dtm == {4'b0,  $past(cpu_d_writedata)})
    );

// Once q is low, the AND-based update keeps it low on the next cycle.
    check_q_sticky_low: assert property (
        @(posedge clk)
        !q |=> !q
    );

// Synchronous reset forces Q to zero by the next clock sample.
    check_reset_clears_counter: assert property (
        @(posedge CK) RST |=> (Q == 4'b0000)
    );

// On reset assertion, sampled Q still reflects the previous non-reset increment.
    check_last_count_visible_on_reset_assertion: assert property (
        @(posedge CK)
        (RST && !$past(RST)) |-> (Q == ($past(Q) + 4'd1))
    );

// Y matches the implemented gate equation.
    check_boolean_function: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

// A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// The only low-output case is A_N low with B high.
    check_low_output_case: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (Y == 1'b0)
    );

// A low Y implies A_N is low and B is high.
    check_y_low_implies_inputs: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1))
    );

// Reset forces the state register to IDLE.
    check_reset_sets_idle: assert property (
        @(posedge clk) !rst_n |-> (cur_state == ST_IDLE)
    );

// Reset keeps ack low.
    check_reset_clears_ack: assert property (
        @(posedge clk) !rst_n |-> (ack == 1'b0)
    );

// No reset is present in the RTL.
    // The DUT is combinational, so checks are sampled on clk.

    // EQ must match the implemented zero-detect of A-B.
    check_eq_matches_rtl_expression: assert property (
        @(posedge clk) EQ == (&(~(A - B)))
    );

// EQ must assert when A and B are equal.
    check_eq_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ == 1'b1)
    );

// EQ must deassert when A and B are different.
    check_eq_when_inputs_different: assert property (
        @(posedge clk) (A != B) |-> (EQ == 1'b0)
    );

// GT is tied low by the RTL logic.
    check_gt_tied_low: assert property (
        @(posedge clk) GT == 1'b0
    );

// AND opcodes drive the bitwise AND of a and b.
    check_and_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0001) || (aluc == 4'b1001)) |-> (result == (a & b))
    );

// OR opcodes drive the bitwise OR of a and b.
    check_or_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0101) || (aluc == 4'b1101)) |-> (result == (a | b))
    );

// XOR opcodes drive the bitwise XOR of a and b.
    check_xor_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b1010) || (aluc == 4'b0010)) |-> (result == (a ^ b))
    );

// LUI opcodes drive zero-extended b[15:0].
    check_lui_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0110) || (aluc == 4'b1110)) |-> (result == {16'b0, b[15:0]})
    );

// ADD opcodes drive a + b.
    check_add_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0000) || (aluc == 4'b1000)) |-> (result == addresult)
    );

// SUB opcodes drive a - b.
    check_sub_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0100) || (aluc == 4'b1100)) |-> (result == subresult)
    );

// SLL opcode drives b shifted left by a.
    check_sll_opcode: assert property (
        @(posedge clk) (aluc == 4'b0011) |-> (result == (b << a))
    );

// SRL opcode drives b shifted right by a.
    check_srl_opcode: assert property (
        @(posedge clk) (aluc == 4'b0111) |-> (result == (b >> a))
    );

// The default opcode 1011 also drives a + b.
    check_default_add_opcode: assert property (
        @(posedge clk) (aluc == 4'b1011) |-> (result == addresult)
    );

// Lower pair follows instance a.
    check_lower_pair_drive: assert property (
        @(posedge clk) {Z10[1], Z10[0]} == (OE ? 2'b10 : 2'b01)
    );

// Upper pair follows instance b with inverted OE.
    check_upper_pair_drive: assert property (
        @(posedge clk) {Z10[3], Z10[2]} == (OE ? 2'b01 : 2'b10)
    );

// Middle bits both track OE.
    check_middle_bits_follow_oe: assert property (
        @(posedge clk) {Z10[2], Z10[1]} == {2{OE}}
    );

// Outer bits both track inverted OE.
    check_outer_bits_follow_inverted_oe: assert property (
        @(posedge clk) {Z10[3], Z10[0]} == {2{~OE}}
    );

// OE high produces the full driven bus pattern.
    check_bus_pattern_when_oe_high: assert property (
        @(posedge clk) OE |-> (Z10 == 4'b0110)
    );

// OE low produces the full driven bus pattern.
    check_bus_pattern_when_oe_low: assert property (
        @(posedge clk) !OE |-> (Z10 == 4'b1001)
    );

// In add mode, result is the 4-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) !SUB |-> (result == (A + B))
    );

// In subtract mode, result is the 4-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) SUB |-> (result == (A - B))
    );

// OVFL always matches the MSB of result.
    check_ovfl_matches_result_msb: assert property (
        @(posedge clk) OVFL == result[3]
    );

// The outputs match the selected arithmetic operation every cycle.
    check_selected_operation: assert property (
        @(posedge clk) result == (SUB ? (A - B) : (A + B))
    );

// When CTRL is low, C is the 4-bit sum of A and B.
    check_add_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b0) |-> (C == (A + B))
    );

// When CTRL is high, C is the sum of zero-extended A[3:1] and B[3:1].
    check_shift_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C == ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

// In add mode, a zero B operand leaves A unchanged.
    check_add_mode_b_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (B == 4'b0000)) |-> (C == A)
    );

// In add mode, a zero A operand leaves B unchanged.
    check_add_mode_a_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'b0000)) |-> (C == B)
    );

// In add mode, overflow wraps to 4 bits on C.
    check_add_mode_overflow_wrap: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'hF) && (B == 4'h1)) |-> (C == 4'h0)
    );

// In shifted mode, zero upper bits on B leave zero-extended A[3:1].
    check_shift_mode_b_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (B[3:1] == 3'b000)) |-> (C == {1'b0, A[3:1]})
    );

// In shifted mode, zero upper bits on A leave zero-extended B[3:1].
    check_shift_mode_a_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000)) |-> (C == {1'b0, B[3:1]})
    );

// In shifted mode, the LSB of C is the sum bit from A[1] and B[1].
    check_shift_mode_lsb: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C[0] == (A[1] ^ B[1]))
    );

// In shifted mode, zero upper slices on both operands force C to zero.
    check_shift_mode_upper_zero_gives_zero: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000) && (B[3:1] == 3'b000)) |-> (C == 4'b0000)
    );

// In shifted mode, carry from the selected upper bits propagates into C[3].
    check_shift_mode_carry_example: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b111) && (B[3:1] == 3'b001)) |-> (C == 4'b1000)
    );

// Output matches a logical left shift of D by A.
    check_shift_relation: assert property (
        @(posedge clk) S == (D << A)
    );

// A value of 0 passes D through unchanged.
    check_shift_by_0: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

// A value of 1 shifts D left by 1 with zero fill.
    check_shift_by_1: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[2:0], 1'b0})
    );

// A value of 2 shifts D left by 2 with zero fill.
    check_shift_by_2: assert property (
        @(posedge clk) (A == 2'b10) |-> (S == {D[1:0], 2'b00})
    );

// A value of 3 shifts D left by 3 with zero fill.
    check_shift_by_3: assert property (
        @(posedge clk) (A == 2'b11) |-> (S == {D[0], 3'b000})
    );

// Y must always be the inversion of A.
    check_inverter_function: assert property (
        @(posedge clk) Y === ~A
    );

// A rising at the sample point must drive Y low.
    check_a_rise_drives_y_low: assert property (
        @(posedge clk) $rose(A) |-> (Y === 1'b0)
    );

// A falling at the sample point must drive Y high.
    check_a_fall_drives_y_high: assert property (
        @(posedge clk) $fell(A) |-> (Y === 1'b1)
    );

// When disabled, the output is forced to zero.
    check_output_zero_when_disabled: assert property (
        @(posedge clk) !EN |-> (Y == 8'b0)
    );

// When enabled and SEL selects D0, the output matches D0.
    check_select_d0_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b00)) |-> (Y == D0)
    );

// When enabled and SEL selects D1, the output matches D1.
    check_select_d1_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b01)) |-> (Y == D1)
    );

// When enabled and SEL selects D2, the output matches D2.
    check_select_d2_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b10)) |-> (Y == D2)
    );

// When enabled and SEL selects D3, the output matches D3.
    check_select_d3_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b11)) |-> (Y == D3)
    );

// SUM[0] matches the first full adder with zero carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0])
    );

// SUM[1] matches the second stage using the bit-0 carry.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// SUM[2] matches the third stage using the propagated carry.
    check_sum_bit2: assert property (
        @(posedge clk)
        SUM[2] == (A[2] ^ B[2] ^
                   ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

// SUM[3] matches the fourth stage using the propagated carry.
    check_sum_bit3: assert property (
        @(posedge clk)
        SUM[3] == (A[3] ^ B[3] ^
                   ((A[2] & B[2]) |
                    (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) &
                     (A[2] ^ B[2]))))
    );

// SUM matches 4-bit addition with overflow discarded.
    check_sum_matches_addition: assert property (
        @(posedge clk) SUM == (A + B)
    );

// Combinational decoder sampled on an external clock; no reset in the RTL.

    // When disabled, all outputs must be low.
    check_disable_drives_zero: assert property (
        @(posedge clk) !EN |-> (Y == 4'b0000)
    );

// Y[0] is high exactly when EN=1 and AB=00.
    check_y0_decode: assert property (
        @(posedge clk) Y[0] == (EN && !A && !B)
    );

// Y[1] is high exactly when EN=1 and AB=01.
    check_y1_decode: assert property (
        @(posedge clk) Y[1] == (EN && !A && B)
    );

// Y[2] is high exactly when EN=1 and AB=10.
    check_y2_decode: assert property (
        @(posedge clk) Y[2] == (EN && A && !B)
    );

// Y[3] is high exactly when EN=1 and AB=11.
    check_y3_decode: assert property (
        @(posedge clk) Y[3] == (EN && A && B)
    );

// When enabled, the output must be one of the four one-hot decode values.
    check_enabled_output_code: assert property (
        @(posedge clk) EN |-> ((Y == 4'b0001) || (Y == 4'b0010) || (Y == 4'b0100) || (Y == 4'b1000))
    );

// The output must always be zero or a valid one-hot decode value.
    check_output_legal_values: assert property (
        @(posedge clk) (Y == 4'b0000) || (Y == 4'b0001) || (Y == 4'b0010) || (Y == 4'b0100) || (Y == 4'b1000)
    );

// out0 is driven by in only for select 000.
    check_out0_decode: assert property (
        @(posedge clk)
        out0 === (((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out1 is driven by in only for select 001.
    check_out1_decode: assert property (
        @(posedge clk)
        out1 === (((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out2 is driven by in only for select 010.
    check_out2_decode: assert property (
        @(posedge clk)
        out2 === (((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out3 is driven by in only for select 011.
    check_out3_decode: assert property (
        @(posedge clk)
        out3 === (((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out4 is driven by in only for select 100.
    check_out4_decode: assert property (
        @(posedge clk)
        out4 === (((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out5 is driven by in only for select 101.
    check_out5_decode: assert property (
        @(posedge clk)
        out5 === (((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out6 is driven by in only for select 110.
    check_out6_decode: assert property (
        @(posedge clk)
        out6 === (((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out7 is driven by in only for select 111.
    check_out7_decode: assert property (
        @(posedge clk)
        out7 === (((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// A low input forces every output low.
    check_input_low_clears_outputs: assert property (
        @(posedge clk)
        (in === 1'b0) |-> ({out7, out6, out5, out4, out3, out2, out1, out0} === 8'b00000000)
    );

// Sample the combinational decoder on clk; the RTL has no reset.

    // A=0 and B=0 must drive only O[0] high.
    check_decode_00: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (O === 16'h0001)
    );

// A=0 and B=1 must drive only O[1] high.
    check_decode_01: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1)) |-> (O === 16'h0002)
    );

// A=1 and B=0 must drive only O[2] high.
    check_decode_10: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0)) |-> (O === 16'h0004)
    );

// A=1 and B=1 must drive only O[3] high.
    check_decode_11: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (O === 16'h0008)
    );

// Unknown or non-binary inputs must select the default all-zero output.
    check_default_zero_on_unknown: assert property (
        @(posedge clk)
        ((((A !== 1'b0) && (A !== 1'b1)) || ((B !== 1'b0) && (B !== 1'b1))))
        |-> (O === 16'h0000)
    );

// The RTL never drives any output bit above O[3].
    check_upper_outputs_zero: assert property (
        @(posedge clk) (O[15:4] === 12'h000)
    );

// The active decoded output in O[3:0] is one-hot or all-zero.
    check_low_nibble_onehot0: assert property (
        @(posedge clk) $onehot0(O[3:0])
    );

// When TE is high and EN is 1, ENCLK is 1 on the next sampled cycle.
    check_capture_one_when_te_high: assert property (
        @(posedge CLK) (TE && EN) |=> (ENCLK == 1'b1)
    );

// When TE is high and EN is 0, ENCLK is 0 on the next sampled cycle.
    check_capture_zero_when_te_high: assert property (
        @(posedge CLK) (TE && !EN) |=> (ENCLK == 1'b0)
    );

// When TE is low, ENCLK holds its previous sampled value.
    check_hold_when_te_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

// ENCLK can change only if TE was high on the previous clock edge.
    check_change_requires_prior_te: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK == $past(ENCLK)) || $past(TE))
    );

// Low reset clears q on the next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) !resetn |=> (q == 26'b0)
    );

// Low squash clears q on the next cycle.
    check_squash_clears_q: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn) |=> (q == 26'b0)
    );

// Enable captures d into q on the next cycle.
    check_enable_captures_d: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && en) |=> (q == $past(d))
    );

// Without enable or clear, q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && !en) |=> (q == $past(q))
    );

// Squash takes priority over enable.
    check_squash_overrides_enable: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn && en) |=> (q == 26'b0)
    );

// The 5-bit output must equal A + B + CIN.
    check_total_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN})
    );

// The least-significant sum bit matches the first full-adder XOR.
    check_lsb_sum: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

// Carry-out reflects overflow of the 4-bit addition.
    check_cout_overflow: assert property (
        @(posedge clk)
        COUT == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN}) > 5'd15)
    );

// With no carry-in, the result matches A + B.
    check_add_without_cin: assert property (
        @(posedge clk)
        !CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B}))
    );

// With carry-in asserted, the result matches A + B + 1.
    check_add_with_cin: assert property (
        @(posedge clk)
        CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + 5'b00001))
    );

// Adding zero to A with no carry-in returns A and no carry-out.
    check_a_identity: assert property (
        @(posedge clk)
        (B == 4'b0000 && !CIN) |-> (SUM == A && COUT == 1'b0)
    );

// Adding zero to B with no carry-in returns B and no carry-out.
    check_b_identity: assert property (
        @(posedge clk)
        (A == 4'b0000 && !CIN) |-> (SUM == B && COUT == 1'b0)
    );

// Zero plus zero produces only the carry-in in the result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (A == 4'b0000 && B == 4'b0000) |-> ({COUT, SUM} == {4'b0000, CIN})
    );

// A carry-in propagates through all bits when the other operand is all ones.
    check_cin_propagation: assert property (
        @(posedge clk)
        (((A == 4'hF) && (B == 4'h0) && (CIN == 1'b1)) ||
         ((A == 4'h0) && (B == 4'hF) && (CIN == 1'b1)))
        |-> (SUM == 4'h0 && COUT == 1'b1)
    );

// Maximum inputs with carry-in overflow and leave SUM at all ones.
    check_max_input_overflow: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (SUM == 4'hF && COUT == 1'b1)
    );

// Output stays within the values produced by the case mapping.
    check_out_valid_range: assert property (
        @(posedge clk) disable iff (rst)
        (out <= 7)
    );

// Output 0 is a stable fixed point.
    check_out_zero_stays_zero: assert property (
        @(posedge clk) disable iff (rst)
        (out == '0) |=> (out == '0)
    );

// Output 1 is a stable fixed point.
    check_out_one_stays_one: assert property (
        @(posedge clk) disable iff (rst)
        (out == 1) |=> (out == 1)
    );

// Reset drives q to 0.
    check_reset_clears_q: assert property (
        @(posedge clk) !post_cb.areset |-> (post_cb.q == 4'b0000)
    );

// Load captures data on the clock edge.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load |-> (post_cb.q == data)
    );

// Load has priority over enable.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load && ena |-> (post_cb.q == data)
    );

// Enable rotates q as {q[2:0], q[3]} when not loading.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && ena |-> (post_cb.q == {q[2:0], q[3]})
    );

// With neither load nor enable, q holds its value.
    check_idle_holds_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && !ena |-> (post_cb.q == q)
    );

// An input LSB of 1 must drive output 01.
    check_lsb_one_maps_to_01: assert property (
        @(posedge clk) (input_bits[0] === 1'b1) |-> (output_bits == 2'b01)
    );

// Any non-1 LSB value must drive output 10.
    check_lsb_not_one_maps_to_10: assert property (
        @(posedge clk) (input_bits[0] !== 1'b1) |-> (output_bits == 2'b10)
    );

// output_bits[0] reflects whether the LSB is exactly 1.
    check_output_bit0_matches_true_branch: assert property (
        @(posedge clk) output_bits[0] == (input_bits[0] === 1'b1)
    );

// output_bits[1] reflects the else branch selection.
    check_output_bit1_matches_else_branch: assert property (
        @(posedge clk) output_bits[1] == (input_bits[0] !== 1'b1)
    );

// The output must always be one of the two assigned encodings.
    check_output_encoding_is_valid: assert property (
        @(posedge clk) ((output_bits == 2'b01) || (output_bits == 2'b10))
    );

// Output must equal the input with only the MSB inverted.
    check_invert_msb_function: assert property (
        @(posedge clk) o_inverted === {~i_binary[3], i_binary[2:0]}
    );

// Output MSB must be the inverse of the input MSB.
    check_output_msb_inverted: assert property (
        @(posedge clk) o_inverted[3] === ~i_binary[3]
    );

// Output lower three bits must pass through unchanged.
    check_output_lower_bits_passthrough: assert property (
        @(posedge clk) o_inverted[2:0] === i_binary[2:0]
    );

// X must match the full mux sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A0 & ~S0 & ~S1) |
              (A1 &  S0 & ~S1) |
              (A2 & ~S0 &  S1) |
              (A3 &  S0 &  S1))
    );

// When select is 00, X must follow A0.
    check_select_00: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b0)) |-> (X == A0)
    );

// When select is 01, X must follow A1.
    check_select_01: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b1)) |-> (X == A1)
    );

// When select is 10, X must follow A2.
    check_select_10: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b0)) |-> (X == A2)
    );

// When select is 11, X must follow A3.
    check_select_11: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b1)) |-> (X == A3)
    );

// With S1 low, X must select between A0 and A1 using S0.
    check_s1_low_lower_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0) |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

// With S1 high, X must select between A2 and A3 using S0.
    check_s1_high_upper_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1) |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

// With S0 low, X must select between A0 and A2 using S1.
    check_s0_low_even_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b0) |-> (X == ((A0 & ~S1) | (A2 & S1)))
    );

// With S0 high, X must select between A1 and A3 using S1.
    check_s0_high_odd_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b1) |-> (X == ((A1 & ~S1) | (A3 & S1)))
    );

// An enabled rising edge loads D into Q.
    check_load_on_enable: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

// A disabled rising edge leaves Q unchanged.
    check_hold_on_disable: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

// Enabled new data must change Q on the next sampled cycle.
    check_change_on_new_enabled_data: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q != $past(Q))
    );

// Enabled same data must leave Q unchanged.
    check_no_change_on_same_enabled_data: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

// When load is low, the output holds its value.
    check_out_holds_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST)
        !LD |=> (OUT == $past(OUT))
    );

// Carry output matches the input AND.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// Sum output matches the input XOR.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// 0 + 0 produces zero sum and zero carry.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> (!SUM && !COUT)
    );

// 1 + 0 produces sum with no carry.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> (SUM && !COUT)
    );

// 0 + 1 produces sum with no carry.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> (SUM && !COUT)
    );

// 1 + 1 produces carry with no sum.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> (!SUM && COUT)
    );

// Output equals the XOR of the two inputs.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

// Equal inputs drive the output low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (A == B) |-> !X
    );

// Different inputs drive the output high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (A != B) |-> X
    );

// 0 ^ 0 produces 0.
    check_00_to_0: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// 0 ^ 1 produces 1.
    check_01_to_1: assert property (
        @(posedge clk) (!A && B) |-> X
    );

// 1 ^ 0 produces 1.
    check_10_to_1: assert property (
        @(posedge clk) (A && !B) |-> X
    );

// 1 ^ 1 produces 0.
    check_11_to_0: assert property (
        @(posedge clk) (A && B) |-> !X
    );

// Pure combinational mux; sampled on an external clock with no RTL reset.

    // When S is high, X selects A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1) |-> (X === A1)
    );

// When S is low, X selects A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0) |-> (X === A0)
    );

// If both data inputs are equal, X matches that common value.
    check_equal_inputs_force_same_output: assert property (
        @(posedge clk) disable iff (1'b0)
        (A0 === A1) |-> (X === A0)
    );

// On a clkin rise, the sampled low-input state must have clkout high.
    check_clkout_high_before_clkin_rise: assert property (
        @(posedge clkin) clkout === 1'b1
    );

// On a clkin fall, the sampled high-input state must have clkout low.
    check_clkout_low_before_clkin_fall: assert property (
        @(negedge clkin) clkout === 1'b0
    );

// CLK is the only clock; RST is a synchronous active-high reset.
    // DATA_OUT is an 8-bit registered output.

    ///// Reset behavior /////

    // When reset is asserted, DATA_OUT must be 0 on the following clock.
    check_reset_clears_data_out: assert property (
        @(posedge CLK)
        RST |=> (DATA_OUT === 8'h00)
    );

///// Active-state behavior /////

    // In active mode, F4 must toggle to C2 on the next clock.
    check_f4_transitions_to_c2: assert property (
        @(posedge CLK) disable iff (RST)
        (DATA_OUT === 8'hf4) |=> (DATA_OUT === 8'hc2)
    );

// In active mode, any value other than F4 must become F4 on the next clock.
    check_non_f4_transitions_to_f4: assert property (
        @(posedge CLK) disable iff (RST)
        (DATA_OUT !== 8'hf4) |=> (DATA_OUT === 8'hf4)
    );

// Reset forces the state register to S0.
    check_reset_forces_state_s0: assert property (
        @(posedge clk_i) !reset_n |-> (state == S0)
    );

// Reset drives sel to the S0 decode value.
    check_reset_drives_sel_s0: assert property (
        @(posedge clk_i) !reset_n |-> (sel == 3'b000)
    );

// sel only takes one of the implemented decode values.
    check_sel_legal_values: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (sel == 3'b000) || (sel == 3'b001) || (sel == 3'b011) || (sel == 3'b100)
    );

// shift_amount 00 passes data through unchanged.
    check_shift_0_passthrough: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

// shift_amount 01 shifts left by 1 with zero fill.
    check_shift_1_left_by_1: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// shift_amount 10 shifts left by 2 with zero fill.
    check_shift_2_left_by_2: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// shift_amount 11 shifts left by 3 with zero fill.
    check_shift_3_left_by_3: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[0], 3'b000})
    );

// Synchronous reset drives the state to IDLE.
    check_reset_forces_idle: assert property (
        @(posedge clk) reset |=> (estado_atual == IDLE)
    );

// LED captures the previous cycle's infrared sample.
    check_led_samples_infrared: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (led == $past(infrared))
    );

// Button outputs are never asserted.
    check_buttons_always_low: assert property (
        @(posedge clk) disable iff (reset)
        (botao_1 == 1'b0 && botao_2 == 1'b0 && botao_3 == 1'b0 && botao_4 == 1'b0)
    );

// Q follows the RTL next-state function across clock edges.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> Q == ($past(DE) ? $past(D) : ($past(SCE) ? $past(SCD) : $past(Q)))
    );

// Q captures D when only DE is asserted.
    check_capture_d_when_de_only: assert property (
        @(posedge CLK) disable iff (1'b0)
        (DE && !SCE) |=> Q == $past(D)
    );

// DE has priority over SCE when both enables are asserted.
    check_de_priority_over_sce: assert property (
        @(posedge CLK) disable iff (1'b0)
        (DE && SCE) |=> Q == $past(D)
    );

// Q captures SCD when scan enable is asserted without DE.
    check_capture_scd_when_sce_only: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && SCE) |=> Q == $past(SCD)
    );

// Q holds its value when neither enable is asserted.
    check_hold_when_no_enable: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && !SCE) |=> Q == $past(Q)
    );

// Q can only change after a clock edge with DE or SCE asserted.
    check_change_requires_enable: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (!$changed(Q) || ($past(DE) || $past(SCE)))
    );

// Active-low reset clears Q to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) !AR[0] |-> (Q == {N{1'b0}})
    );

// When enabled, Q accumulates D.
    check_accumulate_on_enable: assert property (
        @(posedge CLK) disable iff (!AR[0])
        E[0] |=> (Q == ($past(Q) + $past(D)))
    );

// When not enabled, Q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!AR[0])
        !E[0] |=> (Q == $past(Q))
    );

// Combined outputs match 1-bit addition.
    check_full_adder_result: assert property (
        @(posedge clk)
        ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI}))
    );

// SUM is the XOR of the three inputs.
    check_sum_parity: assert property (
        @(posedge clk)
        (SUM == (A ^ B ^ CI))
    );

// COUT is high when any two inputs are high.
    check_cout_majority: assert property (
        @(posedge clk)
        (COUT == ((A & B) | (A & CI) | (B & CI)))
    );

// All-zero inputs produce zero outputs.
    check_all_zero_case: assert property (
        @(posedge clk)
        ((!A && !B && !CI) |-> (!COUT && !SUM))
    );

// Exactly one high input produces SUM only.
    check_one_high_case: assert property (
        @(posedge clk)
        (((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (SUM && !COUT))
    );

// Exactly two high inputs produce COUT only.
    check_two_high_case: assert property (
        @(posedge clk)
        (((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (!SUM && COUT))
    );

// All-one inputs produce both SUM and COUT.
    check_all_one_case: assert property (
        @(posedge clk)
        ((A && B && CI) |-> (SUM && COUT))
    );

// External sampling clock; the DUT itself is combinational and has no reset.

    // out_or_bitwise[0] is the OR of a[0] and b[0].
    check_or_bit0: assert property (
        @(posedge clk) out_or_bitwise[0] == (a[0] | b[0])
    );

// out_or_bitwise[1] is the OR of a[1] and b[1].
    check_or_bit1: assert property (
        @(posedge clk) out_or_bitwise[1] == (a[1] | b[1])
    );

// out_or_bitwise[2] is the OR of a[2] and b[2].
    check_or_bit2: assert property (
        @(posedge clk) out_or_bitwise[2] == (a[2] | b[2])
    );

// out_or_logical is the OR-reduction of the bitwise OR result.
    check_logical_or_reduce: assert property (
        @(posedge clk) out_or_logical == (out_or_bitwise[0] | out_or_bitwise[1] | out_or_bitwise[2])
    );

// out_not[3] is the inversion of a[0].
    check_not_a_bit0: assert property (
        @(posedge clk) out_not[3] == ~a[0]
    );

// out_not[4] is the inversion of a[1].
    check_not_a_bit1: assert property (
        @(posedge clk) out_not[4] == ~a[1]
    );

// out_not[5] is the inversion of a[2].
    check_not_a_bit2: assert property (
        @(posedge clk) out_not[5] == ~a[2]
    );

// out_not[0] is the inversion of b[0].
    check_not_b_bit0: assert property (
        @(posedge clk) out_not[0] == ~b[0]
    );

// out_not[1] is the inversion of b[1].
    check_not_b_bit1: assert property (
        @(posedge clk) out_not[1] == ~b[1]
    );

// out_not[2] is the inversion of b[2].
    check_not_b_bit2: assert property (
        @(posedge clk) out_not[2] == ~b[2]
    );

// Supply pins hold their declared constant values.
    check_supply_constants: assert property (
        @(posedge clk) disable iff (1'b0)
        (VPWR == 1'b1) && (VGND == 1'b0) && (VPB == 1'b1) && (VNB == 1'b0)
    );

// Y matches the implemented NOR-of-NORs logic.
    check_y_boolean_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A | B) & (C | D))
    );

// If both A and B are low, Y must be low.
    check_ab_zero_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b0) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// If both C and D are low, Y must be low.
    check_cd_zero_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((C == 1'b0) && (D == 1'b0)) |-> (Y == 1'b0)
    );

// A high Y requires at least one of A or B to be high.
    check_y_high_requires_ab_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((A == 1'b1) || (B == 1'b1))
    );

// A high Y requires at least one of C or D to be high.
    check_y_high_requires_cd_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((C == 1'b1) || (D == 1'b1))
    );

// One high input in each pair drives Y high.
    check_pairwise_or_drives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (((A == 1'b1) || (B == 1'b1)) && ((C == 1'b1) || (D == 1'b1))) |-> (Y == 1'b1)
    );

// A sampled reset leaves the counter cleared by the next clock.
    check_reset_clears_by_next_clock: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset deassertion is observed with count still at zero.
    check_reset_release_sees_zero: assert property (
        @(posedge clk) reset ##1 !reset |-> (count == 4'b0000)
    );

// From 15, the counter wraps back to zero.
    check_wrap_from_fifteen: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'b1111) |=> (count == 4'b0000)
    );

// On non-reset cycles, the next sampled count is zero or increments by one.
    check_count_progression: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |=> ((count == 4'b0000) || (count == ($past(count) + 4'b0001)))
    );

// Y always matches the RTL's selected combinational expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) Y == (invert ? ~((~A) + 4'h1) : ((~A) + 4'h1))
    );

// When invert is low, Y is ~A plus one.
    check_noninvert_branch: assert property (
        @(posedge clk) !invert |-> (Y == ((~A) + 4'h1))
    );

// When invert is high, Y is the complement of ~A plus one.
    check_invert_branch: assert property (
        @(posedge clk) invert |-> (Y == ~((~A) + 4'h1))
    );

// A value of zero produces zero when invert is low.
    check_zero_noninvert: assert property (
        @(posedge clk) !invert && (A == 4'h0) |-> (Y == 4'h0)
    );

// A value of zero produces all ones when invert is high.
    check_zero_invert: assert property (
        @(posedge clk) invert && (A == 4'h0) |-> (Y == 4'hF)
    );

// A value of all ones produces one when invert is low.
    check_allones_noninvert: assert property (
        @(posedge clk) !invert && (A == 4'hF) |-> (Y == 4'h1)
    );

// A value of all ones produces fourteen when invert is high.
    check_allones_invert: assert property (
        @(posedge clk) invert && (A == 4'hF) |-> (Y == 4'hE)
    );

// Combinational DUT with no reset; sample behavior on clk.

    // Y must match the implemented boolean equation.
    check_boolean_function: assert property (
        @(posedge clk) Y === ((~A_N) & (~B))
    );

// Both inputs low must drive Y high.
    check_output_high_when_inputs_low: assert property (
        @(posedge clk) ((A_N === 1'b0) && (B === 1'b0)) |-> (Y === 1'b1)
    );

// A_N high must drive Y low.
    check_output_low_when_a_n_high: assert property (
        @(posedge clk) (A_N === 1'b1) |-> (Y === 1'b0)
    );

// B high must drive Y low.
    check_output_low_when_b_high: assert property (
        @(posedge clk) (B === 1'b1) |-> (Y === 1'b0)
    );

// Y high implies both inputs are low.
    check_output_high_only_when_inputs_low: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A_N === 1'b0) && (B === 1'b0))
    );

// Overall mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == (sel1 ? (sel0 ? in3 : in2) : (sel0 ? in1 : in0))
    );

// sel1=0 and sel0=0 selects in0.
    check_select_00_routes_in0: assert property (
        @(posedge clk) (!sel1 && !sel0) |-> (out == in0)
    );

// sel1=0 and sel0=1 selects in1.
    check_select_01_routes_in1: assert property (
        @(posedge clk) (!sel1 && sel0) |-> (out == in1)
    );

// sel1=1 and sel0=0 selects in2.
    check_select_10_routes_in2: assert property (
        @(posedge clk) (sel1 && !sel0) |-> (out == in2)
    );

// sel1=1 and sel0=1 selects in3.
    check_select_11_routes_in3: assert property (
        @(posedge clk) (sel1 && sel0) |-> (out == in3)
    );

// Read busy is permanently deasserted.
    check_rd_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_BUSY == 1'b0)
    );

// Read MMU flags are permanently zero.
    check_rd_mmu_flags_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_MMU_FLAGS == 12'h000)
    );

// Read hit is permanently deasserted.
    check_rd_hit_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_HIT == 1'b0)
    );

// Read data is permanently zero.
    check_rd_data_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_DATA == 32'h00000000)
    );

// Update busy is permanently deasserted.
    check_up_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oUP_BUSY == 1'b0)
    );

// Write busy is permanently deasserted.
    check_wr_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oWR_BUSY == 1'b0)
    );

// Sync reset or remove clears the registered read valid on the next cycle.
    check_rd_valid_clears_on_sync_reset_or_remove: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (iRESET_SYNC || iREMOVE) |=> (oRD_VALID == 1'b0)
    );

// Without clear conditions, a high read request sets read valid on the next cycle.
    check_rd_valid_sets_from_rd_req: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && iRD_REQ) |=> (oRD_VALID == 1'b1)
    );

// Without clear conditions, a low read request clears read valid on the next cycle.
    check_rd_valid_clears_from_rd_req_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && !iRD_REQ) |=> (oRD_VALID == 1'b0)
    );

// A greater than B must produce the greater-than code.
    check_result_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

// A less than B must produce the less-than code.
    check_result_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

// Equal inputs must produce the equal code.
    check_result_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// The greater-than code must only appear when A is greater than B.
    check_code_01_means_a_gt_b: assert property (
        @(posedge clk) (result == 2'b01) |-> (A > B)
    );

// The less-than code must only appear when A is less than B.
    check_code_10_means_a_lt_b: assert property (
        @(posedge clk) (result == 2'b10) |-> (A < B)
    );

// The equal code must only appear when A and B are equal.
    check_code_00_means_a_eq_b: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

// The reserved encoding is never driven.
    check_result_encoding_valid: assert property (
        @(posedge clk) (result != 2'b11)
    );

// Out matches the implemented mux equation.
    check_mux_boolean_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        out == ((in0 & ~sel) | (in1 & sel))
    );

// When sel is low, out follows in0.
    check_sel_low_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b0) |-> (out == in0)
    );

// When sel is high, out follows in1.
    check_sel_high_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b1) |-> (out == in1)
    );

// If both inputs are low, out is low.
    check_both_inputs_low_drive_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b0) |-> (out == 1'b0)
    );

// If both inputs are high, out is high.
    check_both_inputs_high_drive_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b1) |-> (out == 1'b1)
    );

// With in0 high and in1 low, out is the inverse of sel.
    check_in0_high_in1_low_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b0) |-> (out == ~sel)
    );

// With in0 low and in1 high, out matches sel.
    check_in0_low_in1_high_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b1) |-> (out == sel)
    );

// The 5-bit result matches unsigned addition of a, b, and cin.
    check_total_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum bit 0 matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == fa_sum(a[0], b[0], cin)
    );

// Sum bit 1 matches the ripple carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == fa_sum(a[1], b[1], fa_cout(a[0], b[0], cin))
    );

// Sum bit 2 matches the ripple carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == fa_sum(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin)))
    );

// Sum bit 3 matches the ripple carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == fa_sum(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Carry out matches the final ripple-carry stage.
    check_cout_chain: assert property (
        @(posedge clk) cout == fa_cout(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Adding zero with cin low passes a through unchanged.
    check_passthrough_a: assert property (
        @(posedge clk) (b == 4'h0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with cin low passes b through unchanged.
    check_passthrough_b: assert property (
        @(posedge clk) (a == 4'h0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// Zero plus zero produces cin in the LSB with no carry out.
    check_zero_plus_cin: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

// X matches the RTL combinational equation.
    check_x_matches_rtl: assert property (
        @(posedge clk)
        X == ((A && B) || (C || D) || !(E && F) || !(G || H))
    );

// A and B both high force X high.
    check_x_high_when_ab_high: assert property (
        @(posedge clk)
        (A && B) |-> X
    );

// Either C or D high forces X high.
    check_x_high_when_cd_high: assert property (
        @(posedge clk)
        (C || D) |-> X
    );

// If E and F are not both high, X must be high.
    check_x_high_when_ef_not_both_high: assert property (
        @(posedge clk)
        !(E && F) |-> X
    );

// If G and H are both low, X must be high.
    check_x_high_when_gh_both_low: assert property (
        @(posedge clk)
        !(G || H) |-> X
    );

// X low requires all four RTL terms to be false.
    check_x_low_implies_false_terms: assert property (
        @(posedge clk)
        !X |-> (!(A && B) && !(C || D) && (E && F) && (G || H))
    );

// If all four RTL terms are false, X must be low.
    check_x_low_when_false_terms: assert property (
        @(posedge clk)
        (!(A && B) && !(C || D) && (E && F) && (G || H)) |-> !X
    );

// Addition mode computes the sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == s8_t'(a + b)) &&
                           (sub_out == 8'sd0) &&
                           (mul_out == 8'sd0) &&
                           (div_out == 8'sd0))
    );

// Subtraction mode computes the difference and clears the other outputs.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((add_out == 8'sd0) &&
                           (sub_out == s8_t'(a - b)) &&
                           (mul_out == 8'sd0) &&
                           (div_out == 8'sd0))
    );

// add_out is cleared whenever addition is not selected.
    check_add_out_cleared_when_not_add: assert property (
        @(posedge clk)
        (op != 2'b00) |-> (add_out == 8'sd0)
    );

// sub_out is cleared whenever subtraction is not selected.
    check_sub_out_cleared_when_not_sub: assert property (
        @(posedge clk)
        (op != 2'b01) |-> (sub_out == 8'sd0)
    );

// mul_out is cleared whenever multiplication is not selected.
    check_mul_out_cleared_when_not_mul: assert property (
        @(posedge clk)
        (op != 2'b10) |-> (mul_out == 8'sd0)
    );

// div_out is cleared whenever division is not selected.
    check_div_out_cleared_when_not_div: assert property (
        @(posedge clk)
        (op != 2'b11) |-> (div_out == 8'sd0)
    );

// Output matches the 4-bit subtraction of A and B.
    check_subtract_function: assert property (
        @(posedge clk) disable iff (1'b0) Y == (A - B)
    );

// Adding B back to Y recovers A modulo 16.
    check_add_back_recovers_a: assert property (
        @(posedge clk) disable iff (1'b0) (Y + B) == A
    );

// Equal operands produce a zero result.
    check_equal_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A == B) |-> (Y == 4'h0)
    );

// Subtracting zero passes A through unchanged.
    check_zero_subtrahend_passthrough: assert property (
        @(posedge clk) disable iff (1'b0) (B == 4'h0) |-> (Y == A)
    );

// Zero minus B produces the wrapped 4-bit result.
    check_zero_minuend_wrap: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'h0) |-> (Y == (4'h0 - B))
    );

// y must implement the XOR of a and b.
    check_xor_function: assert property (
        @(posedge clk) y == (a ^ b)
    );

// When both inputs are low, y must be low.
    check_y_low_for_00: assert property (
        @(posedge clk) (!a && !b) |-> !y
    );

// When only b is high, y must be high.
    check_y_high_for_01: assert property (
        @(posedge clk) (!a && b) |-> y
    );

// When only a is high, y must be high.
    check_y_high_for_10: assert property (
        @(posedge clk) (a && !b) |-> y
    );

// When both inputs are high, y must be low.
    check_y_low_for_11: assert property (
        @(posedge clk) (a && b) |-> !y
    );

// Reset drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over enable when both are high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// When enabled outside reset, count increments by one.
    check_increment_on_enable: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled outside reset, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Enabling at 4'hf wraps the counter back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hf)) |=> (count == 4'h0)
    );

// Clock: clk
    // Reset: areset is asynchronous active-high
    // Logic: sequential shift_reg/q with combinational shifted_value

    // Reset clears the internal shift register.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) areset |-> (shift_reg == 4'b0000)
    );

// Reset clears the output register.
    check_reset_clears_q: assert property (
        @(posedge clk) areset |-> (q == 4'b0000)
    );

// shifted_value is always the zero-filled right shift of shift_reg.
    check_shifted_value_definition: assert property (
        @(posedge clk) disable iff (areset)
        shifted_value == {1'b0, shift_reg[3:1]}
    );

// load has priority and loads data into shift_reg.
    check_shift_reg_load_behavior: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (shift_reg == $past(data))
    );

// Without load, ena shifts shift_reg right with zero fill.
    check_shift_reg_shift_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (shift_reg == {1'b0, $past(shift_reg[3:1])})
    );

// With neither load nor ena, shift_reg holds its value.
    check_shift_reg_hold_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (shift_reg == $past(shift_reg))
    );

// q loads data only when both load and ena are high.
    check_q_load_when_load_and_ena: assert property (
        @(posedge clk) disable iff (areset)
        (load && ena) |=> (q == $past(data))
    );

// Otherwise q takes the prior shifted_value.
    check_q_uses_prior_shifted_value_otherwise: assert property (
        @(posedge clk) disable iff (areset)
        !(load && ena) |=> (q == $past(shifted_value))
    );

// When ena is high, q and shift_reg update to the same value.
    check_q_matches_shift_reg_after_enable: assert property (
        @(posedge clk) disable iff (areset)
        ena |=> (q == shift_reg)
    );

// gray_out[3] matches the previous cycle binary_in[3].
    check_gray_msb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[3] == $past(binary_in[3])
    );

// gray_out[2] matches the previous cycle binary_in[3] ^ binary_in[2].
    check_gray_bit2: assert property (
        @(posedge clk) 1'b1 |=> gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2]))
    );

// gray_out[1] matches the previous cycle binary_in[2] ^ binary_in[1].
    check_gray_bit1: assert property (
        @(posedge clk) 1'b1 |=> gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1]))
    );

// gray_out[0] matches the previous cycle binary_in[1] ^ binary_in[0].
    check_gray_lsb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0]))
    );

// gray_out matches the previous cycle Gray-code conversion of binary_in.
    check_gray_bus: assert property (
        @(posedge clk) 1'b1 |=> gray_out == {
            $past(binary_in[3]),
            ($past(binary_in[3]) ^ $past(binary_in[2])),
            ($past(binary_in[2]) ^ $past(binary_in[1])),
            ($past(binary_in[1]) ^ $past(binary_in[0]))
        }
    );

// Result matches the full bitwise AND of the inputs.
    check_result_vector_and: assert property (
        @(posedge clk) result === (a & b)
    );

// Bit 0 of result matches a[0] & b[0].
    check_result_bit0_and: assert property (
        @(posedge clk) result[0] === (a[0] & b[0])
    );

// Bit 1 of result matches a[1] & b[1].
    check_result_bit1_and: assert property (
        @(posedge clk) result[1] === (a[1] & b[1])
    );

// Bit 2 of result matches a[2] & b[2].
    check_result_bit2_and: assert property (
        @(posedge clk) result[2] === (a[2] & b[2])
    );

// Bit 3 of result matches a[3] & b[3].
    check_result_bit3_and: assert property (
        @(posedge clk) result[3] === (a[3] & b[3])
    );

// Zero on a forces a zero result.
    check_zero_when_a_zero: assert property (
        @(posedge clk) (a === 4'h0) |-> (result === 4'h0)
    );

// Zero on b forces a zero result.
    check_zero_when_b_zero: assert property (
        @(posedge clk) (b === 4'h0) |-> (result === 4'h0)
    );

// All ones on a passes b through to the result.
    check_passthrough_when_a_all_ones: assert property (
        @(posedge clk) (a === 4'hF) |-> (result === b)
    );

// All ones on b passes a through to the result.
    check_passthrough_when_b_all_ones: assert property (
        @(posedge clk) (b === 4'hF) |-> (result === a)
    );

// All ones on both inputs produces all ones on the result.
    check_all_ones_when_both_all_ones: assert property (
        @(posedge clk) ((a === 4'hF) && (b === 4'hF)) |-> (result === 4'hF)
    );

// Output matches the two XOR stages feeding the final AND.
    check_out_final_function: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

// If the first XOR stage is low, the final output must be low.
    check_first_xor_blocks_output: assert property (
        @(posedge clk) !(a ^ b) |-> !out_final
    );

// If the second XOR stage is low, the final output must be low.
    check_second_xor_blocks_output: assert property (
        @(posedge clk) !(c ^ d) |-> !out_final
    );

// A high output requires both XOR stages to be high.
    check_output_high_requires_both_xors: assert property (
        @(posedge clk) out_final |-> ((a ^ b) && (c ^ d))
    );

// If both XOR stages are high, the final output must be high.
    check_both_xors_drive_output_high: assert property (
        @(posedge clk) ((a ^ b) && (c ^ d)) |-> out_final
    );

// Valid decimal inputs pass through unchanged.
    check_valid_decimal_passthrough: assert property (
        @(posedge clk)
        ((in_value == 4'd0) || (in_value == 4'd1) || (in_value == 4'd2) || (in_value == 4'd3) ||
         (in_value == 4'd4) || (in_value == 4'd5) || (in_value == 4'd6) || (in_value == 4'd7) ||
         (in_value == 4'd8) || (in_value == 4'd9))
        |-> (out_value == in_value)
    );

// Input 0 maps to output 0.
    check_digit_0_identity: assert property (
        @(posedge clk)
        (in_value == 4'd0) |-> (out_value == 4'd0)
    );

// Input 1 maps to output 1.
    check_digit_1_identity: assert property (
        @(posedge clk)
        (in_value == 4'd1) |-> (out_value == 4'd1)
    );

// Input 2 maps to output 2.
    check_digit_2_identity: assert property (
        @(posedge clk)
        (in_value == 4'd2) |-> (out_value == 4'd2)
    );

// Input 3 maps to output 3.
    check_digit_3_identity: assert property (
        @(posedge clk)
        (in_value == 4'd3) |-> (out_value == 4'd3)
    );

// Input 4 maps to output 4.
    check_digit_4_identity: assert property (
        @(posedge clk)
        (in_value == 4'd4) |-> (out_value == 4'd4)
    );

// Input 5 maps to output 5.
    check_digit_5_identity: assert property (
        @(posedge clk)
        (in_value == 4'd5) |-> (out_value == 4'd5)
    );

// Input 6 maps to output 6.
    check_digit_6_identity: assert property (
        @(posedge clk)
        (in_value == 4'd6) |-> (out_value == 4'd6)
    );

// Input 7 maps to output 7.
    check_digit_7_identity: assert property (
        @(posedge clk)
        (in_value == 4'd7) |-> (out_value == 4'd7)
    );

// Input 8 maps to output 8.
    check_digit_8_identity: assert property (
        @(posedge clk)
        (in_value == 4'd8) |-> (out_value == 4'd8)
    );

// Input 9 maps to output 9.
    check_digit_9_identity: assert property (
        @(posedge clk)
        (in_value == 4'd9) |-> (out_value == 4'd9)
    );

// Y implements ~(B1 & (A1 | A2 | A3)).
    check_functional_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~(B1 & (A1 | A2 | A3))
    );

// B1 low forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        !B1 |-> Y
    );

// All A inputs low force the OR term low and Y high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        !(A1 | A2 | A3) |-> Y
    );

// A1 high with B1 high forces Y low.
    check_a1_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && B1) |-> !Y
    );

// A2 high with B1 high forces Y low.
    check_a2_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A2 && B1) |-> !Y
    );

// A3 high with B1 high forces Y low.
    check_a3_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A3 && B1) |-> !Y
    );

// Y low requires B1 high and at least one A input high.
    check_y_low_requires_b1_and_any_a: assert property (
        @(posedge clk) disable iff (1'b0)
        !Y |-> (B1 && (A1 | A2 | A3))
    );

// Y high while B1 is high requires all A inputs low.
    check_y_high_with_b1_requires_all_a_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y && B1) |-> !(A1 | A2 | A3)
    );

// sel1=0 and sel0=0 must route in0 to out.
    check_select_00_routes_in0: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out == in0)
    );

// sel1=0 and sel0=1 must route in1 to out.
    check_select_01_routes_in1: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out == in1)
    );

// sel1=1 and sel0=0 must route in2 to out.
    check_select_10_routes_in2: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out == in2)
    );

// sel1=1 and sel0=1 must route in3 to out.
    check_select_11_routes_in3: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out == in3)
    );

// When the lower pair matches and sel1 selects it, sel0 cannot change out.
    check_sel1_low_equal_lower_pair: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (in0 == in1)) |-> (out == in0)
    );

// When the upper pair matches and sel1 selects it, sel0 cannot change out.
    check_sel1_high_equal_upper_pair: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (in2 == in3)) |-> (out == in2)
    );

// When left-side inputs match and sel0 selects them, sel1 cannot change out.
    check_sel0_low_equal_left_inputs: assert property (
        @(posedge clk) ((sel0 == 1'b0) && (in0 == in2)) |-> (out == in0)
    );

// When right-side inputs match and sel0 selects them, sel1 cannot change out.
    check_sel0_high_equal_right_inputs: assert property (
        @(posedge clk) ((sel0 == 1'b1) && (in1 == in3)) |-> (out == in1)
    );

// Y must equal the three-input AND of A, B, and C.
    check_y_matches_three_input_and: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == (A & B & C)
    );

// Y high requires all three inputs high.
    check_y_high_implies_all_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// All three inputs high must drive Y high.
    check_all_inputs_high_implies_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b1) && (B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b1)
    );

// Any low input must drive Y low.
    check_any_low_input_implies_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b0) || (B == 1'b0) || (C == 1'b0)) |-> (Y == 1'b0)
    );

// Y low means at least one input is low.
    check_y_low_implies_at_least_one_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b0) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0))
    );

// Up increments Q when it is not at the maximum value.
    check_up_increment: assert property (
        @(posedge clk) disable iff (1'b0)
        Up && (Q != 4'hF) |=> (Q == ($past(Q) + 4'h1))
    );

// Up wraps Q from 15 back to 0.
    check_up_wrap: assert property (
        @(posedge clk) disable iff (1'b0)
        Up && (Q == 4'hF) |=> (Q == 4'h0)
    );

// Down decrements Q when Up is low and Q is not at zero.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && Down && (Q != 4'h0) |=> (Q == ($past(Q) - 4'h1))
    );

// Down wraps Q from 0 back to 15 when Up is low.
    check_down_wrap: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && Down && (Q == 4'h0) |=> (Q == 4'hF)
    );

// Q holds its value when neither Up nor Down is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && !Down |=> (Q == $past(Q))
    );

// X must implement ((A1 | A2) & B1 & C1).
    check_output_function: assert property (
        @(posedge clk) X === (((A1 | A2) & B1) & C1)
    );

// X high requires B1 high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires C1 high.
    check_x_high_requires_c1: assert property (
        @(posedge clk) X |-> C1
    );

// X high requires at least one of A1 or A2 high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both OR inputs low force X low.
    check_or_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// A1 with B1 and C1 high drives X high.
    check_a1_path_drives_x: assert property (
        @(posedge clk) (A1 && B1 && C1) |-> X
    );

// A2 with B1 and C1 high drives X high.
    check_a2_path_drives_x: assert property (
        @(posedge clk) (A2 && B1 && C1) |-> X
    );

// S=00 routes C to Y.
    check_select_00_routes_c: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y === C)
    );

// S=01 routes D to Y.
    check_select_01_routes_d: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y === D)
    );

// S=10 routes A to Y.
    check_select_10_routes_a: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y === A)
    );

// S=11 routes B to Y.
    check_select_11_routes_b: assert property (
        @(posedge clk) (S == 2'b11) |-> (Y === B)
    );

// X matches the implemented sum-of-products function.
    check_x_function: assert property (
        @(posedge clk) X === ((A1 & A2 & A3) | (B1 & B2))
    );

// The A-side 3-input AND drives X high.
    check_a_product_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// The B-side 2-input AND drives X high.
    check_b_product_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// X is low when neither AND term is active.
    check_no_product_means_x_low: assert property (
        @(posedge clk) (!(A1 & A2 & A3) && !(B1 & B2)) |-> !X
    );

// add reflects the 4-bit sum of A and B.
    check_add_matches_sum: assert property (
        @(posedge clk) add == ((A + B) & 4'hF)
    );

// sub reflects the 4-bit difference of A and B.
    check_sub_matches_difference: assert property (
        @(posedge clk) sub == ((A - B) & 4'hF)
    );

// adding zero leaves A unchanged.
    check_add_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (add == A)
    );

// subtracting zero leaves A unchanged.
    check_sub_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (sub == A)
    );

// equal operands subtract to zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (A == B) |-> (sub == 4'd0)
    );

// X equals the AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high drives X high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// Any low input drives X low.
    check_any_low_drives_x_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !X
    );

// X high requires all inputs high.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// X low requires at least one input low.
    check_x_low_requires_some_input_low: assert property (
        @(posedge clk) !X |-> (!A || !B || !C || !D)
    );

// RTL is combinational and has no native clock or reset; sample it on clk.

    // min must match the RTL's nested minimum calculation.
    check_min_matches_rtl_function: assert property (
        @(posedge clk)
        min == ((((a < b) ? a : b) < ((c < d) ? c : d)) ? ((a < b) ? a : b) : ((c < d) ? c : d))
    );

// min must be less than or equal to every input.
    check_min_le_all_inputs: assert property (
        @(posedge clk)
        (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

// min must equal one of the four inputs.
    check_min_matches_an_input: assert property (
        @(posedge clk)
        (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is a minimum value, min must equal a.
    check_a_drives_min_when_lowest: assert property (
        @(posedge clk)
        (a <= b && a <= c && a <= d) |-> (min == a)
    );

// If b is a minimum value, min must equal b.
    check_b_drives_min_when_lowest: assert property (
        @(posedge clk)
        (b <= a && b <= c && b <= d) |-> (min == b)
    );

// If c is a minimum value, min must equal c.
    check_c_drives_min_when_lowest: assert property (
        @(posedge clk)
        (c <= a && c <= b && c <= d) |-> (min == c)
    );

// If d is a minimum value, min must equal d.
    check_d_drives_min_when_lowest: assert property (
        @(posedge clk)
        (d <= a && d <= b && d <= c) |-> (min == d)
    );

// free3 with tm_count of 3 selects increment 3.
    check_free3_tm3_increment3: assert property (
        @(posedge clk)
        (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// free2 with tm_count of 2 or 3 selects increment 2 when the free3 case is absent.
    check_free2_high_count_increment2: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10)) |-> (fifowp_inc == 4'b0010)
    );

// Any remaining nonzero tm_count selects increment 1.
    check_fallback_nonzero_count_increment1: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) &&
         !(free2 && (tm_count >= 2'b10)) &&
         (tm_count >= 2'b01)) |-> (fifowp_inc == 4'b0001)
    );

// tm_count of 0 selects increment 0.
    check_zero_count_increment0: assert property (
        @(posedge clk)
        (tm_count == 2'b00) |-> (fifowp_inc == 4'b0000)
    );

// Output 3 only occurs for free3 with tm_count of 3.
    check_increment3_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0011) |-> (free3 && (tm_count == 2'b11))
    );

// Output 2 only occurs for the second branch condition.
    check_increment2_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0010) |-> (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10))
    );

// Output 1 only occurs for the third branch condition.
    check_increment1_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0001) |-> (!(free3 && (tm_count == 2'b11)) &&
                                     !(free2 && (tm_count >= 2'b10)) &&
                                     (tm_count >= 2'b01))
    );

// Output 0 only occurs when tm_count is 0.
    check_increment0_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0000) |-> (tm_count == 2'b00)
    );

// SUM implements A XOR B XOR inverted CIN.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT implements (A&B) | (A&~CIN) | (B&~CIN).
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// With CIN high, SUM reduces to A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) CIN |-> (SUM == (A ^ B))
    );

// With CIN high, COUT reduces to A AND B.
    check_cout_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A & B))
    );

// With CIN low, SUM reduces to XNOR of A and B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (SUM == ~(A ^ B))
    );

// With CIN low, COUT reduces to OR of A and B.
    check_cout_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (COUT == (A | B))
    );

// When A and B match, SUM equals inverted CIN.
    check_sum_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == ~CIN)
    );

// When A and B differ, SUM equals CIN.
    check_sum_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (SUM == CIN)
    );

// When A and B match, COUT equals A.
    check_cout_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (COUT == A)
    );

// When A and B differ, COUT equals inverted CIN.
    check_cout_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (COUT == ~CIN)
    );

// Reset forces count to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// When enabled, count increments by one modulo 4.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 2'b01))
    );

// When not enabled, count holds its previous value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// A max count of 3 wraps back to 0 when enabled.
    check_wraps_from_three_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// out1 must always mirror the low byte of in.
    check_splitter_lower_byte: assert property (
        @(posedge clk) out1 == in[7:0]
    );

// out2 must always mirror the high byte of in.
    check_splitter_upper_byte: assert property (
        @(posedge clk) out2 == in[15:8]
    );

// EQ matches the all-inputs-equal comparison.
    check_eq_definition: assert property (
        @(posedge clk) EQ == ((A == B) && (B == C) && (C == D))
    );

// GT matches the comparator decision logic.
    check_gt_definition: assert property (
        @(posedge clk) GT == ((A > B) || ((A == B) && (C > D)))
    );

// Equal inputs force GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

// A greater than B forces GT high.
    check_a_greater_b_sets_gt: assert property (
        @(posedge clk) (A > B) |-> GT
    );

// A less than B forces GT low.
    check_a_less_b_clears_gt: assert property (
        @(posedge clk) (A < B) |-> !GT
    );

// With A tied to B, C greater than D forces GT high.
    check_tie_breaker_sets_gt: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> GT
    );

// With A tied to B, C not greater than D forces GT low.
    check_tie_breaker_clears_gt: assert property (
        @(posedge clk) ((A == B) && (C <= D)) |-> !GT
    );

// When A equals B, GT can only come from C greater than D.
    check_gt_with_equal_ab_requires_c_greater_d: assert property (
        @(posedge clk) (GT && (A == B)) |-> (C > D)
    );

// When A differs from B, GT can only come from A greater than B.
    check_gt_with_unequal_ab_requires_a_greater_b: assert property (
        @(posedge clk) (GT && (A != B)) |-> (A > B)
    );

// Terminal count resets cnt_100M and raises Core.
    check_core_pulse_on_terminal_count: assert property (
        @(posedge slowest_sync_clk)
        (cnt_100M == 32'd100_000_000) |=> (cnt_100M == 32'd0 && Core == 1'b1)
    );

// Non-terminal count increments cnt_100M and keeps Core low.
    check_core_low_on_nonterminal_count: assert property (
        @(posedge slowest_sync_clk)
        (cnt_100M != 32'd100_000_000) |=> (cnt_100M == ($past(cnt_100M) + 32'd1) && Core == 1'b0)
    );

// cnt_core increments when Core is sampled high.
    check_cnt_core_increments_when_core_high: assert property (
        @(posedge lpf_int)
        (Core == 1'b1) |=> (cnt_core == ($past(cnt_core) + 8'd1))
    );

// cnt_core holds when Core is sampled low.
    check_cnt_core_holds_when_core_low: assert property (
        @(posedge lpf_int)
        (Core == 1'b0) |=> (cnt_core == $past(cnt_core))
    );

// bsr is driven low after each lpf_int edge.
    check_bsr_clears_each_lpf_tick: assert property (
        @(posedge lpf_int)
        1'b1 |=> (bsr == 1'b0)
    );

// cnt_bsr increments when bsr is sampled high.
    check_cnt_bsr_increments_when_bsr_high: assert property (
        @(posedge lpf_int)
        (bsr == 1'b1) |=> (cnt_bsr == ($past(cnt_bsr) + 6'd1) && pr == 1'b0)
    );

// cnt_bsr holds when bsr is sampled low.
    check_cnt_bsr_holds_when_bsr_low: assert property (
        @(posedge lpf_int)
        (bsr == 1'b0) |=> (cnt_bsr == $past(cnt_bsr))
    );

// pr is driven low after each lpf_int edge.
    check_pr_clears_each_lpf_tick: assert property (
        @(posedge lpf_int)
        1'b1 |=> (pr == 1'b0)
    );

// When enabled, Y matches the implemented logic cone.
    check_enabled_output_matches_implemented_logic: assert property (
        @(posedge clk) (EN === 1'b0) |-> (Y === (D3 & SEL[0] & SEL[1]))
    );

// With EN low and SEL[1] low, the final stage forces Y low.
    check_sel1_low_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL[1] === 1'b0) |-> (Y === 1'b0)
    );

// With EN low and SEL equal 2'b10, Y remains low.
    check_sel_10_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b10) |-> (Y === 1'b0)
    );

// With EN low and SEL equal 2'b11, Y follows D3.
    check_sel_11_passes_d3_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b11) |-> (Y === D3)
    );

// Sampled active-low reset forces count to zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// First clock after a sampled reset low sets count to one.
    check_reset_release_starts_at_one: assert property (
        @(posedge clk) disable iff (!rst) (!$past(rst)) |-> (count == 4'd1)
    );

// With reset high on consecutive samples, count increments or restarts from one after an async reset pulse.
    check_running_step_or_restart: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> ((count == ($past(count) + 4'd1)) || (count == 4'd1))
    );

// A sampled zero while running can only come from wrapping past 15.
    check_zero_only_after_wrap: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );

// A sampled zero while running advances to one on the next clock.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'd0)) |-> (count == 4'd1)
    );

// X must always equal A XOR B.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

// X must be low when both inputs are low.
    check_both_low_output_low: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// X must be high when only B is high.
    check_only_b_high_output_high: assert property (
        @(posedge clk) (!A && B) |-> X
    );

// X must be high when only A is high.
    check_only_a_high_output_high: assert property (
        @(posedge clk) (A && !B) |-> X
    );

// X must be low when both inputs are high.
    check_both_high_output_low: assert property (
        @(posedge clk) (A && B) |-> !X
    );

// and_out and xor_out cannot be high on the same bit.
  check_and_xor_mutex: assert property (
    @(posedge clk) disable iff (1'b0) (and_out & xor_out) == '0
  );

// When sel selects x_axis, data must match x_axis.
    check_select_x_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b00) |-> (data == x_axis)
    );

// When sel selects y_axis, data must match y_axis.
    check_select_y_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b01) |-> (data == y_axis)
    );

// When sel selects z_axis, data must match z_axis.
    check_select_z_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b10) |-> (data == z_axis)
    );

// When sel selects temp_data, data must be zero-extended temp_data.
    check_select_temp_data: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b11) |-> (data == {8'h00, temp_data})
    );

// Reset clears the registered result on the following cycle.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

// max matches the nested comparator implementation.
    check_nested_compare_equivalence: assert property (
        @(posedge clk)
        max == ((((a > b) ? a : b) > ((c > d) ? c : d)) ? ((a > b) ? a : b) : ((c > d) ? c : d))
    );

// max is never smaller than a.
    check_max_ge_a: assert property (
        @(posedge clk)
        max >= a
    );

// max is never smaller than b.
    check_max_ge_b: assert property (
        @(posedge clk)
        max >= b
    );

// max is never smaller than c.
    check_max_ge_c: assert property (
        @(posedge clk)
        max >= c
    );

// max is never smaller than d.
    check_max_ge_d: assert property (
        @(posedge clk)
        max >= d
    );

// max must equal one of the four inputs.
    check_max_matches_an_input: assert property (
        @(posedge clk)
        (max == a) || (max == b) || (max == c) || (max == d)
    );

// If a is at least as large as all others, max equals a.
    check_a_is_max_value: assert property (
        @(posedge clk)
        ((a >= b) && (a >= c) && (a >= d)) |-> (max == a)
    );

// If b is at least as large as all others, max equals b.
    check_b_is_max_value: assert property (
        @(posedge clk)
        ((b >= a) && (b >= c) && (b >= d)) |-> (max == b)
    );

// If c is at least as large as all others, max equals c.
    check_c_is_max_value: assert property (
        @(posedge clk)
        ((c >= a) && (c >= b) && (c >= d)) |-> (max == c)
    );

// If d is at least as large as all others, max equals d.
    check_d_is_max_value: assert property (
        @(posedge clk)
        ((d >= a) && (d >= b) && (d >= c)) |-> (max == d)
    );

// Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// When load is asserted, count updates with data on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

// When load is deasserted, count increments by one on the next clock.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

// Incrementing from 4'hF wraps the 4-bit counter back to zero.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

// out is the 4-bit sum of in1 and in2.
    check_out_matches_sum: assert property (
        @(posedge clk) out == (in1 + in2)
    );

// max_out follows the RTL max expression using out and the sum.
    check_max_out_matches_rtl_max_expr: assert property (
        @(posedge clk) max_out == ((out > (in1 + in2)) ? out : (in1 + in2))
    );

// Since out is assigned from the sum, max_out must equal out.
    check_max_out_equals_out: assert property (
        @(posedge clk) max_out == out
    );

// max_out also equals the computed 4-bit sum.
    check_max_out_matches_sum: assert property (
        @(posedge clk) max_out == (in1 + in2)
    );

// The output vector updates as a shift register driven only by the previous in[0].
    check_output_vector_update: assert property (
        @(posedge clk) 1'b1 |=> out == { $past(in[0]), $past(out[99:1]) }
    );

// The output MSB captures the previous cycle value of in[0].
    check_output_msb_from_input0: assert property (
        @(posedge clk) 1'b1 |=> out[99] == $past(in[0])
    );

// The lower 99 output bits shift from the previous cycle's higher output bits.
    check_output_lower_bits_shift: assert property (
        @(posedge clk) 1'b1 |=> out[98:0] == $past(out[99:1])
    );

// RTL has no clock or reset; clk is an external sampling clock.

    // Output equals the bitwise AND of the two inputs.
    check_out_matches_bitwise_and: assert property (
        @(posedge clk) out == (A & B)
    );

// A value of zero forces the output to zero.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) (A == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// B value of zero forces the output to zero.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) (B == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// All ones on A makes the output follow B.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |-> (out == B)
    );

// All ones on B makes the output follow A.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (out == A)
    );

// Any high output bit must also be high in A.
    check_output_ones_subset_of_a: assert property (
        @(posedge clk) ((out & ~A) == 32'h0000_0000)
    );

// Any high output bit must also be high in B.
    check_output_ones_subset_of_b: assert property (
        @(posedge clk) ((out & ~B) == 32'h0000_0000)
    );

// Equal inputs pass through unchanged to the output.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (out == A)
    );

// RGB outputs are forced to zero when either sync is high.
    check_rgb_zero_when_sync_not_both_low: assert property (
        @(posedge clk) disable iff (rst)
        !(hsync == 1'b0 && vsync == 1'b0)
        |=> (r == 8'h00 && g == 8'h00 && b == 8'h00)
    );

// Clock is CLK1; there is no reset in the RTL.

    // Read data always reflects the selected memory bit.
    check_read_data_matches_mem: assert property (
        @(posedge CLK1) B1DATA == mem[B1ADDR]
    );

// With write enable low, the memory contents hold.
    check_no_write_holds_mem: assert property (
        @(posedge CLK1) !A1EN |=> $stable(mem)
    );

// A write updates memory exactly at the addressed bit.
    check_write_updates_full_mem_state: assert property (
        @(posedge CLK1)
        A1EN |=> mem == (($past(mem) & ~(32'h1 << $past(A1ADDR))) |
                         ({31'b0, $past(A1DATA)} << $past(A1ADDR)))
    );

// A write stores A1DATA into the addressed location.
    check_write_updates_addressed_bit: assert property (
        @(posedge CLK1) A1EN |=> mem[$past(A1ADDR)] == $past(A1DATA)
    );

// A write does not change any unaddressed memory bits.
    check_write_preserves_unaddressed_bits: assert property (
        @(posedge CLK1)
        A1EN |=> (((mem ^ $past(mem)) & ~(32'h1 << $past(A1ADDR))) == 32'h0)
    );

// Writing the existing value leaves memory unchanged.
    check_same_value_write_keeps_mem_stable: assert property (
        @(posedge CLK1) (A1EN && (A1DATA == mem[A1ADDR])) |=> $stable(mem)
    );

// A subsequent read of the written address returns the stored data.
    check_read_after_write_same_address: assert property (
        @(posedge CLK1)
        A1EN |=> ((B1ADDR != $past(A1ADDR)) || (B1DATA == $past(A1DATA)))
    );

// Addition opcode returns A + B, truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((A + B) & 8'hff))
    );

// Subtraction opcode returns A - B, truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((A - B) & 8'hff))
    );

// Division by zero forces the result to zero.
    check_div_by_zero: assert property (
        @(posedge clk) (op == 2'b11 && B == 8'h00) |-> (result == 8'h00)
    );

// Reset clears all stages on the clock edge where reset is sampled high.
    check_reset_clears_all_stages: assert property (
        @(posedge shift_clk)
        reset |=> (q0 == 4'b0000 && q1 == 4'b0000 && q2 == 4'b0000 && q3 == 4'b0000)
    );

// q0 captures data_in on each non-reset clock.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q0 == $past(data_in))
    );

// q1 captures the previous value of q0 on each non-reset clock.
    check_q1_shifts_q0: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q1 == $past(q0))
    );

// q2 captures the previous value of q1 on each non-reset clock.
    check_q2_shifts_q1: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q2 == $past(q1))
    );

// q3 captures the previous value of q2 on each non-reset clock.
    check_q3_shifts_q2: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q3 == $past(q2))
    );

// out matches the full case mapping.
    check_output_function: assert property (
        @(posedge clk)
        out == ((shift_amt == 2'b00) ? in :
                (shift_amt == 2'b01) ? ((dir == 1'b1) ? {in[2:0], in[3]} : {in[1:0], in[3:2]}) :
                (shift_amt == 2'b10) ? ((dir == 1'b1) ? {in[1:0], in[3:2]} : {in[2:0], in[3]}) :
                                      {in[0], in[3:1]})
    );

// shift_amt 00 passes in directly to out.
    check_shift_amt_00_passthrough: assert property (
        @(posedge clk)
        (shift_amt == 2'b00) |-> (out == in)
    );

// shift_amt 01 dir 1, or shift_amt 10 dir 0, selects {in[2:0],in[3]}.
    check_rotate_pattern_2301: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b1)) ||
         ((shift_amt == 2'b10) && (dir == 1'b0)))
        |-> (out == {in[2:0], in[3]})
    );

// shift_amt 01 dir 0, or shift_amt 10 dir 1, selects {in[1:0],in[3:2]}.
    check_rotate_pattern_0123: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b0)) ||
         ((shift_amt == 2'b10) && (dir == 1'b1)))
        |-> (out == {in[1:0], in[3:2]})
    );

// shift_amt 11 selects {in[0],in[3:1]} regardless of dir.
    check_shift_amt_11_mapping: assert property (
        @(posedge clk)
        (shift_amt == 2'b11) |-> (out == {in[0], in[3:1]})
    );

// When SEL is 0, Y must match A.
    check_select_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

// When SEL is not 0, Y must match B.
    check_select_b: assert property (
        @(posedge clk) (SEL !== 1'b0) |-> (Y === B)
    );

// Checks incrementing 4'hF produces wraparound with carry.
    check_increment_overflow: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0000) && (Cout == 1'b1))
    );

// Reset forces all synchronized reset outputs low.
    check_reset_forces_low: assert property (
        @(posedge clk)
        !reset_n |-> (reset_n_sync == ALL_ZERO)
    );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// A single-stage case stays high one clock later.
            check_release_stays_high_next_cycle: assert property (
                @(posedge clk) disable iff (!reset_n)
                $rose(reset_n) |-> ##1 (reset_n_sync == ALL_ONE)
            );

// Reset forces the counter to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// Load updates count with data_in on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// Load has priority over increment when both are asserted.
    check_load_priority_over_increment: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (count == $past(data_in))
    );

// Without load, up_down high increments the counter.
    check_increment_operation: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// Without load, up_down low decrements the counter.
    check_decrement_operation: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Increment wraps from 4'hF to 4'h0.
    check_increment_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrement wraps from 4'h0 to 4'hF.
    check_decrement_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Output always equals the inversion of the input.
    check_inversion_function: assert property (
        @(posedge clk) Y === ~A
    );

// A low input drives Y high.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input drives Y low.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// A known input produces a known output.
    check_known_input_known_output: assert property (
        @(posedge clk) !$isunknown(A) |-> !$isunknown(Y)
    );

// Combinational RTL with no reset; clk is a sampling clock.

    // Addition mode returns the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((num1 + num2) & 8'hFF))
    );

// Subtraction mode returns the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((num1 - num2) & 8'hFF))
    );

// Division by zero forces the result to zero.
    check_division_by_zero_result: assert property (
        @(posedge clk) (op == 2'b11 && num2 == 8'h00) |-> (result == 8'h00)
    );

// Blank forces the blanked display pattern.
    check_blank_output: assert property (
        @(posedge clk) blank |-> (s7 == ~7'b0000000)
    );

// Minus selects the minus pattern when not blanked.
    check_minus_output: assert property (
        @(posedge clk) (!blank && minus) |-> (s7 == ~7'b1000000)
    );

// Value 0 selects the 0 segment pattern.
    check_value_0_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h0)) |-> (s7 == ~7'b0111111)
    );

// Value 1 selects the 1 segment pattern.
    check_value_1_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h1)) |-> (s7 == ~7'b0000110)
    );

// Value 2 selects the 2 segment pattern.
    check_value_2_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h2)) |-> (s7 == ~7'b1011011)
    );

// Value 3 selects the 3 segment pattern.
    check_value_3_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h3)) |-> (s7 == ~7'b1001111)
    );

// Value 4 selects the 4 segment pattern.
    check_value_4_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h4)) |-> (s7 == ~7'b1100110)
    );

// Value 5 selects the 5 segment pattern.
    check_value_5_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h5)) |-> (s7 == ~7'b1101101)
    );

// Value 6 selects the 6 segment pattern.
    check_value_6_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h6)) |-> (s7 == ~7'b1111101)
    );

// Value 7 selects the 7 segment pattern.
    check_value_7_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h7)) |-> (s7 == ~7'b0000111)
    );

// Value 8 selects the 8 segment pattern.
    check_value_8_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h8)) |-> (s7 == ~7'b1111111)
    );

// Value 9 selects the 9 segment pattern.
    check_value_9_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h9)) |-> (s7 == ~7'b1101111)
    );

// Value A selects the A segment pattern.
    check_value_a_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hA)) |-> (s7 == ~7'b1110111)
    );

// Value B selects the B segment pattern.
    check_value_b_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hB)) |-> (s7 == ~7'b1111100)
    );

// Value C selects the C segment pattern.
    check_value_c_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hC)) |-> (s7 == ~7'b0111001)
    );

// Value D selects the D segment pattern.
    check_value_d_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hD)) |-> (s7 == ~7'b1011110)
    );

// Value E selects the E segment pattern.
    check_value_e_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hE)) |-> (s7 == ~7'b1111001)
    );

// Value F selects the F segment pattern.
    check_value_f_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hF)) |-> (s7 == ~7'b1110001)
    );

// RTL is combinational, so assertions are sampled on an external clock.

    // Checks left mode performs two successive left shifts.
    check_left_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b0) |-> (out == ((in << shift) << shift))
    );

// Checks right mode performs two successive right shifts.
    check_right_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b1) |-> (out == ((in >> shift) >> shift))
    );

// Checks a zero shift passes the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift == 4'd0) |-> (out == in)
    );

// Checks shifts of 8 or more clear the 16-bit result after two stages.
    check_large_shift_clears_output: assert property (
        @(posedge clk)
        (shift >= 4'd8) |-> (out == 16'h0000)
    );

// Checks left shifts insert zeros into the low bits.
    check_left_shift_zero_fills_low_bits: assert property (
        @(posedge clk)
        (dir == 1'b0 && shift != 4'd0) |-> (out[1:0] == 2'b00)
    );

// Checks right shifts insert zeros into the high bits.
    check_right_shift_zero_fills_high_bits: assert property (
        @(posedge clk)
        (dir == 1'b1 && shift != 4'd0) |-> (out[15:14] == 2'b00)
    );

// Reset drives out to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

// Load updates out from data[3:0].
    check_load_updates_out: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (out == $past(data[3:0]))
    );

// Load has priority over select.
    check_load_priority_over_select: assert property (
        @(posedge clk) disable iff (reset)
        (load && select) |=> (out == $past(data[3:0]))
    );

// Select rotates in when load is low.
    check_select_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && select) |=> (out == $past({in[2:0], in[3]}))
    );

// Default path rotates in when both controls are low.
    check_default_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !select) |=> (out == $past({in[0], in[3:1]}))
    );

// Every non-reset cycle follows the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (
            out == ($past(load) ? $past(data[3:0]) :
                    ($past(select) ? $past({in[2:0], in[3]}) :
                                     $past({in[0], in[3:1]})))
        )
    );

// Input value 0 maps to output 0.
    check_zero_input_mapping: assert property (
        @(posedge clk) (input_val == 10'd0) |-> (binary_val == 4'd0)
    );

// Input values 1 through 8 map to their 4-bit value.
    check_midrange_input_mapping: assert property (
        @(posedge clk) ((input_val >= 10'd1) && (input_val <= 10'd8)) |-> (binary_val == input_val[3:0])
    );

// Input value 9 maps to output 9.
    check_nine_input_mapping: assert property (
        @(posedge clk) (input_val == 10'd9) |-> (binary_val == 4'd9)
    );

// Unsupported input values drive the default zero output.
    check_default_zero_for_invalid_inputs: assert property (
        @(posedge clk) (input_val > 10'd9) |-> (binary_val == 4'd0)
    );

// The output never exceeds the highest encoded value.
    check_output_range: assert property (
        @(posedge clk) (binary_val <= 4'd9)
    );

// X matches the implemented combined logic.
    check_output_equation: assert property (
        @(posedge clk) X == (A1 & A2 & ~B1_N & ~C1)
    );

// When all required terms are enabled, X is high.
    check_enable_combination_sets_x: assert property (
        @(posedge clk) (A1 & A2 & ~B1_N & ~C1) |-> X
    );

// A high X requires all enabling conditions.
    check_x_high_requires_all_enables: assert property (
        @(posedge clk) X |-> (A1 & A2 & ~B1_N & ~C1)
    );

// A low A1 forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A high B1_N forces X low.
    check_b1_n_high_forces_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// A high C1 forces X low.
    check_c1_high_forces_x_low: assert property (
        @(posedge clk) C1 |-> !X
    );

// When reset is high, count must be zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// When count is 9, it wraps to 0 on the next clock if reset stays low.
    check_wrap_from_nine: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'd9) |=> (count == 4'd0)
    );

// When count is not 9, it increments by 1 on the next clock if reset stays low.
    check_increment_when_not_nine: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'd9) |=> (count == ($past(count) + 4'd1))
    );

// When load is high, bit 3 captures input bit 3 on the next clock.
    check_load_captures_bit3: assert property (
        @(posedge clk) load |=> data_out[3] == $past(data_in[3])
    );

// When load is high, bit 2 captures input bit 2 on the next clock.
    check_load_captures_bit2: assert property (
        @(posedge clk) load |=> data_out[2] == $past(data_in[2])
    );

// When load is high, bit 1 captures input bit 1 on the next clock.
    check_load_captures_bit1: assert property (
        @(posedge clk) load |=> data_out[1] == $past(data_in[1])
    );

// When load is high, bit 0 captures input bit 0 on the next clock.
    check_load_captures_bit0: assert property (
        @(posedge clk) load |=> data_out[0] == $past(data_in[0])
    );

// When load is low, bit 3 takes the previous bit 2 on the next clock.
    check_rotate_bit3_from_bit2: assert property (
        @(posedge clk) !load |=> data_out[3] == $past(data_out[2])
    );

// When load is low, bit 2 takes the previous bit 1 on the next clock.
    check_rotate_bit2_from_bit1: assert property (
        @(posedge clk) !load |=> data_out[2] == $past(data_out[1])
    );

// When load is low, bit 1 takes the previous bit 0 on the next clock.
    check_rotate_bit1_from_bit0: assert property (
        @(posedge clk) !load |=> data_out[1] == $past(data_out[0])
    );

// When load is low, bit 0 takes the previous bit 3 on the next clock.
    check_rotate_bit0_from_bit3: assert property (
        @(posedge clk) !load |=> data_out[0] == $past(data_out[3])
    );

// Y implements A & B & ~C.
    check_output_function: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

// Y can only be high when A and B are high and C is low.
    check_y_high_requires_inputs: assert property (
        @(posedge clk) Y |-> (A && B && !C)
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// A and B high with C low forces Y high.
    check_all_true_inputs_drive_y_high: assert property (
        @(posedge clk) (A && B && !C) |-> Y
    );

// With A and B high, Y equals the inverse of C.
    check_ab_high_makes_y_follow_not_c: assert property (
        @(posedge clk) (A && B) |-> (Y == !C)
    );

// With C low, Y matches A AND B.
    check_c_low_makes_y_follow_a_and_b: assert property (
        @(posedge clk) !C |-> (Y == (A & B))
    );

// Y matches the RTL XNOR function of A and B.
    check_y_matches_xnor_function: assert property (
        @(posedge clk) (Y == ~(A ^ B))
    );

// A=0 and B=0 drive Y high.
    check_00_outputs_high: assert property (
        @(posedge clk) ((!A && !B) |-> (Y == 1'b1))
    );

// A=0 and B=1 drive Y low.
    check_01_outputs_low: assert property (
        @(posedge clk) ((!A && B) |-> (Y == 1'b0))
    );

// A=1 and B=0 drive Y low.
    check_10_outputs_low: assert property (
        @(posedge clk) ((A && !B) |-> (Y == 1'b0))
    );

// A=1 and B=1 drive Y high.
    check_11_outputs_high: assert property (
        @(posedge clk) ((A && B) |-> (Y == 1'b1))
    );

// gated_clk is low just before each src_clk rising edge.
    check_gated_clk_low_before_src_clk_rise: assert property (
        @(posedge src_clk) (gated_clk == 1'b0)
    );

// Output matches the mux select function.
    check_mux_function: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// When select is low, the output routes A.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

// When select is high, the output routes B.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

// The output is always equal to one of the two inputs.
    check_output_is_input_a_or_b: assert property (
        @(posedge clk) (Y == A) || (Y == B)
    );

// If both inputs match, the output matches that value.
    check_equal_inputs_produce_same_output: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// If output differs from A, B must be selected and drive the output.
    check_output_differs_from_a_only_when_b_selected: assert property (
        @(posedge clk) (Y != A) |-> (SEL && (Y == B))
    );

// If output differs from B, A must be selected and drive the output.
    check_output_differs_from_b_only_when_a_selected: assert property (
        @(posedge clk) (Y != B) |-> ((!SEL) && (Y == A))
    );

// MO must match the mux expression implemented in the RTL.
    check_mux_equation: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

// A high select routes B to the output.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

// A low select routes A to the output.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

// Equal inputs make the output independent of select.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );
